    const style = getQuestStyles(quest);

    const handleClaim = (e: React.MouseEvent) => {
        e.stopPropagation();
        setConfirmState({
            isOpen: true,
            title: "Получить Награду",
            message: "Деяние действительно совершено? Бездна ждет завершения.",
            onConfirm: () => onUpdateStatus(quest.id, QuestStatus.COMPLETED)
        });
    };

    return (
        <div className="relative group perspective-1000 mb-4 isolate">
            <ConfirmationModal 
                isOpen={confirmState.isOpen}
                onClose={() => setConfirmState({...confirmState, isOpen: false})}
                onConfirm={confirmState.onConfirm}
                title={confirmState.title}
                message={confirmState.message}
            />

            <div 
                onClick={() => setIsOpen(!isOpen)}
                className={`
                    relative z-10 w-full cursor-pointer rounded-xl overflow-hidden
                    ${style.container} ${style.glow}
                    transform hover:-translate-y-1
                `}
            >
                {/* Magical Scanline effect */}
                <div className="absolute inset-0 bg-gradient-to-b from-white/5 to-transparent opacity-0 group-hover:opacity-20 pointer-events-none transition-opacity duration-500"></div>

                {/* Header Section */}
                <div className="p-4 relative">
                     <div className="flex justify-between items-start gap-3">
                         <div className="flex-1">
                             {/* Quest Type Indicator */}
                             <div className="flex items-center gap-2 mb-1">
                                 <div className={`w-1.5 h-1.5 rounded-full ${style.accent} shadow-[0_0_5px_currentColor]`}></div>
                                 <span className={`text-[9px] uppercase tracking-[0.2em] font-bold ${style.text} opacity-70`}>
                                     {TYPE_LABELS[quest.type]}
                                 </span>
                             </div>
                             <h4 className={`font-fantasy font-bold text-lg leading-tight ${style.title}`}>{quest.title}</h4>
                         </div>

                         {/* Status / Pins */}
                         <div className="flex -space-x-2">
                             {isTaken ? (
                                 quest.details.acceptedBy.map((name, idx) => {
                                     const char = allCharacters.find(c => c.name === name);
                                     const avatar = char?.data?.identity?.avatar_url || char?.data?.avatar_url;

                                     return (
                                        <div 
                                            key={`${quest.id}-pin-${idx}`}
                                            className={`w-6 h-6 rounded-full border flex items-center justify-center text-[9px] font-bold ring-2 ring-black/50 ${getPinColor(name, idx)} overflow-hidden bg-black`}
                                            title={name}
                                        >
                                             {avatar ? (
                                                 <img src={avatar} alt={name} className="w-full h-full object-cover" />
                                             ) : (
                                                 name.charAt(0)
                                             )}
                                        </div>
                                     );
                                 })
                             ) : (
                                 <div className={`w-6 h-6 rounded-full border border-white/10 bg-white/5 flex items-center justify-center animate-pulse`}>
                                     <Sparkles size={10} className={style.text} />
                                 </div>
                             )}
                         </div>
                     </div>

                     {isAdmin && (
                        <button 
                            onClick={(e) => { e.stopPropagation(); onEdit(quest); }}
                            className="absolute top-2 right-2 p-1 text-slate-500 hover:text-white transition-colors opacity-0 group-hover:opacity-100"
                        >
                            <Edit2 size={12} />
                        </button>
                     )}
                </div>

                {/* Expandable Content */}
                <div className={`
                    bg-black/40
                    transition-all duration-500 ease-in-out overflow-hidden
                    ${isOpen ? 'max-h-[500px] opacity-100' : 'max-h-0 opacity-0'}
                `}>
                    <div className="p-4 pt-0">
                        <div className={`h-px w-full bg-gradient-to-r from-transparent via-current to-transparent opacity-20 my-3 ${style.text}`} />

                        <p className={`text-sm leading-relaxed whitespace-pre-wrap font-sans ${style.text}`}>{quest.description}</p>

                        <div className="mt-4 space-y-3">
                            <div className="flex items-center gap-2">
                                <span className="text-[10px] uppercase tracking-widest text-slate-500">Награда</span>
                                <span className={`text-xs font-bold ${style.title}`}>{quest.reward}</span>
                            </div>

                            {/* Accepted By List with Colors */}
                            {isTaken && quest.details.acceptedBy.length > 0 && (
                                <div className="border-t border-white/5 pt-2 mt-2">
                                     <span className="text-[10px] uppercase tracking-widest text-slate-500 block mb-1">Приняли</span>
                                     <div className="flex flex-wrap gap-2">
                                         {quest.details.acceptedBy.map((name, idx) => {
                                             const char = allCharacters.find(c => c.name === name);
                                             const avatar = char?.data?.identity?.avatar_url || char?.data?.avatar_url;

                                             return (
                                                 <div key={idx} className="flex items-center gap-1.5 bg-black/20 px-2 py-1 rounded border border-white/5">
                                                     <div className={`w-3 h-3 rounded-full ${getPinColor(name, idx)} shadow-[0_0_5px_currentColor] overflow-hidden bg-black`}>
                                                        {avatar && <img src={avatar} alt={name} className="w-full h-full object-cover" />}
                                                     </div>
                                                     <span className={`text-xs font-medium ${style.text}`}>{name}</span>
                                                 </div>
                                             );
                                         })}
                                     </div>
                                </div>
                            )}

                            <div className="flex justify-between items-end pt-2">
                                <div className="flex flex-col">
                                    <span className="text-[10px] uppercase tracking-widest text-slate-500">Заказчик</span>
                                    <span className={`text-xs italic ${style.text}`}>{quest.details.givenBy}</span>
                                </div>

                                <div className="flex gap-2" onClick={e => e.stopPropagation()}>
                                    {quest.status === QuestStatus.AVAILABLE && (
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); onOpenAcceptModal(quest.id); }}
                                            className="bg-violet-600/80 hover:bg-violet-500 text-white px-3 py-1.5 rounded text-xs font-bold uppercase tracking-wider shadow-[0_0_10px_rgba(139,92,246,0.4)] hover:shadow-[0_0_15px_rgba(139,92,246,0.6)] transition-all border border-violet-400/30 backdrop-blur-sm"
                                        >
                                            Принять Судьбу
                                        </button>
                                    )}
                                    {quest.status === QuestStatus.IN_PROGRESS && (
                                        <button 
                                            onClick={handleClaim}
                                            className="bg-emerald-600/80 hover:bg-emerald-500 text-white px-3 py-1.5 rounded text-xs font-bold uppercase tracking-wider shadow-[0_0_10px_rgba(16,185,129,0.4)] transition-all border border-emerald-400/30 backdrop-blur-sm flex items-center gap-1"
                                        >
                                            <CheckCircle size={12} /> Завершить
                                        </button>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
});

// --- Main Page Component ---

interface QuestBoardPageProps {
    isAdmin: boolean;
}

const QuestBoardPage: React.FC<QuestBoardPageProps> = ({ isAdmin }) => {
  const { quests, updateStatus, addQuest, acceptQuest, editQuest } = useQuests();
  const { characters } = useCharacters();

  // Mobile & Layout State
  const [activeColIndex, setActiveColIndex] = useState(1);
  const touchStartRef = useRef<{x: number, y: number} | null>(null);

  // Archive State
  const [isArchiveOpen, setIsArchiveOpen] = useState(false);
  const [expandedArchiveId, setExpandedArchiveId] = useState<string | null>(null);

  // Modal States
  const [isPostModalOpen, setIsPostModalOpen] = useState(false);
  const [editingQuestId, setEditingQuestId] = useState<string | null>(null); 
  const [acceptModalOpen, setAcceptModalOpen] = useState(false);
  const [selectedQuestId, setSelectedQuestId] = useState<string | null>(null);
  const [acceptNames, setAcceptNames] = useState<string[]>(['']);
  const [isCharSelectorOpen, setIsCharSelectorOpen] = useState(false);

  // Form State
  const [formQuest, setFormQuest] = useState<Partial<Quest>>({
      type: QuestType.PUBLIC,
      status: QuestStatus.AVAILABLE,
      alignment: 'Neutral',
      details: { givenBy: '', acceptedBy: [] }
  });
  const [isPlayerGiver, setIsPlayerGiver] = useState(false); 

  // Filter out Graveyard/Dead characters
  const activeCharacters = useMemo(() => {
      return characters.filter(c => {
          const faction = c.data?.identity?.faction || c.faction || '';
          const name = c.name || '';
          // Filter Graveyard/Могильник
          if (['graveyard', 'могильник'].includes(faction.toLowerCase())) return false;
          // Extra safety check if name implies dead
          if (name.includes('Dead') || name.includes('(Dead)')) return false;
          return true;
      });
  }, [characters]);

  const groupedCharacters = useMemo<Record<string, Character[]>>(() => {
      const groups: Record<string, Character[]> = {};
      activeCharacters.forEach(c => {
          const f = c.data?.identity?.faction || c.faction || 'Uncommon';
          if (!groups[f]) groups[f] = [];
          groups[f].push(c);
      });
      return groups;
  }, [activeCharacters]);

  // --- Handlers ---
  const handleTouchStart = (e: React.TouchEvent) => {
      touchStartRef.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
      if (!touchStartRef.current) return;
      const diffX = touchStartRef.current.x - e.changedTouches[0].clientX;
      const diffY = touchStartRef.current.y - e.changedTouches[0].clientY;
      if (Math.abs(diffX) > Math.abs(diffY)) {
          if (Math.abs(diffX) > 50) {
              if (diffX > 0) setActiveColIndex(prev => Math.min(prev + 1, columns.length - 1));
              else setActiveColIndex(prev => Math.max(prev - 1, 0));
          }
      }
      touchStartRef.current = null;
  };

  const handleUpdateStatus = useCallback((id: string, status: QuestStatus) => {
      updateStatus(id, status);
  }, [updateStatus]);

  const handleOpenAccept = useCallback((id: string) => {
      setSelectedQuestId(id);
      setAcceptNames(['']);
      setAcceptModalOpen(true);
  }, []);

  const handleEditClick = useCallback((quest: Quest) => {
      setEditingQuestId(quest.id);
      setFormQuest({ ...quest });
      const isChar = characters.some(c => c.name === quest.details.givenBy);
      setIsPlayerGiver(isChar);
      setIsPostModalOpen(true);
  }, [characters]);

  const handlePostSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if(formQuest.title && formQuest.description && formQuest.details) {
          let finalQuest = { ...formQuest };

          if (formQuest.type === QuestType.PERSONAL) {
              finalQuest.status = QuestStatus.IN_PROGRESS;
              finalQuest.details = {
                  ...finalQuest.details,
                  acceptedBy: [finalQuest.details!.givenBy]
              };
          }

          if (editingQuestId) {
              editQuest(editingQuestId, finalQuest);
          } else {
              addQuest(finalQuest as Omit<Quest, 'id'>);
          }

          setIsPostModalOpen(false);
          setEditingQuestId(null);
          setFormQuest({
             type: QuestType.PUBLIC, 
             status: QuestStatus.AVAILABLE, 
             alignment: 'Neutral',
             details: { givenBy: '', acceptedBy: [] } 
          });
          setIsPlayerGiver(false);
      }
  };

  const handleAcceptSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      const validNames = acceptNames.filter(n => n.trim() !== '');
      if(selectedQuestId && validNames.length > 0) {
          acceptQuest(selectedQuestId, validNames);
          setAcceptModalOpen(false);
      }
  };

  const handleRosterConfirm = (names: string[]) => {
      const current = new Set(acceptNames.filter(n => n.trim() !== ''));
      names.forEach(n => current.add(n));
      const combined = Array.from(current);
      if(combined.length === 0) combined.push('');
      setAcceptNames(combined);
  };

  const columns = useMemo(() => [
      { title: 'Личные', type: QuestType.PERSONAL, color: 'text-emerald-300', bg: 'bg-emerald-900/10' },
      { title: 'Фракционные', type: QuestType.FACTION, color: 'text-indigo-300', bg: 'bg-indigo-900/10' },
      { title: 'Публичные', type: QuestType.PUBLIC, color: 'text-slate-300', bg: 'bg-slate-900/10' }
  ], []);

  const completedQuests = useMemo(() => quests.filter(q => q.status === QuestStatus.COMPLETED), [quests]);

  return (
    <div 
        className="h-full flex flex-col overflow-hidden relative"
        onTouchStart={handleTouchStart}
        onTouchEnd={handleTouchEnd}
    >
       <CharacterSelector 
          isOpen={isCharSelectorOpen} 
          onClose={() => setIsCharSelectorOpen(false)} 
          onConfirm={handleRosterConfirm}
          alreadySelected={acceptNames}
       />

       {/* Unified Header */}
       <div className="bg-slate-900/90 backdrop-blur-md border-b border-violet-500/20 p-3 sticky top-0 z-20 flex flex-wrap gap-3 justify-between items-center shadow-lg shrink-0 min-h-[3.5rem]">
            <div className="flex items-center gap-4">
                <h2 className="text-xl font-fantasy text-transparent bg-clip-text bg-gradient-to-r from-violet-200 to-fuchsia-200 flex items-center gap-2 drop-shadow-sm shrink-0">
                    <Shield className="text-violet-500 drop-shadow-[0_0_8px_rgba(139,92,246,0.8)]" size={20} /> Доска Заданий
                </h2>

                {/* Divider & Context */}
                <div className="hidden lg:block h-5 w-px bg-white/10"></div>
                <div className="hidden lg:flex items-center text-xs text-slate-400 font-fantasy tracking-wide">
                    <span>Активные Контракты</span>
                </div>
            </div>

            {/* Mobile Dots (Changed from md:hidden to lg:hidden to show on <1024px) */}
            <div className="flex lg:hidden gap-1.5 mx-auto">
               {columns.map((_, idx) => (
                   <div key={idx} className={`w-1.5 h-1.5 rounded-full transition-all duration-300 ${idx === activeColIndex ? 'bg-violet-400 scale-125 shadow-[0_0_8px_rgba(167,139,250,0.8)]' : 'bg-slate-700'}`} />
               ))}
            </div>

            {isAdmin && (
                <button onClick={() => { 
                    setEditingQuestId(null); 
                    setFormQuest({type: QuestType.PUBLIC, status: QuestStatus.AVAILABLE, alignment: 'Neutral', details: {givenBy: '', acceptedBy: []}}); 
                    setIsPostModalOpen(true); 
                }} className="ml-auto group relative bg-violet-900/40 hover:bg-violet-800/60 text-violet-100 border border-violet-500/50 px-3 py-1.5 rounded-lg font-fantasy flex items-center gap-2 transition-all shadow-[0_0_15px_rgba(139,92,246,0.2)] overflow-hidden text-xs md:text-sm">
                    <div className="absolute inset-0 bg-gradient-to-r from-violet-500/0 via-violet-400/20 to-violet-500/0 translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></div>
                    <Plus size={16} className="relative z-10" /> <span className="hidden sm:inline relative z-10">Создать Квест</span>
                </button>
            )}
       </div>

       {/* Board Container */}
       <div className="flex-1 overflow-hidden relative flex flex-col z-10 bg-black/40 backdrop-blur-sm m-4 rounded-xl border border-slate-700/50 shadow-2xl">
            {/* Background Grid FX */}
            <div className="absolute inset-0 z-0 opacity-20 pointer-events-none" 
                 style={{ 
                    backgroundImage: 'linear-gradient(rgba(139, 92, 246, 0.1) 1px, transparent 1px), linear-gradient(90deg, rgba(139, 92, 246, 0.1) 1px, transparent 1px)',
                    backgroundSize: '40px 40px'
                 }}>
            </div>

            <div className="flex-1 flex w-full relative z-10 h-full">
                {columns.map((col, index) => (
                    <div key={col.type} className={`flex-1 h-full flex-col border-r border-slate-700/30 ${col.bg} transition-opacity duration-300 ${index === activeColIndex ? 'flex' : 'hidden lg:flex'}`}>
                        {/* Column Header */}
                        <div className="p-4 border-b border-white/5 flex items-center justify-center relative">
                            <button onClick={() => setActiveColIndex(Math.max(0, index - 1))} className={`lg:hidden absolute left-2 text-slate-500 ${index === 0 ? 'opacity-0 pointer-events-none' : ''}`}><ChevronLeft /></button>
                            <h3 className={`text-center font-fantasy ${col.color} text-lg uppercase tracking-[0.2em] drop-shadow-[0_0_8px_currentColor]`}>{col.title}</h3>
                            <button onClick={() => setActiveColIndex(Math.min(2, index + 1))} className={`lg:hidden absolute right-2 text-slate-500 ${index === 2 ? 'opacity-0 pointer-events-none' : ''}`}><ChevronRight /></button>

                            {/* Magic Glow Line */}
                            <div className={`absolute bottom-0 left-1/4 right-1/4 h-px bg-gradient-to-r from-transparent via-current to-transparent opacity-50 ${col.color}`}></div>
                        </div>

                        {/* Quest List */}
                        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-4">
                             {quests.filter(q => q.type === col.type && q.status !== QuestStatus.COMPLETED).map(q => (
                                 <QuestCard 
                                    key={q.id} 
                                    quest={q} 
                                    onUpdateStatus={handleUpdateStatus}
                                    onOpenAcceptModal={handleOpenAccept}
                                    isAdmin={isAdmin}
                                    onEdit={handleEditClick}
                                    allCharacters={characters}
                                 />
                             ))}
                        </div>
                    </div>
                ))}
            </div>

            {/* Archive Floating Button */}
            <button 
                onClick={() => setIsArchiveOpen(true)}
                className="absolute bottom-6 right-6 z-30 group"
                title="Открыть Архив Бездны"
            >
                <div className="relative w-14 h-14 rounded-full bg-slate-950 border border-slate-700 flex items-center justify-center shadow-2xl overflow-hidden group-hover:scale-110 transition-transform duration-300">
                    <div className="absolute inset-0 bg-violet-900/20 group-hover:bg-violet-600/30 transition-colors"></div>
                    <CheckCircle className="text-emerald-500 group-hover:text-emerald-300 transition-colors relative z-10" size={24} />
                    {/* Glow Pulse */}
                    <div className="absolute inset-0 rounded-full animate-ping bg-emerald-500/10"></div>
                </div>
            </button>
       </div>

       {/* --- Modals --- */}

       {/* Archive Modal (Void) - UPDATED SIZE and ANIMATION */}
       <Modal 
            isOpen={isArchiveOpen} 
            onClose={() => setIsArchiveOpen(false)} 
            title="Бездна" 
            zIndex="z-50"
            size="xl" 
            customBg="bg-[#050b14]/98 border-violet-900/50 shadow-[0_0_60px_rgba(109,40,217,0.3)] backdrop-blur-xl animate-void origin-center"
       >
            <div className="text-center mb-6 pb-2 relative overflow-hidden rounded-lg p-2">
                 {/* Stars/Noise BG for header */}
                 <div className="absolute inset-0 opacity-40" style={{backgroundImage: 'radial-gradient(white 1px, transparent 1px)', backgroundSize: '15px 15px'}}></div>
                 <div className="relative z-10 font-fantasy text-slate-500 text-sm">Завершенные контракты, вернувшиеся из бездны...</div>
            </div>

            <div className="space-y-4 max-h-[60vh] overflow-y-auto pr-2 custom-scrollbar">
                {completedQuests.length === 0 ? (
                    <div className="text-center py-12 text-violet-900/50 font-fantasy text-sm">Бездна смотрит в ответ... здесь пусто.</div>
                ) : (
                    completedQuests.map(q => {
                        const style = getQuestStyles(q);
                        const isExpanded = expandedArchiveId === q.id;

                        return (
                        <div 
                            key={q.id} 
                            onClick={() => setExpandedArchiveId(isExpanded ? null : q.id)}
                            className={`group relative bg-black/40 border p-4 rounded-lg flex flex-col gap-2 transition-all cursor-pointer hover:bg-white/5 ${style.archiveBorder || 'border-slate-800'}`}
                        >
                            <div className="flex justify-between items-start relative z-10">
                                <span className={`font-fantasy font-bold text-lg decoration-violet-800 decoration-1 transition-colors ${style.archiveText || 'text-slate-400'} group-hover:brightness-125`}>{q.title}</span>
                                <div className="flex items-center gap-2">
                                     <span className={`text-[9px] bg-black border border-white/10 px-2 py-0.5 rounded tracking-widest uppercase ${style.archiveText}`}>{TYPE_LABELS[q.type]}</span>
                                     <ChevronDown size={14} className={`text-slate-500 transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
                                </div>
                            </div>

                            {/* Expanded Details */}
                            {isExpanded && (
                                <div className="mt-2 pt-2 border-t border-white/10 animate-fadeIn space-y-2">
                                    <p className="text-sm text-slate-400 font-serif leading-relaxed italic">{q.description}</p>
                                    <div className="flex justify-between items-center text-xs text-slate-500">
                                        <span>Награда: <span className="text-slate-300">{q.reward}</span></span>
                                        <span>От: {q.details.givenBy}</span>
                                    </div>
                                </div>
                            )}

                            {!isExpanded && (
                                <div className="flex justify-between items-center mt-2 pt-2 border-t border-white/5">
                                    <div className="flex -space-x-2">
                                        {q.details.acceptedBy.map((n, i) => (
                                            <div key={i} className={`w-5 h-5 rounded-full border border-slate-900 flex items-center justify-center text-[8px] font-bold text-slate-300 ring-1 ring-slate-800 bg-slate-800`} title={n}>
                                                {n.charAt(0)}
                                            </div>
                                        ))}
                                    </div>
                                    <span className="text-[10px] text-slate-600 uppercase tracking-widest group-hover:text-slate-500 transition-colors">Исполнено</span>
                                </div>
                            )}
                        </div>
                    )})
                )}
            </div>
       </Modal>

       <Modal isOpen={isPostModalOpen} onClose={() => setIsPostModalOpen(false)} title={editingQuestId ? "Перековать Квест" : "Сотворить Квест"}>
            <form onSubmit={handlePostSubmit} className="space-y-4">
                <MagicalInput required placeholder="Название Квеста" 
                    value={formQuest.title || ''} onChange={e => setFormQuest({...formQuest, title: e.target.value})} />

                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                         <label className="text-xs text-slate-400">Сфера (Тип)</label>
                         <MagicalSelect
                            value={formQuest.type} onChange={e => setFormQuest({...formQuest, type: e.target.value as QuestType})}>
                            <option value={QuestType.PERSONAL}>Личный</option>
                            <option value={QuestType.FACTION}>Фракционный</option>
                            <option value={QuestType.PUBLIC}>Публичный</option>
                        </MagicalSelect>
                    </div>
                    {formQuest.type === QuestType.FACTION && (
                        <div className="space-y-1 animate-fadeIn">
                            <label className="text-xs text-slate-400">Аура (Мировоззрение)</label>
                            <MagicalSelect
                                value={formQuest.alignment} onChange={e => setFormQuest({...formQuest, alignment: e.target.value as QuestAlignment})}>
                                <option value="Neutral">Нейтральный (Фиолетовый)</option>
                                <option value="Dark">Тьма (Индиго)</option>
                                <option value="Light">Свет (Золотой)</option>
                                <option value="NPC">Кровь (Красный)</option>
                                <option value="Player">Дух (Голубой)</option>
                            </MagicalSelect>
                        </div>
                    )}
                </div>

                <MagicalInput required placeholder="Награда" 
                    value={formQuest.reward || ''} onChange={e => setFormQuest({...formQuest, reward: e.target.value})} />

                <div className="space-y-1 bg-slate-900/30 p-2 rounded border border-slate-800/50">
                     <label className="text-xs text-slate-400 block mb-1">
                         {formQuest.type === QuestType.PERSONAL ? "Привязано к Душе" : "Происхождение / Покровитель"}
                     </label>

                     {formQuest.type !== QuestType.PERSONAL && (
                         <div className="mb-4">
                             <RuneCheckbox 
                                label="Известный Искатель?" 
                                checked={isPlayerGiver} 
                                onChange={v => setIsPlayerGiver(v)} 
                             />
                         </div>
                     )}

                     {(formQuest.type === QuestType.PERSONAL || isPlayerGiver) ? (
                         <MagicalSelect 
                            required 
                            value={formQuest.details?.givenBy || ''}
                            onChange={e => setFormQuest({...formQuest, details: {...formQuest.details!, givenBy: e.target.value}})}
                         >
                             <option value="" disabled>Выберите Душу...</option>
                             {Object.entries(groupedCharacters).map(([faction, chars]) => (
                                 <optgroup key={faction} label={faction}>
                                     {(chars as Character[]).map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                                 </optgroup>
                             ))}
                         </MagicalSelect>
                     ) : (
                         <MagicalInput required 
                            placeholder="Имя Сущности" 
                            value={formQuest.details?.givenBy || ''} onChange={e => setFormQuest({...formQuest, details: {...formQuest.details!, givenBy: e.target.value}})} />
                     )}
                </div>

                <MagicalTextArea required placeholder="Детали пакта..." rows={3} 
                    value={formQuest.description || ''} onChange={e => setFormQuest({...formQuest, description: e.target.value})} />

                <button type="submit" className="w-full mt-4 group relative px-6 py-3 bg-slate-900 border-2 border-violet-500/50 shadow-[0_0_15px_rgba(139,92,246,0.2)] text-violet-100 font-fantasy tracking-[0.2em] uppercase hover:bg-violet-900/40 hover:border-violet-400 hover:shadow-[0_0_25px_rgba(139,92,246,0.6)] transition-all duration-300 overflow-hidden">
                    <span className="relative z-10">{editingQuestId ? "Изменить Реальность" : "Воплотить"}</span>
                    <div className="absolute inset-0 bg-gradient-to-r from-transparent via-violet-400/10 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></div>
                </button>
            </form>
       </Modal>

       <Modal isOpen={acceptModalOpen} onClose={() => setAcceptModalOpen(false)} title="Связать Судьбы">
           <form onSubmit={handleAcceptSubmit} className="space-y-4">
               <div className="bg-slate-800/50 p-3 rounded text-sm text-slate-300 italic mb-4 border border-slate-700">"Плетение связывает тех, кто принимает зов..."</div>

               <div className="flex justify-between items-center mb-2">
                   <label className="text-xs text-slate-400 uppercase tracking-widest font-bold">Участники</label>
                   <button 
                      type="button" 
                      onClick={() => setIsCharSelectorOpen(true)}
                      className="text-xs flex items-center gap-1 bg-violet-900/20 text-violet-300 px-2 py-1 rounded hover:bg-violet-900/40 transition-colors border border-violet-500/30"
                   >
                       <BookOpen size={12} /> Список
                   </button>
               </div>

               <div className="space-y-2 max-h-60 overflow-y-auto">
                   {acceptNames.map((name, index) => (
                       <div key={index} className="relative group">
                           <MagicalInput 
                               autoFocus={index === acceptNames.length - 1} 
                               placeholder={`Душа ${index + 1}`} 
                               className="pr-8"
                               value={name} 
                               onChange={(e) => { const newNames = [...acceptNames]; newNames[index] = e.target.value; setAcceptNames(newNames); }} 
                           />

                           {acceptNames.length > 1 && (
                               <button 
                                  type="button" 
                                  onClick={() => setAcceptNames(acceptNames.filter((_, i) => i !== index))} 
                                  className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-500 hover:text-red-500 p-1"
                               >
                                   <X size={14} />
                               </button>
                           )}
                       </div>
                   ))}
               </div>

               <button type="button" onClick={() => setAcceptNames([...acceptNames, ''])} className="text-xs flex items-center gap-1 text-slate-400 hover:text-white transition-colors">
                   <Plus size={14} /> Добавить участника
               </button>

               <button type="submit" className="w-full mt-4 group relative px-6 py-3 bg-slate-900 border-2 border-violet-500/50 shadow-[0_0_15px_rgba(139,92,246,0.2)] text-violet-100 font-fantasy tracking-[0.2em] uppercase hover:bg-violet-900/40 hover:border-violet-400 hover:shadow-[0_0_25px_rgba(139,92,246,0.6)] transition-all duration-300 overflow-hidden">
                  <span className="relative z-10">Скрепить Пакт</span>
               </button>
           </form>
       </Modal>
    </div>
  );
};

export default QuestBoardPage;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { DndContext, DragEndEvent, DragOverlay, useSensor, useSensors, PointerSensor, DragStartEvent, pointerWithin } from '@dnd-kit/core';
import { arrayMove } from '@dnd-kit/sortable';
import { BattleParticipant, LogEntry, SequenceNode, BattleStatus, CharacterTemplate, ActiveEffect, Cooldown, JsonInjury } from './types';
import { advanceRound, tickActionTimers } from './engine/timeEngine';
import { calculateSequenceTree } from './engine/calculator';
import { generateSummary, generateStatsText } from './engine/formatters';
import SourcePanel from './components/SourcePanel';
import SequenceCanvas from './components/SequenceCanvas';
import BattleLog from './components/BattleLog';
import { Modal } from './components/Modal';
import { updateBattle, getCharacters, createBattle, getBattles, calculateTraumaPenalty, updateCharacter, deleteBattle, supabase } from './lib/supabase';
import { UserPlus, Save, Play, Square, List, RefreshCw, Trash2, Search, Filter, HardDrive, Cloud, Database, WifiOff } from 'lucide-react';

// UI State Types
type ModalType = 'CREATE_BATTLE' | 'CONFIRM_SAVE' | 'CONFIRM_END' | 'FINALIZE_BATTLE' | 'ALERT' | 'CHAR_SELECT' | 'BATTLE_LIST' | 'CONFIRM_DELETE' | null;
type StorageMode = 'local' | 'server';

interface SavedBattleItem {
    id: string;
    name: string;
    status: string;
    source: StorageMode;
    timestamp?: number;
}

interface BattleModuleProps {
  isAdmin?: boolean;
}

const LOCAL_STORAGE_KEY = 'juul_d_local_battles';

const App: React.FC<BattleModuleProps> = ({ isAdmin = false }) => {
  const [participants, setParticipants] = useState<BattleParticipant[]>([]);
  const [round, setRound] = useState<number>(0); 
  const [status, setStatus] = useState<BattleStatus>('startup');
  const [battleName, setBattleName] = useState('Новый Бой');
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [battleId, setBattleId] = useState<string | null>(null);

  // Storage State
  const [storageMode, setStorageMode] = useState<StorageMode>(isAdmin ? 'server' : 'local');
  const [savedBattles, setSavedBattles] = useState<SavedBattleItem[]>([]);

  const [loading, setLoading] = useState(false);
  const [allCharacters, setAllCharacters] = useState<CharacterTemplate[]>([]);

  const [activeModal, setActiveModal] = useState<ModalType>(null);
  const [modalInput, setModalInput] = useState('');
  const [alertMessage, setAlertMessage] = useState('');
  const [pendingAction, setPendingAction] = useState<() => void>(() => {});

  // Character Selection State
  const [charSearchTerm, setCharSearchTerm] = useState('');
  const [selectedFaction, setSelectedFaction] = useState<string>('All');
  const [selectedVolume, setSelectedVolume] = useState<string>('All');

  // State for Finalize Battle Modal
  const [participantsToSave, setParticipantsToSave] = useState<Set<string>>(new Set());

  // State for Deletion
  const [battleToDelete, setBattleToDelete] = useState<{id: string, source: StorageMode} | null>(null);

  const [tree, setTree] = useState<SequenceNode[]>([]);
  const [activeDragItem, setActiveDragItem] = useState<any>(null);
  const [activeNode, setActiveNode] = useState<SequenceNode | null>(null);

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 5 } }));

  const initRef = useRef(false);

  // --- INIT ---
  useEffect(() => {
    if (initRef.current) return;
    initRef.current = true;
    refreshData();
  }, [isAdmin]);

  // Ensure non-admins are always local
  useEffect(() => {
      if (!isAdmin && storageMode === 'server') {
          setStorageMode('local');
      }
  }, [isAdmin]);

  const refreshData = async () => {
        // Load Characters
        const { data: chars } = await getCharacters();
        if (chars && chars.length > 0) {
             setAllCharacters(chars);
        }
        await loadSavedBattlesList();
  };

  const loadSavedBattlesList = async () => {
        let combined: SavedBattleItem[] = [];

        // 1. Local Storage
        try {
            const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
            const localMapped = localData.map((b: any) => ({
                id: b.id,
                name: b.name,
                status: b.status,
                source: 'local' as StorageMode,
                timestamp: b.timestamp || 0
            }));
            combined = [...combined, ...localMapped];
        } catch (e) {
            console.error("Failed to parse local battles", e);
        }

        // 2. Server (If Admin)
        if (isAdmin) {
            const { data: battles } = await getBattles();
            if (battles) {
                const serverMapped = battles.map((b: any) => ({
                    id: b.id,
                    name: b.name,
                    status: b.status,
                    source: 'server' as StorageMode,
                    timestamp: new Date(b.created_at).getTime()
                }));
                combined = [...combined, ...serverMapped];
            }
        }

        setSavedBattles(combined);
  };

  // --- DERIVED LISTS FOR FILTERS ---
  const uniqueFactions = useMemo(() => {
      const factions = new Set<string>();
      allCharacters.forEach(c => {
          if (c.profile.faction && c.profile.faction !== 'Могильник') {
              factions.add(c.profile.faction);
          }
      });
      return Array.from(factions).sort();
  }, [allCharacters]);

  const uniqueVolumes = useMemo(() => {
      const isNpcLike = ['NPC', 'НПС', 'Бестиарий'].includes(selectedFaction);
      if (!isNpcLike) return [];

      const volumes = new Set<string>();
      allCharacters.forEach(c => {
          if (c.profile.faction === selectedFaction && c.profile.npc_volume) {
              volumes.add(c.profile.npc_volume);
          }
      });
      return Array.from(volumes).sort();
  }, [allCharacters, selectedFaction]);


  // --- MEMOIZED FILTERING ---
  const filteredCharacters = useMemo(() => {
    let result = [...allCharacters];
    result = result.filter(c => c.profile.faction !== 'Могильник');

    if (charSearchTerm) {
        const lower = charSearchTerm.toLowerCase();
        result = result.filter(c => c.profile.name.toLowerCase().includes(lower));
    }

    if (selectedFaction !== 'All') {
        result = result.filter(c => c.profile.faction === selectedFaction);
    }

    const isNpcLike = ['NPC', 'НПС', 'Бестиарий'].includes(selectedFaction);
    if (isNpcLike && selectedVolume !== 'All') {
         result = result.filter(c => c.profile.npc_volume === selectedVolume);
    }

    result.sort((a, b) => a.profile.name.localeCompare(b.profile.name));
    return result;
  }, [allCharacters, charSearchTerm, selectedFaction, selectedVolume]);

  // --- UI HELPERS ---
  const showAlert = (msg: string) => {
      setAlertMessage(msg);
      setActiveModal('ALERT');
  };

  const closeModal = () => {
      setActiveModal(null);
      setModalInput('');
      setAlertMessage('');
      setCharSearchTerm('');
      setSelectedFaction('All');
      setSelectedVolume('All');
  };

  const getStatusLabel = (s: string) => {
       if (s === 'active') return 'АКТИВЕН';
       if (s === 'finished') return 'ЗАВЕРШЕН';
       if (s === 'startup') return 'ПОДГОТОВКА';
       return s;
  };

  const getCharacterStyle = (faction: string) => {
      const f = (faction || '').toLowerCase();
      if (['светлые', 'light', 'свет'].includes(f)) return 'bg-amber-900/10 border-amber-600/50 hover:bg-amber-900/20 text-amber-100';
      if (['тёмные', 'dark', 'темные', 'тьма'].includes(f)) return 'bg-indigo-950/30 border-indigo-500/50 hover:bg-indigo-900/20 text-indigo-100';
      if (['npc', 'нпс', 'бестиарий'].includes(f)) return 'bg-red-950/20 border-red-800/50 hover:bg-red-900/20 text-red-100';
      return 'bg-panel border-violet-900/30 hover:border-violet-500/50 text-slate-200';
  };

  const toggleStorageMode = () => {
      if (!isAdmin) return;
      setStorageMode(prev => prev === 'server' ? 'local' : 'server');
  };

  // ... (keeping all event handlers as they were, no changes to logic)
  const handleUpdateParticipant = (id: string, updates: any) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== id) return p;

          // Deep merge for profile/stats if necessary, but simple spread usually works for top-level keys
          // If we are updating profile.name via "profile: {name: ...}", we need to preserve other profile fields
          if (updates.profile) {
              return { ...p, profile: { ...p.profile, ...updates.profile } };
          }
          if (updates.stats) {
              return { ...p, stats: { ...p.stats, ...updates.stats } };
          }

          return { ...p, ...updates };
      }));
  };

  const handleToggleEquip = (participantId: string, itemId: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const newWearable = p.equipment.wearable.map(item => {
              if (item._id === itemId) return { ...item, is_equipped: !item.is_equipped };
              return item;
          });
          return { ...p, equipment: { ...p.equipment, wearable: newWearable } };
      }));
  };

  const handleRemoveParticipant = (participantId: string) => {
      setParticipants(prev => {
          // 1. Remove the target
          const filtered = prev.filter(p => p.instance_id !== participantId);

          // 2. Auto-Renumber duplicates logic
          const idMap: Record<string, number[]> = {};

          // Helper to extract base name (removes " #4" suffix)
          const getBaseName = (name: string) => name.replace(/ #\d+$/, '');

          // Group indices by TemplateID + BaseName to avoid mixing different monsters or custom-renamed ones
          filtered.forEach((p, idx) => {
              const base = getBaseName(p.profile.name);
              const key = `${p.id}|${base}`;
              if (!idMap[key]) idMap[key] = [];
              idMap[key].push(idx);
          });

          // Create copy to mutate names
          const nextParticipants = [...filtered];

          Object.values(idMap).forEach(indices => {
              // If group has multiples OR if the single remaining item definitely had a number tag (e.g. we deleted #1 leaving #2)
              if (indices.length > 0) {
                  const firstP = nextParticipants[indices[0]];
                  const baseName = getBaseName(firstP.profile.name);
                  const wasNumbered = firstP.profile.name.match(/ #\d+$/);

                  // Renumber sequentially if there are multiples or if it was part of a numbered set
                  if (indices.length > 1 || wasNumbered) {
                      indices.forEach((pIndex, i) => {
                          const newName = `${baseName} #${i + 1}`;
                          if (nextParticipants[pIndex].profile.name !== newName) {
                              nextParticipants[pIndex] = {
                                  ...nextParticipants[pIndex],
                                  profile: {
                                      ...nextParticipants[pIndex].profile,
                                      name: newName
                                  }
                              };
                          }
                      });
                  }
              }
          });

          return nextParticipants;
      });
  };

  const handleRemoveEffect = (participantId: string, effectId: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const effectToRemove = p.active_effects.find(e => e.id === effectId);
          const nextEffects = p.active_effects.filter(e => e.id !== effectId);

          let nextCooldowns = [...p.cooldowns];
          if (effectToRemove?.original_ability_id) {
               const sourceAbility = p.flat_abilities.find(a => a._id === effectToRemove.original_ability_id);
               if (sourceAbility && sourceAbility.cd > 0) {
                   if (!nextCooldowns.some(cd => cd.name === sourceAbility.name)) {
                       nextCooldowns.push({
                          id: `cd_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                          name: sourceAbility.name,
                          val: sourceAbility.cd,
                          max: sourceAbility.cd,
                          unit: sourceAbility.cd_unit || 'turn'
                       });
                   }
               }
          }
          return { ...p, active_effects: nextEffects, cooldowns: nextCooldowns };
      }));
  };

  const handleRemoveCooldown = (participantId: string, cdId: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          return { ...p, cooldowns: p.cooldowns.filter(cd => cd.id !== cdId) };
      }));
  };

  const handleAddInjury = (participantId: string, templateId: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const newInjuries = [...p.medcard.injuries, { count: 1, template_id: templateId, custom_name: '' }];
          const trauma = calculateTraumaPenalty(newInjuries);
          return {
              ...p,
              medcard: { ...p.medcard, injuries: newInjuries },
              battle_stats: { ...p.battle_stats, hp_penalty_current: trauma.total, trauma_phys: trauma.phys, trauma_mag: trauma.mag, trauma_uniq: trauma.uniq }
          };
      }));
  };

  const handleRemoveInjury = (participantId: string, index: number) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const newInjuries = [...p.medcard.injuries];
          newInjuries.splice(index, 1);
          const trauma = calculateTraumaPenalty(newInjuries);
          return {
              ...p,
              medcard: { ...p.medcard, injuries: newInjuries },
              battle_stats: { ...p.battle_stats, hp_penalty_current: trauma.total, trauma_phys: trauma.phys, trauma_mag: trauma.mag, trauma_uniq: trauma.uniq }
          };
      }));
  };

  const handleAddDebuff = (participantId: string, name: string, tag: string, val: number, dur: number, unit: string, extraTags?: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== participantId) return p;
          const finalTags = [];
          if (tag && tag !== 'none') finalTags.push(tag);
          if (extraTags) finalTags.push(extraTags.toLowerCase().trim());

          const newEffect: ActiveEffect = {
              id: `custom_${Date.now()}`,
              name: name,
              tags: finalTags,
              bonuses: [{ val: val, stat: tag }],
              duration_left: dur,
              unit: unit || 'turn'
          };
          return { ...p, active_effects: [...p.active_effects, newEffect] };
      }));
  };

  const loadBattle = async (id: string, source: StorageMode) => {
      setLoading(true);

      let foundBattle = null;

      if (source === 'server') {
          const { data: b } = await supabase.from('battles').select('*').eq('id', id).single();
          foundBattle = b;
      } else {
          // Local storage lookup
          const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
          foundBattle = localData.find((b: any) => b.id === id);
      }

      if (foundBattle) {
          setBattleId(foundBattle.id);
          setBattleName(foundBattle.name || 'Бой без названия');
          setRound(foundBattle.round);
          setStatus(foundBattle.status || 'startup');
          setLogs(foundBattle.sequence_log || []);
          setParticipants(foundBattle.participants_snapshot || []);

          // Switch to the mode of the loaded battle so save works intuitively
          if (isAdmin) setStorageMode(source);
      } else {
          showAlert("Бой не найден (возможно удален).");
          loadSavedBattlesList(); // Refresh list
      }
      setLoading(false);
      setActiveModal(null);
  };

  const handleDeleteBattle = (id: string, source: StorageMode, e: React.MouseEvent) => {
      e.stopPropagation();
      setBattleToDelete({ id, source });
      setActiveModal('CONFIRM_DELETE');
  };

  const confirmDeleteBattle = async () => {
      if (!battleToDelete) {
          setActiveModal('BATTLE_LIST');
          return;
      }

      const { id, source } = battleToDelete;

      if (source === 'server') {
          const { error } = await deleteBattle(id);
          if (error) {
              showAlert(`Ошибка удаления: ${error.message}`);
              return;
          }
      } else {
          const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
          const newData = localData.filter((b: any) => b.id !== id);
          localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(newData));
      }

      // Optimistic update
      setSavedBattles(prev => prev.filter(b => b.id !== id));

      if (battleId === id) {
          setBattleId(null);
          setBattleName('Новый Бой');
          setRound(1);
          setStatus('startup');
          setLogs([]);
          setParticipants([]);
          setTree([]);
          showAlert(source === 'server' ? "Бой удален из базы." : "Бой удален из локального хранилища.");
      } else {
          setActiveModal('BATTLE_LIST');
      }
      setBattleToDelete(null);
  };

  const cancelDelete = () => {
      setBattleToDelete(null);
      setActiveModal('BATTLE_LIST');
  };

  const handleCreateBattleClick = () => {
      setModalInput('');
      setActiveModal('CREATE_BATTLE');
  };

  const confirmCreateBattle = async () => {
      const name = modalInput || "Стычка у ворот";
      setLoading(true);

      const newBattle = {
          id: `battle_${Date.now()}_${Math.random().toString(36).substr(2,5)}`,
          name,
          participants_snapshot: [],
          sequence_log: [],
          casualties: [],
          round: 0,
          status: 'startup'
      };

      if (storageMode === 'server' && isAdmin) {
          const { data, error } = await createBattle(name);
          if (error) {
              showAlert(`Failed to create battle in DB. Error: ${error.message}`);
              setLoading(false);
              return;
          }
          if (data) {
              setBattleId(data.id);
              setBattleName(data.name);
          }
      } else {
          setBattleId(newBattle.id);
          setBattleName(newBattle.name);
          const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
          localData.push(newBattle);
          localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
      }

      setRound(0);
      setStatus('startup');
      setParticipants([]);
      setLogs([]);
      setLoading(false);
      closeModal();
      loadSavedBattlesList(); // Refresh list to show new
  };

  const handleSaveBattle = async () => {
      if (!battleId) {
          setPendingAction(() => async () => {
               showAlert("Пожалуйста, создайте бой через меню 'Архив' -> 'Создать'.");
               closeModal();
          });
          setActiveModal('CONFIRM_SAVE');
          return;
      }

      const battleState = {
          name: battleName,
          participants_snapshot: participants,
          sequence_log: logs,
          round: round,
          status: status,
          casualties: []
      };

      if (storageMode === 'server' && isAdmin) {
          const { error } = await updateBattle(battleId, battleState);

          if (error) {
              showAlert(`Ошибка сохранения на сервер: ${error.message}. (Если вы переключили режим с Локального, создайте новый бой на сервере)`);
          } else {
              showAlert("Бой успешно сохранен в базе данных.");
          }
      } else {
          // Local Save
          const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
          const index = localData.findIndex((b: any) => b.id === battleId);
          if (index !== -1) {
              localData[index] = { ...localData[index], ...battleState };
          } else {
              localData.push({ id: battleId, ...battleState });
          }
          localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
          showAlert("Бой сохранен локально.");
      }
      loadSavedBattlesList();
  };

  const updateBattleName = async (newName: string) => {
      setBattleName(newName);
  };

  const escapeRegExp = (string: string) => {
    return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); // $& means the whole matched string
  }

  const addParticipant = (template: CharacterTemplate) => {
      // Logic for adding copies with auto-numbering
      setParticipants(prev => {
          const baseName = template.profile.name;
          const sameType = prev.filter(p => p.id === template.id);

          let newName = baseName;
          let updatedPrev = [...prev];

          if (sameType.length > 0) {
              // 1. Rename existing "Base Name" to "Base Name #1" if found
              updatedPrev = updatedPrev.map(p => {
                  if (p.id === template.id && p.profile.name === baseName) {
                      return { ...p, profile: { ...p.profile, name: `${baseName} #1` } };
                  }
                  return p;
              });

              // 2. Find used numbers in names like "Base Name #N"
              const regex = new RegExp(`^${escapeRegExp(baseName)} #(\\d+)$`);
              const usedNumbers = updatedPrev
                  .filter(p => p.id === template.id)
                  .map(p => {
                      const match = p.profile.name.match(regex);
                      return match ? parseInt(match[1]) : 0;
                  });

              const maxNum = Math.max(0, ...usedNumbers);
              newName = `${baseName} #${maxNum + 1}`;
          }

          const flatAbilities = (template.ability_groups || []).flatMap(g => g.abilities || []);
          let passivesToScan = template.flat_passives || [];
          if (passivesToScan.length === 0 && template.passives) {
              passivesToScan = template.passives.flatMap(g => g.items);
          }

          const startupEffects: ActiveEffect[] = [];
          let logText = "";

          passivesToScan.forEach(pas => {
              if (!pas.trigger) return;
              const trig = pas.trigger.toUpperCase();
              if (trig.includes('START') || trig.includes('НАЧАЛО') || trig.includes('COMBAT') || trig.includes('БОЯ')) {
                  const mechInfo = pas.desc_mech ? ` (${pas.desc_mech})` : '';
                  logText += `> (${newName}: ${pas.name}${mechInfo})\n`;

                  const hasDuration = pas.dur && pas.dur > 0;
                  startupEffects.push({
                      id: `start_passive_${pas._id || Math.random()}_${Date.now()}`,
                      name: pas.name,
                      tags: [...(pas.tags || []), pas.is_flaw ? 'debuff' : 'buff'],
                      bonuses: pas.bonuses || [],
                      duration_left: hasDuration ? pas.dur! : 999,
                      unit: hasDuration ? (pas.dur_unit || 'turn') : 'battle',
                      original_ability_id: pas._id
                  });
              }
          });

          const newP: BattleParticipant = {
              ...template,
              instance_id: `char_${template.id}_${Date.now()}`,
              is_player: false,
              profile: {
                  ...template.profile,
                  name: newName // Apply numbered name
              },

              battle_stats: (template as any).battle_stats || {
                  hp_penalty_current: 0,
                  trauma_phys: 0,
                  trauma_mag: 0,
                  trauma_uniq: 0,
                  actions_max: 4,
                  actions_left: 4
              },
              active_effects: startupEffects,
              cooldowns: [],
              usage_counts: {}, 
              flat_abilities: flatAbilities,
              flat_passives: passivesToScan
          };

          if (logText) {
              setLogs(prevLogs => [...prevLogs, {
                  id: `trigger_add_${newP.instance_id}_${Date.now()}`,
                  round: round,
                  timestamp: new Date().toISOString(),
                  type: 'action', 
                  text_formatted: logText.trim()
              }]);
          }

          return [...updatedPrev, newP];
      });

      setActiveModal(null);
  };

  const handleNextRound = async () => {
    const summary = generateSummary(participants, round);
    const statsSnapshot = generateStatsText(participants);

    const participantsSnapshot = JSON.parse(JSON.stringify(participants));

    const endRoundLog: LogEntry = {
      id: `end_rnd_${round}_${Date.now()}`,
      round: round,
      timestamp: new Date().toISOString(),
      type: 'system',
      text_formatted: round === 0 ? `ЗАВЕРШЕНИЕ ПОДГОТОВКИ` : `ЗАВЕРШЕНИЕ РАУНДА ${round}`,
      summary: summary,
      details: {
          stats_snapshot: statsSnapshot,
          participants_snapshot: participantsSnapshot
      }
    };

    const nextR = round + 1;
    let newStatus = status;
    if (status === 'startup') {
        newStatus = 'active';
        setStatus('active');
    }

    let advancedParticipants = [...participants];

    if (round !== 0) {
        advancedParticipants = advanceRound(participants);
    }

    const startRoundLog: LogEntry = {
        id: `start_rnd_${nextR}_${Date.now()}`,
        round: nextR,
        timestamp: new Date().toISOString(),
        text_formatted: `НАЧАЛО РАУНДА ${nextR}`,
        type: 'round_change'
    };

    const logsToAdd = [endRoundLog, startRoundLog];
    const updatedLogs = [...logs, ...logsToAdd];

    setRound(nextR);
    setParticipants(advancedParticipants);
    setLogs(updatedLogs);
    setStatus(newStatus);

    if (battleId) {
        // Auto-save to CURRENT storage mode
        if (storageMode === 'server' && isAdmin) {
            await updateBattle(battleId, { 
                sequence_log: updatedLogs, 
                round: nextR, 
                status: newStatus,
                participants_snapshot: advancedParticipants 
            });
        } else {
            const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
            const index = localData.findIndex((b: any) => b.id === battleId);
            const battleState = {
                name: battleName,
                participants_snapshot: advancedParticipants,
                sequence_log: updatedLogs,
                round: nextR,
                status: newStatus
            };
            if (index !== -1) {
                localData[index] = { ...localData[index], ...battleState };
            }
            localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
        }
    }
  };

  const handleRollback = async (targetRound: number) => {
      const snapshotLog = logs.find(l => l.round === targetRound && l.details?.participants_snapshot);

      if (!snapshotLog) {
          showAlert("Невозможно откатить: нет сохраненного состояния для этого раунда.");
          return;
      }

      setParticipants(snapshotLog.details.participants_snapshot);
      setRound(snapshotLog.round);

      const newLogs = logs.filter(l => l.round <= targetRound && l.id !== snapshotLog.id);

      setLogs(newLogs);

      if (battleId) {
          const updatePayload = {
              round: snapshotLog.round,
              participants_snapshot: snapshotLog.details.participants_snapshot,
              sequence_log: newLogs,
              status: 'active'
          };

          if (storageMode === 'server' && isAdmin) {
              await updateBattle(battleId, updatePayload);
          } else {
              const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
              const index = localData.findIndex((b: any) => b.id === battleId);
              if (index !== -1) {
                  localData[index] = { ...localData[index], ...updatePayload };
                  localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
              }
          }
      }

      showAlert(`Откат выполнен. Вы вернулись в Раунд ${targetRound}.`);
  };

  const handleEndBattleClick = () => {
      const injuredIds = new Set<string>();
      participants.forEach(p => {
          if (p.medcard.injuries.length > 0) {
              injuredIds.add(p.instance_id);
          }
      });
      setParticipantsToSave(injuredIds);
      setActiveModal('FINALIZE_BATTLE');
  };

  const handleToggleSaveParticipant = (id: string) => {
      const next = new Set(participantsToSave);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setParticipantsToSave(next);
  };

  const finalizeBattle = async () => {
      if (!isAdmin) {
          setStatus('finished');
          showAlert("Бой завершен локально. Не-админы не могут обновлять травмы в базе персонажей.");
          closeModal();
          return;
      }

      setLoading(true);
      for (const p of participants) {
          if (participantsToSave.has(p.instance_id)) {
              await updateCharacter(p.id, {
                  medcard: p.medcard
              });
          }
      }
      setStatus('finished');
      if (battleId && storageMode === 'server') {
          const { error } = await updateBattle(battleId, { status: 'finished' });
          if (error) console.error("Failed to update battle status", error);
      }
      setLoading(false);
      closeModal();
      showAlert("Бой финализирован. Травмы для выбранных персонажей обновлены в базе данных.");
  };

  const confirmEndBattle = async () => {
      setStatus('finished');
      if (battleId) {
          if (storageMode === 'server' && isAdmin) {
              const { error } = await updateBattle(battleId, { status: 'finished' });
              if (error) showAlert(`Failed to update status in DB: ${error.message}`);
          } else {
              const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
              const index = localData.findIndex((b: any) => b.id === battleId);
              if (index !== -1) {
                  localData[index].status = 'finished';
                  localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
              }
          }
      }
      closeModal();
  };

  const extractActionsFromTree = (nodes: SequenceNode[]): SequenceNode[] => {
      let actions: SequenceNode[] = [];
      for (const node of nodes) {
          if (node.type === 'action') actions.push(node);
          if (node.children) actions = actions.concat(extractActionsFromTree(node.children));
      }
      return actions;
  };

  const handleCommit = async () => {
    if (tree.length === 0) {
        showAlert("Холст пуст. Добавьте действия или комбо.");
        return;
    }

    const result = calculateSequenceTree(tree, participants);

    const newLog: LogEntry = {
        id: Date.now().toString(),
        round: round,
        timestamp: new Date().toISOString(),
        text_formatted: result.formattedString || 'Пустое действие',
        type: 'action'
    };

    let updatedParticipants = [...participants];

    const actionNodes = extractActionsFromTree(tree);
    const actionsPerActor: Record<string, number> = {};
    const abilitiesUsed: { charId: string, abilityId: string }[] = [];

    actionNodes.forEach(node => {
        const charId = node.data?.charId;
        const abilityId = node.data?.abilityId;
        if (charId) {
            actionsPerActor[charId] = (actionsPerActor[charId] || 0) + 1;
        }
        if (charId && abilityId) {
            abilitiesUsed.push({ charId, abilityId });
        }
    });

    const effectsToApply: { charId: string, effect: ActiveEffect }[] = [];
    const cooldownsToApply: { charId: string, cooldown: Cooldown }[] = [];

    actionNodes.forEach(node => {
        const charId = node.data?.charId;
        const abilityId = node.data?.abilityId;
        if (!charId || !abilityId) return;

        const actor = participants.find(p => p.instance_id === charId);
        if (!actor) return;

        let ability = actor.flat_abilities.find(a => a._id === abilityId);
        if (!ability) {
             actor.ability_groups.forEach(g => {
                 const found = g.abilities.find(a => a._id === abilityId);
                 if (found) ability = found;
             });
        }

        if (ability) {
            if (ability.dur > 0) {
                effectsToApply.push({
                    charId,
                    effect: {
                        id: `eff_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                        name: ability.name,
                        tags: ability.tags,
                        bonuses: ability.bonuses,
                        duration_left: ability.dur,
                        unit: ability.dur_unit || 'turn',
                        original_ability_id: ability._id
                    }
                });
            }
            if (ability.cd > 0 && ability.dur === 0) {
                if (!ability.limit || ability.limit <= 0) {
                    cooldownsToApply.push({
                        charId,
                        cooldown: {
                            id: `cd_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                            name: ability.name,
                            val: ability.cd,
                            max: ability.cd,
                            unit: ability.cd_unit || 'turn'
                        }
                    });
                }
            }
        }
    });

    updatedParticipants = updatedParticipants.map(p => {
        let processedP = p;
        if (actionsPerActor[p.instance_id]) {
            processedP = tickActionTimers(p, actionsPerActor[p.instance_id]);
        }

        const myUsages = abilitiesUsed.filter(u => u.charId === p.instance_id);
        const nextUsageCounts = { ...processedP.usage_counts };
        const limitBasedCooldowns: Cooldown[] = [];

        myUsages.forEach(usage => {
             const ability = processedP.flat_abilities.find(a => a._id === usage.abilityId);
             if (ability) {
                 const current = nextUsageCounts[ability._id] || 0;
                 const next = current + 1;
                 nextUsageCounts[ability._id] = next;

                 if (ability.limit && ability.limit > 0) {
                     if (next >= ability.limit) {
                          if (ability.cd > 0) {
                              limitBasedCooldowns.push({
                                  id: `cd_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
                                  name: ability.name,
                                  val: ability.cd,
                                  max: ability.cd,
                                  unit: ability.cd_unit || 'turn'
                              });
                          }
                     }
                 }
             }
        });

        processedP = { ...processedP, usage_counts: nextUsageCounts };

        const myNewEffects = effectsToApply
            .filter(item => item.charId === p.instance_id)
            .map(item => item.effect);

        const myNewCooldowns = cooldownsToApply
            .filter(item => item.charId === p.instance_id)
            .map(item => item.cooldown);

        const allNewCooldowns = [...myNewCooldowns, ...limitBasedCooldowns];

        const finalCooldowns = [...processedP.cooldowns];
        allNewCooldowns.forEach(newCD => {
             if (!finalCooldowns.some(existing => existing.name === newCD.name)) {
                 finalCooldowns.push(newCD);
             }
        });

        return {
            ...processedP,
            active_effects: [...processedP.active_effects, ...myNewEffects],
            cooldowns: finalCooldowns
        };
    });

    setParticipants(updatedParticipants);
    const updatedLogs = [...logs, newLog];
    setLogs(updatedLogs);
    setTree([]); 

    if (battleId) {
        if (storageMode === 'server' && isAdmin) {
            await updateBattle(battleId, { 
                sequence_log: updatedLogs, 
                participants_snapshot: updatedParticipants
            });
        } else {
            const localData = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
            const index = localData.findIndex((b: any) => b.id === battleId);
            if (index !== -1) {
                localData[index] = { 
                    ...localData[index], 
                    sequence_log: updatedLogs, 
                    participants_snapshot: updatedParticipants 
                };
                localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(localData));
            }
        }
    }
  };

  // ... Drag and drop handlers ...
  const getParentId = (nodes: SequenceNode[], nodeId: string, parentId: string = 'root'): string | null => {
      for (const node of nodes) {
          if (node.id === nodeId) return parentId;
          if (node.children && node.children.length > 0) {
              const found = getParentId(node.children, nodeId, node.id);
              if (found) return found;
          }
      }
      return null;
  };

  const findNode = (nodes: SequenceNode[], id: string): SequenceNode | null => {
    for (const node of nodes) {
        if (node.id === id) return node;
        const found = findNode(node.children, id);
        if (found) return found;
    }
    return null;
  }

  const handleDragStart = (event: DragStartEvent) => {
    const { active } = event;
    const type = active.data.current?.type;
    if (type === 'SOURCE_ABILITY') setActiveDragItem(active.data.current);
    else if (type === 'NODE') setActiveNode(active.data.current?.node);
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    setActiveDragItem(null);
    setActiveNode(null);

    if (!over) return;

    if (active.data.current?.type === 'SOURCE_ABILITY') {
        const { charId, abilityId } = active.data.current;
        const newNode: SequenceNode = {
            id: `node-${Date.now()}`,
            type: 'action',
            data: { charId, abilityId, weaponId: '' },
            children: []
        };

        let targetParentId = 'root';
        const overData = over.data.current || {};

        if (over.id === 'root-canvas') {
            targetParentId = 'root';
        } else if (overData.type === 'CONTAINER') {
            targetParentId = overData.nodeId;
        } else if (overData.type === 'NODE') {
             targetParentId = getParentId(tree, over.id as string) || 'root';
        }

        if (targetParentId !== 'root') {
            const container = findNode(tree, targetParentId);
            if (container && container.type === 'combo' && container.children.length >= 2) {
                return; 
            }
        }

        setTree(prev => {
             if (targetParentId === 'root') return [...prev, newNode];
             return addNodeToContainer(prev, targetParentId, newNode);
        });
        return;
    }

    if (active.data.current?.type === 'NODE') {
        const activeId = active.id as string;
        const activeParentId = getParentId(tree, activeId) || 'root';

        if (!activeId) return;

        let targetParentId = 'root';
        const overId = over.id as string;
        const overData = over.data.current || {};

        if (over.id === 'root-canvas') {
            targetParentId = 'root';
        } else if (overData.type === 'CONTAINER') {
            targetParentId = overData.nodeId;
        } else if (overData.type === 'NODE') {
             targetParentId = getParentId(tree, overId) || 'root';
        }

        if (activeId === overId) return;

        if (targetParentId !== activeParentId && targetParentId !== 'root') {
             const container = findNode(tree, targetParentId);
             if (container && container.type === 'combo' && container.children.length >= 2) {
                 return;
             }
        }

        setTree(items => {
             if (activeParentId === targetParentId) {
                  if (activeParentId === 'root') {
                      const oldIdx = items.findIndex(n => n.id === activeId);
                      const newIdx = items.findIndex(n => n.id === overId);
                      if (oldIdx !== -1 && newIdx !== -1) {
                        return arrayMove(items, oldIdx, newIdx);
                      }
                      return items;
                  } else {
                      return recursiveSort(items, activeId, overId); 
                  }
             }
             return moveNodeBetweenParents(items, activeId, activeParentId, targetParentId, overId);
        });
    }
  };

  const moveNodeBetweenParents = (nodes: SequenceNode[], nodeId: string, sourceParentId: string, targetParentId: string, overId: string): SequenceNode[] => {
      let nodeToMove: SequenceNode | null = null;
      const removeNode = (list: SequenceNode[]): SequenceNode[] => {
          const newList = [];
          for (const item of list) {
              if (item.id === nodeId) {
                  nodeToMove = item;
                  continue;
              }
              if (item.children.length > 0) {
                  const newChildren = removeNode(item.children);
                  if (newChildren !== item.children) {
                      newList.push({ ...item, children: newChildren });
                      continue;
                  }
              }
              newList.push(item);
          }
          return newList;
      };
      const treeWithoutNode = removeNode(nodes);
      if (!nodeToMove) return nodes; 
      const insertNode = (list: SequenceNode[], isRoot: boolean): SequenceNode[] => {
          if (targetParentId === 'root' && isRoot) {
              const newRoot = [...list];
              const overIndex = newRoot.findIndex(n => n.id === overId);
              if (overIndex !== -1) {
                  newRoot.splice(overIndex, 0, nodeToMove!);
              } else {
                  newRoot.push(nodeToMove!);
              }
              return newRoot;
          }
          return list.map(item => {
               if (item.id === targetParentId) {
                   const newChildren = [...item.children];
                   const overIndex = newChildren.findIndex(n => n.id === overId);
                   if (overIndex !== -1) {
                        newChildren.splice(overIndex, 0, nodeToMove!);
                   } else {
                        newChildren.push(nodeToMove!);
                   }
                   return { ...item, children: newChildren };
               }
               if (item.children.length > 0) {
                   return { ...item, children: insertNode(item.children, false) };
               }
               return item;
          });
      };
      return insertNode(treeWithoutNode, true);
  };

  const addNodeToContainer = (nodes: SequenceNode[], targetId: string, newNode: SequenceNode): SequenceNode[] => {
      return nodes.map(node => {
          if (node.id === targetId) return { ...node, children: [...node.children, newNode] };
          if (node.children.length > 0) return { ...node, children: addNodeToContainer(node.children, targetId, newNode) };
          return node;
      });
  };

  const recursiveSort = (nodes: SequenceNode[], activeId: string, overId: string): SequenceNode[] => {
     return nodes.map(node => {
         const activeIndex = node.children.findIndex(c => c.id === activeId);
         const overIndex = node.children.findIndex(c => c.id === overId);
         if (activeIndex !== -1 && overIndex !== -1) return { ...node, children: arrayMove(node.children, activeIndex, overIndex) };
         if (node.children.length > 0) return { ...node, children: recursiveSort(node.children, activeId, overId) };
         return node;
     });
  };

  const removeNode = (id: string) => {
      const recursiveFilter = (nodes: SequenceNode[]): SequenceNode[] => {
          return nodes.filter(n => n.id !== id).map(n => ({ ...n, children: recursiveFilter(n.children) }));
      };
      setTree(prev => recursiveFilter(prev));
  };

  const updateNodeData = (id: string, data: any) => {
      const recursiveUpdate = (nodes: SequenceNode[]): SequenceNode[] => {
          return nodes.map(n => {
              if (n.id === id) return { ...n, data: { ...n.data, ...data } };
              return { ...n, children: recursiveUpdate(n.children) };
          });
      };
      setTree(prev => recursiveUpdate(prev));
  };

  const addBlock = (type: 'combo' | 'condition' | 'divider') => {
      if (type === 'condition') {
          const initialCondition: SequenceNode = {
            id: `cond-${Date.now()}`,
            type: 'condition',
            data: {},
            children: []
          };
          const chainNode: SequenceNode = {
              id: `chain-${Date.now()}`,
              type: 'logic_chain',
              children: [initialCondition]
          };
          setTree(prev => [...prev, chainNode]);
      } else {
          const newNode: SequenceNode = {
              id: `block-${Date.now()}`,
              type,
              data: {},
              children: []
          };
          setTree(prev => [...prev, newNode]);
      }
  };

  const handleAddLogicSibling = (nodeId: string) => {
      const newSibling: SequenceNode = {
          id: `cond-${Date.now()}`,
          type: 'condition',
          data: {},
          children: []
      };
      const recursiveAdd = (nodes: SequenceNode[]): SequenceNode[] => {
          return nodes.map(node => {
              if (node.type === 'logic_chain') {
                  const childExists = node.children.some(c => c.id === nodeId);
                  if (childExists) {
                      return { ...node, children: [...node.children, newSibling] };
                  }
              }
              if (node.children.length > 0) {
                  return { ...node, children: recursiveAdd(node.children) };
              }
              return node;
          });
      };
      setTree(prev => recursiveAdd(prev));
  };

  const updateLog = (newLogs: LogEntry[]) => {
      setLogs(newLogs);
  };

  return (
    <DndContext 
        sensors={sensors}
        collisionDetection={pointerWithin}
        onDragStart={handleDragStart} 
        onDragEnd={handleDragEnd}
    >
        <Modal 
            isOpen={activeModal === 'CHAR_SELECT'} 
            onClose={closeModal} 
            title="Добавить участника"
        >
            <div className="flex flex-col gap-3 mb-4">
                <div className="relative group">
                    <input 
                        type="text" 
                        placeholder="ПОИСК ПО ИМЕНИ..." 
                        value={charSearchTerm}
                        onChange={(e) => setCharSearchTerm(e.target.value)}
                        className="w-full bg-[#0b0d12] border border-violet-900/40 rounded pl-9 pr-2 py-2 text-sm text-white focus:border-violet-500 focus:shadow-glow outline-none transition-all placeholder-slate-600 font-sans"
                    />
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-violet-400" />
                </div>
                <div className="flex gap-2">
                    <div className="flex-1 relative group">
                        <Filter size={14} className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none group-focus-within:text-violet-400"/>
                        <select
                            value={selectedFaction}
                            onChange={(e) => {
                                setSelectedFaction(e.target.value);
                                setSelectedVolume('All');
                            }}
                            className="w-full bg-[#0b0d12] border border-violet-900/40 rounded pl-8 pr-2 py-1.5 text-xs text-white appearance-none outline-none focus:border-violet-500 focus:shadow-glow transition-all"
                        >
                            <option value="All" className="bg-[#0b0d12] text-slate-300">ВСЕ ФРАКЦИИ</option>
