            {tree.map(node => (
                <WikiCategoryNode 
                    key={node.id}
                    node={node}
                    selectedCategoryId={selectedCategoryId}
                    expandedIds={expandedIds}
                    onToggleExpand={toggleExpand}
                    onSelectCategory={(id) => { handleSelectCategory(id); }}
