      {/* Main Content Area */}
      <div className={`flex-1 flex flex-col transition-all duration-300 ${isSidebarOpen ? 'ml-0 min-[1150px]:ml-64' : 'ml-0'} h-full overflow-hidden bg-black/20 relative`}>

