export const exportFullBackup = async () => {
    try {
        const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
        const tables = ['characters', 'battles', 'lore_articles', 'lore_categories', 'maps', 'locations', 'quests', 'library', 'training', 'basic_actions', 'time_units', 'injuries', 'triggers'];
        const backupData: Record<string, any> = {};

        for (const table of tables) {
            const { data, error } = await supabase.from(table).select('*');
            if (!error && data) {
                backupData[table] = data;
            }
        }

        const blob = new Blob([JSON.stringify(backupData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `juul_d_full_backup_${timestamp}.json`;
        a.click();
        URL.revokeObjectURL(url);
        return true;
    } catch (e) {
        console.error("Backup failed", e);
        throw e;
    }
};

export const importFullBackup = async (file: File): Promise<{success: boolean, message: string}> => {
    try {
        const text = await file.text();
        const json = JSON.parse(text);

        // Define import order to respect foreign keys (Categories before Items)
        const tablesOrder = [
            'lore_categories', 
            'lore_articles', 
            'maps', 
            'locations', 
            'characters', // Characters might link to locations/maps, but usually loose coupling in JSONB
            'quests', 
            'battles', 
            'library', 
            'training',
            'basic_actions',
            'time_units',
            'injuries',
            'triggers'
        ];

        let successCount = 0;

        for (const table of tablesOrder) {
            if (json[table] && Array.isArray(json[table]) && json[table].length > 0) {
                console.log(`Importing ${table} (${json[table].length} rows)...`);
                const { error } = await supabase.from(table).upsert(json[table]);
                if (error) {
                    console.warn(`Error importing ${table}:`, error.message);
                } else {
                    successCount++;
                }
            }
        }

        CacheService.clearAll(); // Clear cache to reflect new data
        return { success: true, message: `Восстановлено таблиц: ${successCount}` };
    } catch (e: any) {
        console.error("Import failed", e);
        return { success: false, message: e.message };
    }
};

export const cleanUnusedStorage = async () => {
    try {
        const bucketName = 'Juul-D-Tracker';

        // 1. Get all DB references
        const { data: chars } = await supabase.from('characters').select('data');
        const { data: locations } = await supabase.from('locations').select('img');
        const { data: maps } = await supabase.from('maps').select('image_url');

        const usedFiles = new Set<string>();

        chars?.forEach((row: any) => {
            const url = row.data?.meta?.avatar_url;
            if (url) {
                const parts = url.split('/');
                const filename = parts[parts.length - 1];
                if (filename) usedFiles.add(filename);
            }
        });

        locations?.forEach((row: any) => {
            if (row.img) {
                const parts = row.img.split('/');
                const filename = parts[parts.length - 1];
                if (filename) usedFiles.add(filename);
            }
        });

        maps?.forEach((row: any) => {
            if (row.image_url) {
                const parts = row.image_url.split('/');
                const filename = parts[parts.length - 1];
                if (filename) usedFiles.add(filename);
            }
        });

        // 2. List all files in bucket
        const { data: files, error: listError } = await supabase.storage.from(bucketName).list();
        if (listError) throw listError;

        if (!files) return 0;

        // 3. Find unused
        const filesToDelete = files
            .filter(f => !usedFiles.has(f.name) && f.name !== '.emptyFolderPlaceholder')
            .map(f => f.name);

        if (filesToDelete.length === 0) return 0;

        // 4. Delete
        const { error: deleteError } = await supabase.storage.from(bucketName).remove(filesToDelete);
        if (deleteError) throw deleteError;

        return filesToDelete.length;
    } catch (e) {
        console.error("Cleanup failed", e);
        throw e;
    }
};

import React, { useState, useEffect, useRef } from 'react';
import { InjuryDefinition, TimeUnit, Ability } from '../types';
import { Button, Card, StyledInput, StyledTextarea, BonusInput, TagInput, TimeInput, CommonTagToggles } from './Shared';
import { Settings, X, Save, Trash2, Plus, Clock, Zap, Skull, Swords, Sparkles, Hourglass, Hash, Database, Download, FileText, Eraser, Upload, RefreshCw } from 'lucide-react';
import { useUI } from '../context/UIContext';
import { getBasicActions, saveBasicActions, exportFullBackup, importFullBackup, cleanUnusedStorage } from '../utils/supabaseService';

interface Props {
  onClose: () => void;
  // Triggers
  triggersMap: Record<string, string>;
  onSaveTriggers: (t: Record<string, string>) => Promise<void>;
  // Injuries
  injuryDefinitions: InjuryDefinition[];
  onSaveInjuries: (injuries: InjuryDefinition[]) => Promise<void>;
  // Time Units
  timeUnits: TimeUnit[];
  onSaveTimeUnits: (units: TimeUnit[]) => Promise<void>;
}

const GlobalSettingsModal: React.FC<Props> = ({ 
  onClose, 
  triggersMap, onSaveTriggers,
  injuryDefinitions, onSaveInjuries,
  timeUnits, onSaveTimeUnits
}) => {
  const { showAlert, showConfirm } = useUI();
  const [activeTab, setActiveTab] = useState<'triggers' | 'injuries' | 'time' | 'basic' | 'system'>('triggers');

  // --- Triggers State ---
  const [editingTriggers, setEditingTriggers] = useState<Record<string, string>>({ ...triggersMap });
  const [newTriggerKey, setNewTriggerKey] = useState("");
  const [newTriggerLabel, setNewTriggerLabel] = useState("");

  // --- Injuries State ---
  const [editingInjuries, setEditingInjuries] = useState<InjuryDefinition[]>([...injuryDefinitions]);
  const [newInjury, setNewInjury] = useState<Partial<InjuryDefinition>>({
    tag: "", label: "", value: -5, type: 1, desc: "", stack: undefined
  });

  // --- Time Units State ---
  const [editingTimeUnits, setEditingTimeUnits] = useState<TimeUnit[]>([...timeUnits]);
  const [newTimeTag, setNewTimeTag] = useState("");
  const [newTimeLabel, setNewTimeLabel] = useState("");
  const [newTimeBattle, setNewTimeBattle] = useState(false);

  // --- Basic Actions State ---
  const [basicActions, setBasicActions] = useState<Ability[]>([]);
  const [loadingActions, setLoadingActions] = useState(false);

  // --- System State ---
  const [cleanupStatus, setCleanupStatus] = useState<string | null>(null);
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
      if (activeTab === 'basic') {
          setLoadingActions(true);
          getBasicActions().then(actions => {
              setBasicActions(actions);
              setLoadingActions(false);
          });
      }
  }, [activeTab]);

  // --- Handlers: Triggers ---
  const saveTriggers = async () => {
    await onSaveTriggers(editingTriggers);
    showAlert("Триггеры успешно записаны в архив.", "Сохранено");
  };
  const addTrigger = () => {
    if (newTriggerKey && newTriggerLabel) {
      setEditingTriggers(prev => ({ ...prev, [newTriggerKey]: newTriggerLabel }));
      setNewTriggerKey("");
      setNewTriggerLabel("");
    }
  };
  const removeTrigger = (key: string) => {
     showConfirm("Удалить этот триггер из списка?", () => {
        const next = { ...editingTriggers };
        delete next[key];
        setEditingTriggers(next);
     }, "Удаление");
  };

  // --- Handlers: Injuries ---
  const saveInjuriesHandler = async () => {
    await onSaveInjuries(editingInjuries);
    showAlert("Шаблоны травм обновлены.", "Сохранено");
  };
  const addInjury = () => {
    if (newInjury.tag && newInjury.label) {
      setEditingInjuries(prev => [...prev, {
        tag: newInjury.tag!,
        label: newInjury.label!,
        value: newInjury.value || 0,
        type: newInjury.type || 1,
        desc: newInjury.desc || "",
        stack: newInjury.stack || undefined
      } as InjuryDefinition]);
      setNewInjury({ tag: "", label: "", value: -5, type: 1, desc: "", stack: undefined });
    }
  };
  const removeInjury = (idx: number) => {
    showConfirm("Удалить этот шаблон травмы?", () => {
      setEditingInjuries(prev => prev.filter((_, i) => i !== idx));
    }, "Удаление");
  };
  const updateInjury = (idx: number, field: keyof InjuryDefinition, val: any) => {
     const next = [...editingInjuries];
     next[idx] = { ...next[idx], [field]: val };
     setEditingInjuries(next);
  };

  // --- Handlers: Time Units ---
  const saveTimeUnitsHandler = async () => {
    await onSaveTimeUnits(editingTimeUnits);
    showAlert("Единицы времени зафиксированы.", "Сохранено");
  };
  const addTimeUnit = () => {
    if (newTimeTag && newTimeLabel) {
      // Prevent duplicate tags
      if (editingTimeUnits.some(u => u.tag === newTimeTag)) {
         showAlert("Такой тег уже существует!", "Ошибка");
         return;
      }
      setEditingTimeUnits(prev => [...prev, { tag: newTimeTag, label: newTimeLabel, battle: newTimeBattle }]);
      setNewTimeTag("");
      setNewTimeLabel("");
      setNewTimeBattle(false);
    }
  };
  const removeTimeUnit = (idx: number) => {
     setEditingTimeUnits(prev => prev.filter((_, i) => i !== idx));
  };
  const updateTimeUnit = (idx: number, field: keyof TimeUnit, val: any) => {
     const next = [...editingTimeUnits];
     next[idx] = { ...next[idx], [field]: val };
     setEditingTimeUnits(next);
  };

  // --- Handlers: Basic Actions ---
  const addBasicAction = () => {
      setBasicActions(prev => [...prev, {
          name: "Новое Действие",
          bonuses: [],
          tags: [],
          desc_lore: "",
          desc_mech: "",
          cd: 0, cd_unit: "",
          dur: 0, dur_unit: "",
          limit: 0, limit_unit: ""
      }]);
  };
  const updateBasicAction = (idx: number, field: string, val: any) => {
      setBasicActions(prev => {
          const next = [...prev];
          next[idx] = { ...next[idx], [field]: val };
          return next;
      });
