          {/* Footer Actions (Conditional) */}
          {activeTab !== 'system' && (
            <div className="relative z-10 p-5 border-t border-violet-500/20 bg-[#0b0d12]/90 backdrop-blur">
                <div className="flex gap-4">
                {activeTab === 'triggers' && (
                    <button onClick={saveTriggers} className="flex-1 py-3 bg-cyan-900/20 border border-cyan-500/50 text-cyan-300 font-serif uppercase tracking-widest text-sm hover:bg-cyan-900/40 hover:shadow-[0_0_15px_rgba(34,211,238,0.2)] transition-all">
                        Сохранить Триггеры
                    </button>
                )}
                {activeTab === 'injuries' && (
                    <button onClick={saveInjuriesHandler} className="flex-1 py-3 bg-red-900/20 border border-red-500/50 text-red-300 font-serif uppercase tracking-widest text-sm hover:bg-red-900/40 hover:shadow-[0_0_15px_rgba(248,113,113,0.2)] transition-all">
                        Обновить Протоколы Травм
                    </button>
                )}
                {activeTab === 'time' && (
                    <button onClick={saveTimeUnitsHandler} className="flex-1 py-3 bg-amber-900/20 border border-amber-500/50 text-amber-300 font-serif uppercase tracking-widest text-sm hover:bg-amber-900/40 hover:shadow-[0_0_15px_rgba(251,191,36,0.2)] transition-all">
                        Синхронизировать Время
                    </button>
                )}
                {activeTab === 'basic' && (
                    <button onClick={saveBasicActionsHandler} className="flex-1 py-3 bg-emerald-900/20 border border-emerald-500/50 text-emerald-300 font-serif uppercase tracking-widest text-sm hover:bg-emerald-900/40 hover:shadow-[0_0_15px_rgba(16,185,129,0.2)] transition-all">
                        Кодифицировать Действия
                    </button>
                )}
                </div>
            </div>
          )}

       </div>
    </div>
  );
};

export default GlobalSettingsModal;

payload.text:
Для того чтобы применить политики сразу ко всем таблицам, лучше всего использовать **SQL Editor** в панели Supabase.

Я подготовил полный скрипт. Он делает следующее:
1.  Создает удобную функцию `is_admin()` (чтобы не писать сложные проверки каждый раз).
2.  Включает защиту (RLS) для всех таблиц.
3.  Настраивает права:
    *   **Все:** Могут читать всё (Public Read).
    *   **Админы:** Могут менять всё.
    *   **Владельцы персонажей:** Могут менять **только своих** персонажей (проверка по JSON полю).
    *   **Профили:** Пользователи могут менять свои аватарки/имена.

### Инструкция:
1.  Зайди в Supabase -> **SQL Editor**.
2.  Создай "New Query".
3.  Вставь код ниже и нажми **Run**.

```sql
-- 1. Создаем функцию для быстрой проверки на админа
-- Это упростит все последующие политики
CREATE OR REPLACE FUNCTION is_admin()
RETURNS BOOLEAN AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM profiles
    WHERE id = auth.uid() AND role = 'admin'
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ==========================================
-- ГРУППА 1: СИСТЕМНЫЕ ТАБЛИЦЫ (Лор, Настройки, Карты)
-- Правило: Читают все, меняет только Админ.
-- ==========================================

DO $$
DECLARE
    -- Список таблиц, где контент создает только админ (или ГМ)
    tables text[] := ARRAY[
        'lore_articles', 
        'lore_categories', 
        'maps', 
        'locations', 
        'quests', 
        'library', 
        'basic_actions', 
        'time_units', 
        'injuries', 
        'triggers',
        'battles' -- Бои тоже оставим под управлением админа для безопасности
    ];
    tbl text;
BEGIN
    FOREACH tbl IN ARRAY tables LOOP
        -- Включаем RLS
        EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY;', tbl);

        -- Удаляем старые политики, чтобы не было конфликтов
        EXECUTE format('DROP POLICY IF EXISTS "Public Read" ON %I;', tbl);
        EXECUTE format('DROP POLICY IF EXISTS "Admin Write" ON %I;', tbl);

        -- Политика: Чтение для всех
        EXECUTE format('CREATE POLICY "Public Read" ON %I FOR SELECT USING (true);', tbl);

        -- Политика: Запись/Удаление только для админов
        EXECUTE format('CREATE POLICY "Admin Write" ON %I FOR ALL USING (is_admin());', tbl);
    END LOOP;
END $$;

-- ==========================================
-- ГРУППА 2: ПЕРСОНАЖИ (Сложная логика JSON)
-- Правило: Читают все, меняет Админ ИЛИ Владелец (по полю meta.uid)
-- ==========================================

ALTER TABLE characters ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public Read Characters" ON characters;
DROP POLICY IF EXISTS "Owner/Admin Manage Characters" ON characters;
DROP POLICY IF EXISTS "Authenticated Insert Characters" ON characters;

-- 1. Читать могут все
CREATE POLICY "Public Read Characters" 
ON characters FOR SELECT 
USING (true);

-- 2. Создавать могут все зарегистрированные
CREATE POLICY "Authenticated Insert Characters" 
ON characters FOR INSERT 
WITH CHECK (auth.role() = 'authenticated');

-- 3. Обновлять/Удалять: Админ ИЛИ если ID в JSON совпадает с ID юзера
CREATE POLICY "Owner/Admin Manage Characters" 
ON characters FOR ALL 
USING (
    is_admin() 
    OR 
    (data->'meta'->>'uid')::text = auth.uid()::text
);

-- ==========================================
-- ГРУППА 3: ТРЕНИРОВКИ (Связаны с персонажем)
-- Правило: Если ты владелец персонажа, ты можешь менять его тренировки
-- ==========================================

ALTER TABLE training ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public Read Training" ON training;
DROP POLICY IF EXISTS "Owner Manage Training" ON training;

CREATE POLICY "Public Read Training" 
ON training FOR SELECT 
USING (true);

-- Разрешаем запись, если юзер владеет персонажем, указанным в char_id
CREATE POLICY "Owner Manage Training" 
ON training FOR ALL 
USING (
    is_admin()
    OR
    EXISTS (
        SELECT 1 FROM characters 
        WHERE characters.id = training.char_id 
        AND (characters.data->'meta'->>'uid')::text = auth.uid()::text
    )
);

-- ==========================================
-- ГРУППА 4: ПРОФИЛИ ПОЛЬЗОВАТЕЛЕЙ
-- ==========================================

ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public Read Profiles" ON profiles;
DROP POLICY IF EXISTS "Users Update Own Profile" ON profiles;

CREATE POLICY "Public Read Profiles" 
ON profiles FOR SELECT 
USING (true);

CREATE POLICY "Users Update Own Profile" 
ON profiles FOR UPDATE 
USING ( id = auth.uid() );

-- ==========================================
-- ГРУППА 5: ХРАНИЛИЩЕ (STORAGE)
-- Нужно для загрузки аватарок.
-- ==========================================

-- Разрешаем загрузку файлов в бакет 'Juul-D-Tracker' всем авторизованным
-- (В Supabase Storage политики создаются отдельно через UI или SQL ниже)

BEGIN;
  -- Создаем политику для storage.objects
  DROP POLICY IF EXISTS "Give public access to images" ON storage.objects;
  DROP POLICY IF EXISTS "Allow authenticated uploads" ON storage.objects;
  DROP POLICY IF EXISTS "Allow owners to delete" ON storage.objects;

  -- Чтение картинок доступно всем
  CREATE POLICY "Give public access to images" ON storage.objects FOR SELECT USING ( bucket_id = 'Juul-D-Tracker' );

  -- Загрузка только для авторизованных
  CREATE POLICY "Allow authenticated uploads" ON storage.objects FOR INSERT WITH CHECK (
    bucket_id = 'Juul-D-Tracker' AND auth.role() = 'authenticated'
  );

  -- Удаление (для скрипта очистки) - только админ
  CREATE POLICY "Allow admin delete" ON storage.objects FOR DELETE USING (
    bucket_id = 'Juul-D-Tracker' AND is_admin()
  );
COMMIT;
```

### Важные примечания:

1.  **Поле `meta.uid`**: Убедитесь, что при создании персонажа (в `src/modules/roster/App.tsx` функция `handleCreate`) вы действительно записываете ID текущего пользователя в поле `meta.uid`. Если там записано `'system'` или пустота, обычный пользователь не сможет редактировать созданного персонажа.
    *   *Совет:* В коде создания персонажа добавьте: `newChar.meta.uid = user?.id || 'system';`
2.  **Backup Restore**: Функция `importFullBackup`, которую мы написали ранее, использует `upsert`. Так как она будет запускаться, скорее всего, от имени **Админа**, политика `is_admin()` позволит ей перезаписать любые данные без ограничений.

