                      )}
                   </div>
                 </div>

                 {!isEditMode && res.max > 0 && (
                   <div className="w-full bg-[#020408] h-1.5 rounded-full overflow-hidden mt-2 relative z-10 border border-slate-800">
                     <div 
                        className="h-full bg-violet-600 transition-all duration-500 shadow-[0_0_5px_#7c3aed]" 
                        style={{ width: `${Math.min(100, (res.current / res.max) * 100)}%` }}
                     ></div>
                   </div>
                 )}
               </div>

               {isEditMode && (
                  <button onClick={() => removeResource(idx)} className="text-slate-600 hover:text-red-500 transition-colors p-1">
                    <Trash2 size={14} />
                  </button>
               )}
            </div>
          ))}

          {isEditMode && (
            <Button size="sm" variant="secondary" onClick={addResource} className="w-full border-dashed border-slate-700 text-slate-500 hover:text-white font-serif uppercase tracking-wider">
              {/* [DIALECT] */}
              <Plus size={14} /> {t('btn_add_res', 'Добавить')}
            </Button>
          )}
        </div>
      </div>
    </div>
  );
};

export default SheetHeader;

import React, { useState, useMemo } from 'react';
import { CharacterData, TimeUnit, StatType, Bonus } from '../types';
import { Card, StyledInput, StyledTextarea, Button, BonusInput, TagInput, TimeInput, TabRadarCharts, CommonTagToggles } from './Shared';
import { Plus, Trash2, Clock, Hourglass, ChevronDown, ChevronRight, Eye, EyeOff, Hash, Check, X } from 'lucide-react';
import { DisplayMode } from '../App';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  displayMode: DisplayMode;
  onChange: (groups: CharacterData['ability_groups']) => void;
  timeUnits: TimeUnit[];
}

const TabAbilities: React.FC<Props> = ({ character, isEditMode, displayMode, onChange, timeUnits }) => {
  const { ability_groups } = character;
  const [collapsedGroups, setCollapsedGroups] = useState<Record<number, boolean>>({});
  const [deleteConfirmGroupIdx, setDeleteConfirmGroupIdx] = useState<number | null>(null);
  /* [DIALECT] */ const { t } = useDialect();

  const toggleGroup = (idx: number) => {
    setCollapsedGroups(prev => ({ ...prev, [idx]: !prev[idx] }));
  };

  const updateGroup = (idx: number, field: string, val: any) => {
    const next = [...ability_groups];
    next[idx] = { ...next[idx], [field]: val };
    onChange(next);
  };

  const addGroup = () => onChange([...ability_groups, { name: "Новая Школа", tags: [], abilities: [], is_hidden: false }]);

  const removeGroup = (idx: number) => {
     const next = ability_groups.filter((_, i) => i !== idx);
     onChange(next);

     // Clean up collapsed state & delete state
     const newCollapsed = { ...collapsedGroups };
     delete newCollapsed[idx];
     setCollapsedGroups(newCollapsed);
     setDeleteConfirmGroupIdx(null);
  };

  const addAbility = (gIdx: number) => {
    const next = [...ability_groups];
    // Deep clone the group to avoid mutation
    const group = { ...next[gIdx] };
    group.abilities = [...(group.abilities || [])];

    group.abilities.push({ 
      name: "Новый Навык", bonuses: [], tags: [], desc_lore: "", desc_mech: "",
      cd: 0, cd_unit: "", dur: 0, dur_unit: "", limit: 0, limit_unit: ""
    });

    next[gIdx] = group;
    onChange(next);
  };

  const updateAbility = (gIdx: number, aIdx: number, field: string, val: any) => {
    const next = [...ability_groups];
    // Deep clone logic
    const group = { ...next[gIdx] };
    group.abilities = [...group.abilities];
    group.abilities[aIdx] = { ...group.abilities[aIdx], [field]: val };
    next[gIdx] = group;
    onChange(next);
  };

  const removeAbility = (gIdx: number, aIdx: number) => {
    const next = [...ability_groups];
    const group = { ...next[gIdx] };
    group.abilities = [...group.abilities];
    group.abilities.splice(aIdx, 1);
    next[gIdx] = group;
    onChange(next);
  };

  const shouldShowLore = displayMode === 'lore';
  const shouldShowMech = displayMode === 'mech';

  // --- Derived Data for Charts (Memoized to prevent flickering during text edits) ---
  const structureData = useMemo(() => {
      // Optimization: Skip calculation in Edit Mode
      if (isEditMode) return [];

      const data = ability_groups.map((g, i) => {
        const name = g.name || "Unknown";
        let baseName = name.length > 10 ? name.substring(0, 8) + '..' : name;
        return {
          subject: baseName + '\u200B'.repeat(i), 
          value: g.abilities ? g.abilities.length : 0
        };
      });
      // Pad to at least 3 points for radar chart
      while (data.length < 3) {
          data.push({ 
              subject: '\u200B'.repeat(100 + data.length), 
              value: 0 
          });
      }
      return data;
  }, [ability_groups, isEditMode]); // Depend on isEditMode

  const bonusData = useMemo(() => {
      // Optimization: Skip calculation in Edit Mode
      if (isEditMode) return [];

      let phys = 0, magic = 0, unique = 0;
      ability_groups.forEach(g => {
        if (Array.isArray(g.abilities)) {
          g.abilities.forEach(item => {
            if (Array.isArray(item.bonuses)) {
              item.bonuses.forEach(b => {
                 const val = Number(b.val);
                 if (!Number.isNaN(val)) {
                    if (b.stat === StatType.PHYS) phys += val;
                    if (b.stat === StatType.MAGIC) magic += val;
                    if (b.stat === StatType.UNIQUE) unique += val;
                 }
              });
            }
          });
        }
      });

      const getValue = (v: number) => Math.max(0, v); // Only positive for abilities

      return [
        { subject: t('stat_phys_short', 'ФИЗ'), value: getValue(phys) },
        { subject: t('stat_mag_short', 'МАГ'), value: getValue(magic) },
        { subject: t('stat_uni_short', 'УНИК'), value: getValue(unique) },
      ];
  }, [ability_groups, t, isEditMode]);

  return (
    <div className="space-y-8 animate-fade-in">

      {/* Charts Visualization - Explicit Cyan Color */}
      {/* PERFORMANCE FIX: Only render charts in View Mode */}
      {!isEditMode && (
          <TabRadarCharts 
              structureData={structureData} 
              bonusData={bonusData} 
              color="#06b6d4" 
              t={t}
          />
      )}

      {ability_groups.map((group, gIdx) => {
        // Hide if not in edit mode AND either empty or explicitly hidden
        if (!isEditMode && (group.abilities.length === 0 || group.is_hidden)) return null;

        const isCollapsed = collapsedGroups[gIdx];
        const isHidden = group.is_hidden;

        return (
          // Use Index as key to prevent re-mounting on name change
          <div key={gIdx} className={`space-y-4 transition-all ${isHidden && isEditMode ? 'opacity-70 border-2 border-dashed border-gray-800 p-4 rounded-xl bg-gray-900/20' : ''}`}>
             {/* Header */}
             <div className="flex items-center gap-4 border-b border-gray-800 pb-2 bg-slate-900/90 p-3 rounded-t-lg backdrop-blur-sm shadow-md">
               <button onClick={() => toggleGroup(gIdx)} className="text-gray-500 hover:text-cyan-400 transition-colors p-1">
                  {isCollapsed ? <ChevronRight size={24}/> : <ChevronDown size={24} />}
               </button>
               <div className="flex-1">
                 <StyledInput 
                   isEditMode={isEditMode} 
                   value={group.name} 
                   onChange={e => updateGroup(gIdx, 'name', e.target.value)} 
                   className="text-xl font-bold text-cyan-500 uppercase tracking-widest bg-transparent border-none p-0" 
                 />
                 {/* [DIALECT] */}
                 {isHidden && isEditMode && <span className="text-[10px] uppercase font-bold text-gray-500 block -mt-1">{t('lbl_hidden_group', "Скрытая группа")}</span>}
               </div>

               {!isCollapsed && <TagInput isEditMode={isEditMode} tags={group.tags || []} onChange={t => updateGroup(gIdx, 'tags', t)} />}

               {isEditMode && (
                 <>
                   <button 
                     onClick={() => updateGroup(gIdx, 'is_hidden', !isHidden)} 
                     className={`p-1.5 rounded transition-colors ${isHidden ? 'bg-gray-800 text-gray-400 hover:text-white' : 'text-cyan-600 hover:text-cyan-400'}`}
                     title={isHidden ? "Показать в листе" : "Скрыть из листа"}
                   >
                     {isHidden ? <EyeOff size={16}/> : <Eye size={16}/>}
                   </button>

                   {/* Delete Confirm Logic */}
                   {deleteConfirmGroupIdx === gIdx ? (
                     <div className="flex items-center gap-1">
                        <Button size="sm" variant="danger" onClick={() => removeGroup(gIdx)}><Check size={14} /></Button>
                        <Button size="sm" variant="secondary" onClick={() => setDeleteConfirmGroupIdx(null)}><X size={14} /></Button>
                     </div>
                   ) : (
                     <Button size="sm" variant="danger" onClick={() => setDeleteConfirmGroupIdx(gIdx)}><Trash2 size={14} /></Button>
                   )}
                 </>
               )}
             </div>

             {/* Content */}
             {!isCollapsed && (
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-in">
                 {group.abilities.map((ability, aIdx) => (
                   <Card key={aIdx} className="hover:border-gray-700 transition-colors bg-[#0b0d10] border-gray-800">
                      <div className="flex justify-between items-start mb-2 overflow-hidden">
                         <div className="flex-1 min-w-0 mr-2" title={ability.name}>
                           <StyledInput 
                              isEditMode={isEditMode} 
                              value={ability.name} 
                              onChange={e => updateAbility(gIdx, aIdx, 'name', e.target.value)} 
                              className="font-bold text-lg truncate block w-full" 
                              // [DIALECT]
                              placeholder={t('ph_ability_name', "Название навыка")}
                           />
                         </div>
                         {isEditMode && <button onClick={() => removeAbility(gIdx, aIdx)} className="text-red-900 hover:text-red-500 transition-colors flex-shrink-0"><Trash2 size={14}/></button>}
                      </div>

                      {/* Mech Details (Hidden in Lore Mode unless Editing) */}
                      {(shouldShowMech || isEditMode) && (
                        <div className="flex flex-wrap gap-2 mb-2">
                          <BonusInput isEditMode={isEditMode} bonuses={ability.bonuses} onChange={b => updateAbility(gIdx, aIdx, 'bonuses', b)} />
                          <TimeInput 
                            icon={Clock} label="КД" isEditMode={isEditMode} 
                            val={ability.cd} unit={ability.cd_unit} 
                            onChangeVal={v => updateAbility(gIdx, aIdx, 'cd', v)} 
                            onChangeUnit={u => updateAbility(gIdx, aIdx, 'cd_unit', u)} 
                            options={timeUnits}
                          />
                          <TimeInput 
                            icon={Hourglass} label="Длит." isEditMode={isEditMode} 
                            val={ability.dur} unit={ability.dur_unit} 
                            onChangeVal={v => updateAbility(gIdx, aIdx, 'dur', v)} 
                            onChangeUnit={u => updateAbility(gIdx, aIdx, 'dur_unit', u)} 
                            options={timeUnits}
                          />
                          {/* Limit input */}
                          <TimeInput 
                            icon={Hash} label="Лимит" isEditMode={isEditMode} 
                            val={ability.limit || 0} unit={ability.limit_unit || ""} 
                            onChangeVal={v => updateAbility(gIdx, aIdx, 'limit', v)} 
                            onChangeUnit={u => updateAbility(gIdx, aIdx, 'limit_unit', u)} 
                            options={timeUnits}
                          />
                        </div>
                      )}

                      <div className="mb-3">
                         <TagInput isEditMode={isEditMode} tags={ability.tags || []} onChange={t => updateAbility(gIdx, aIdx, 'tags', t)} />
                         {isEditMode && <CommonTagToggles tags={ability.tags || []} onChange={t => updateAbility(gIdx, aIdx, 'tags', t)} />}
                      </div>

                      {/* Lore Text */}
                      {(shouldShowLore || isEditMode) && (
                        <StyledTextarea 
                          isEditMode={isEditMode} 
                          value={ability.desc_lore} 
                          onChange={e => updateAbility(gIdx, aIdx, 'desc_lore', e.target.value)} 
                          className="text-sm text-gray-400 italic mb-2" 
                          // [DIALECT]
                          placeholder={t('ph_ability_lore', "Худ. описание")}
                        />
                      )}

                      {/* Mech Text - Green Highlight */}
                      {(shouldShowMech || isEditMode) && (isEditMode || ability.desc_mech) && (
                        <div className={`pt-2 ${!isEditMode && shouldShowLore ? 'border-t border-gray-800' : ''}`}>
                          <StyledTextarea 
                            isEditMode={isEditMode} 
                            value={ability.desc_mech} 
                            onChange={e => updateAbility(gIdx, aIdx, 'desc_mech', e.target.value)} 
                            className={`text-xs font-mono leading-relaxed ${isEditMode ? 'text-green-400' : 'text-green-500/80'}`} 
                            // [DIALECT]
                            placeholder={t('ph_ability_mech', "Механика")} 
                          />
                        </div>
                      )}
                   </Card>
                 ))}
                 {isEditMode && (
                   <button onClick={() => addAbility(gIdx)} className="border-2 border-dashed border-gray-800 rounded-lg flex items-center justify-center text-gray-700 hover:text-cyan-500 hover:border-cyan-900 transition-all min-h-[150px] bg-slate-900/50 backdrop-blur-sm">
                     <Plus size={24} />
                   </button>
                 )}
               </div>
             )}
          </div>
        );
      })}

      {/* [DIALECT] */}
      {isEditMode && <Button onClick={addGroup} className="w-full py-4 border-dashed border-2 bg-slate-900/50 backdrop-blur-sm border-gray-800 text-gray-600 hover:text-white hover:border-gray-600">
         {t('btn_add_school', "Создать новую школу")}
      </Button>}
    </div>
  );
};

export default TabAbilities;

import React, { useState, useMemo } from 'react';
import { CharacterData, TimeUnit, StatType, Bonus } from '../types';
import { Card, StyledInput, StyledTextarea, Button, BonusInput, TagInput, TimeInput, TabRadarCharts, CommonTagToggles } from './Shared';
import { Plus, Trash2, Clock, Hourglass, Check, X, ChevronRight, ChevronDown, Eye, EyeOff } from 'lucide-react';
import { DisplayMode } from '../App';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  displayMode: DisplayMode;
  onChange: (p: CharacterData['passives']) => void;
  triggersMap: Record<string, string>;
  timeUnits: TimeUnit[];
}

const TabPassives: React.FC<Props> = ({ character, isEditMode, displayMode, onChange, triggersMap, timeUnits }) => {
  const { passives } = character;
  const [collapsedGroups, setCollapsedGroups] = useState<Record<number, boolean>>({});
  const [deleteConfirmGroupIdx, setDeleteConfirmGroupIdx] = useState<number | null>(null);
  /* [DIALECT] */ const { t } = useDialect();

  const toggleGroup = (idx: number) => {
    setCollapsedGroups(prev => ({ ...prev, [idx]: !prev[idx] }));
  };

  const updateGroup = (gIdx: number, field: string, val: any) => {
    const next = [...passives];
    next[gIdx] = { ...next[gIdx], [field]: val };
    onChange(next);
  };

  const addGroup = () => onChange([...passives, { group_name: "Классовые", tags: [], items: [], is_flaw_group: false }]);

  const removeGroup = (idx: number) => { 
     const next = passives.filter((_, i) => i !== idx);
     onChange(next);
     setDeleteConfirmGroupIdx(null);
     // Clean up collapsed state
     const newCollapsed = { ...collapsedGroups };
     delete newCollapsed[idx];
     setCollapsedGroups(newCollapsed);
  };

  const addItem = (gIdx: number) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...(group.items || [])];
    group.items.push({ 
      name: "Новая черта", 
      bonuses: [], 
      trigger: Object.keys(triggersMap)[0] || "Always", 
      tags: [], 
      desc_lore: "", 
      desc_mech: "", 
      is_flaw: false,
      cd: 0, cd_unit: "", dur: 0, dur_unit: ""
    });
    next[gIdx] = group;
    onChange(next);
  };

  const updateItem = (gIdx: number, iIdx: number, field: string, val: any) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...group.items];
    group.items[iIdx] = { ...group.items[iIdx], [field]: val };
    next[gIdx] = group;
    onChange(next);
  };

  const removeItem = (gIdx: number, iIdx: number) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...group.items];
    group.items.splice(iIdx, 1);
    next[gIdx] = group;
    onChange(next);
  };

  const shouldShowLore = displayMode === 'lore';
  const shouldShowMech = displayMode === 'mech';

  // --- Derived Data for Charts (Memoized) ---
  const structureData = useMemo(() => {
      // Optimization: Skip calculation in Edit Mode
      if (isEditMode) return [];

      const positiveGroups = passives.filter(g => !g.is_flaw_group);

      const data = positiveGroups.map((g, i) => {
        const name = g.group_name || "Unknown";
        let baseName = name.length > 10 ? name.substring(0, 8) + '..' : name;
        return {
          subject: baseName + '\u200B'.repeat(i), 
          value: g.items ? g.items.length : 0
        };
      });
      while (data.length < 3) {
          data.push({ subject: '\u200B'.repeat(100 + data.length), value: 0 });
      }
      return data;
  }, [passives, isEditMode]);

  const bonusData = useMemo(() => {
      // Optimization: Skip calculation in Edit Mode
      if (isEditMode) return [];

      let phys = 0, magic = 0, unique = 0;
      // Iterate only positive groups
      passives.filter(g => !g.is_flaw_group).forEach(g => {
        if (Array.isArray(g.items)) {
          g.items.forEach(item => {
            if (Array.isArray(item.bonuses)) {
              item.bonuses.forEach(b => {
                 const val = Number(b.val);
                 if (!Number.isNaN(val)) {
                    if (b.stat === StatType.PHYS) phys += val;
                    if (b.stat === StatType.MAGIC) magic += val;
                    if (b.stat === StatType.UNIQUE) unique += val;
                 }
              });
            }
          });
        }
      });

      const getValue = (v: number) => Math.max(0, v); 

      return [
        { subject: t('stat_phys_short', 'ФИЗ'), value: getValue(phys) },
        { subject: t('stat_mag_short', 'МАГ'), value: getValue(magic) },
        { subject: t('stat_uni_short', 'УНИК'), value: getValue(unique) },
      ];
  }, [passives, t, isEditMode]);

  return (
    <div className="space-y-8 animate-fade-in relative">

      {/* Charts Visualization - Explicit Emerald Color */}
      {/* PERFORMANCE FIX: Only render charts in View Mode */}
      {!isEditMode && (
          <TabRadarCharts 
              structureData={structureData} 
              bonusData={bonusData} 
              color="#10b981" 
              t={t}
          />
      )}

      {passives.map((group, gIdx) => {
         // IMPORTANT: Skip if this is a DEBUFF group
         if (group.is_flaw_group) return null;

         // Check if hidden property is set (we'll treat it like abilities)
         const isHidden = (group as any).is_hidden;
         const visibleItems = group.items; 

         // Logic for visibility: Edit Mode sees all. View Mode hides hidden groups OR empty groups
         if (!isEditMode && (visibleItems.length === 0 || isHidden)) return null;

         const isCollapsed = collapsedGroups[gIdx];

         return (
           // Use Index as key to prevent re-mounting on input
           <div key={gIdx} className={`space-y-4 transition-all ${isHidden && isEditMode ? 'opacity-70 border-2 border-dashed border-gray-800 p-4 rounded-xl bg-gray-900/20' : ''}`}>
             <div className="border-b border-gray-800 pb-2 bg-slate-900/90 p-3 rounded-t-lg backdrop-blur-sm shadow-md">
                <div className="flex items-center justify-between mb-2 gap-4">
                   <button onClick={() => toggleGroup(gIdx)} className="text-gray-500 hover:text-emerald-400 transition-colors p-1">
                      {isCollapsed ? <ChevronRight size={24}/> : <ChevronDown size={24} />}
                   </button>

                   <div className="flex-1">
                       <StyledInput isEditMode={isEditMode} value={group.group_name} onChange={e => updateGroup(gIdx, 'group_name', e.target.value)} className="text-xl font-bold text-emerald-500 uppercase tracking-widest bg-transparent border-none p-0" />
                       {isHidden && isEditMode && <span className="text-[10px] uppercase font-bold text-gray-500 block -mt-1">{t('lbl_hidden_group', "Скрытая группа")}</span>}
                   </div>

                   {/* Edit Actions */}
                   {isEditMode && (
                     <div className="flex items-center gap-2">
                        <button 
                            onClick={() => updateGroup(gIdx, 'is_hidden', !isHidden)} 
                            className={`p-1.5 rounded transition-colors ${isHidden ? 'bg-gray-800 text-gray-400 hover:text-white' : 'text-emerald-600 hover:text-emerald-400'}`}
                            title={isHidden ? "Показать в листе" : "Скрыть из листа"}
                        >
                            {isHidden ? <EyeOff size={16}/> : <Eye size={16}/>}
                        </button>

                        {deleteConfirmGroupIdx === gIdx ? (
                           <div className="flex items-center gap-1">
                              <Button size="sm" variant="danger" onClick={() => removeGroup(gIdx)}><Check size={14} /></Button>
                              <Button size="sm" variant="secondary" onClick={() => setDeleteConfirmGroupIdx(null)}><X size={14} /></Button>
                           </div>
                         ) : (
                           <Button size="sm" variant="danger" onClick={() => setDeleteConfirmGroupIdx(gIdx)}><Trash2 size={14}/></Button>
                         )}
                     </div>
                   )}
                </div>

                {!isCollapsed && <TagInput isEditMode={isEditMode} tags={group.tags || []} onChange={t => updateGroup(gIdx, 'tags', t)} />}
             </div>

             {!isCollapsed && (
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                   {visibleItems.map((item, iIdx) => (
                     <Card key={iIdx} className="relative bg-[#0b0d10] border-gray-800 border-l-4 border-l-emerald-500">
                        <div className="flex justify-between items-start mb-2 overflow-hidden">
                          <div className="flex-1 min-w-0 mr-2" title={item.name}>
                            <StyledInput 
                              isEditMode={isEditMode} 
                              value={item.name} 
                              onChange={e => updateItem(gIdx, iIdx, 'name', e.target.value)} 
                              className="font-bold text-lg truncate block w-full text-emerald-300" 
                            />
                          </div>
                          <div className="flex items-center gap-2 flex-shrink-0">
                            {isEditMode && <button onClick={() => removeItem(gIdx, iIdx)} className="text-red-900 hover:text-red-500"><Trash2 size={14}/></button>}
                          </div>
                        </div>

                        {(shouldShowMech || isEditMode) && (
                          <div className="flex flex-wrap items-center gap-2 mb-2">
                             {isEditMode ? (
                               <select value={item.trigger} onChange={e => updateItem(gIdx, iIdx, 'trigger', e.target.value)} className="bg-gray-800 text-xs border border-gray-700 rounded p-1 max-w-[200px]">
                                 {Object.entries(triggersMap).map(([key, label]) => (
                                   <option key={key} value={key}>{label}</option>
                                 ))}
                               </select>
                             ) : (
                               <span className="text-[10px] font-bold uppercase bg-gray-800 px-2 py-0.5 rounded border border-gray-700 text-gray-500">
                                 {triggersMap[item.trigger] || item.trigger}
                               </span>
                             )}
                             <BonusInput isEditMode={isEditMode} bonuses={item.bonuses} onChange={b => updateItem(gIdx, iIdx, 'bonuses', b)} />
                          </div>
                        )}

                        {(shouldShowMech || isEditMode) && (
                          <div className="flex flex-wrap gap-2 mb-2">
                             <TimeInput 
                              icon={Clock} label="КД" isEditMode={isEditMode} 
                              val={item.cd} unit={item.cd_unit} 
                              onChangeVal={v => updateItem(gIdx, iIdx, 'cd', v)} 
                              onChangeUnit={u => updateItem(gIdx, iIdx, 'cd_unit', u)} 
                              options={timeUnits}
                            />
                            <TimeInput 
                              icon={Hourglass} label="Длит." isEditMode={isEditMode} 
                              val={item.dur} unit={item.dur_unit} 
                              onChangeVal={v => updateItem(gIdx, iIdx, 'dur', v)} 
                              onChangeUnit={u => updateItem(gIdx, iIdx, 'dur_unit', u)} 
                              options={timeUnits}
                            />
                          </div>
                        )}

                        <div className="mb-2">
                           <TagInput isEditMode={isEditMode} tags={item.tags || []} onChange={t => updateItem(gIdx, iIdx, 'tags', t)} />
                           {isEditMode && <CommonTagToggles tags={item.tags || []} onChange={t => updateItem(gIdx, iIdx, 'tags', t)} />}
                        </div>

                        {(shouldShowLore || isEditMode) && (
                          <StyledTextarea 
                            isEditMode={isEditMode} 
                            value={item.desc_lore} 
                            onChange={e => updateItem(gIdx, iIdx, 'desc_lore', e.target.value)} 
                            className="text-sm text-gray-400 italic mb-2" 
                            // [DIALECT]
                            placeholder={t('ph_lore_generic', "Худ. описание")}
                          />
                        )}
                        {(shouldShowMech || isEditMode) && (isEditMode || item.desc_mech) && (
                          <StyledTextarea 
                            isEditMode={isEditMode} 
                            value={item.desc_mech} 
                            onChange={e => updateItem(gIdx, iIdx, 'desc_mech', e.target.value)} 
                            className={`text-xs font-mono ${isEditMode ? 'text-green-400' : 'text-green-500/80'}`} 
                            // [DIALECT]
                            placeholder={t('ph_mech_generic', "Механика (Эффект)")}
                          />
                        )}
                     </Card>
                   ))}
                   {isEditMode && <Button onClick={() => addItem(gIdx)} variant="secondary" className="border-dashed"><Plus size={14} /> 
                      {/* [DIALECT] */}
                      {t('btn_add_passive', "Добавить черту")}
                   </Button>}
                 </div>
             )}
           </div>
         );
      })}
       {isEditMode && <Button onClick={addGroup} className="w-full py-4 border-dashed border-2 bg-slate-900/50 backdrop-blur-sm border-gray-800 text-gray-500 hover:text-white hover:border-gray-600">
          {/* [DIALECT] */}
          {t('btn_add_passive_group', "Создать группу пассивок")}
       </Button>}
    </div>
  );
};

export default TabPassives;

export enum Faction {
  LIGHT = "Свет",
  DARK = "Тьма",
  NPC = "Бестиарий",
  GRAVEYARD = "Могильник"
}

