  ON_KILL = "On Kill",
  LOW_HP = "Low HP",
  COMBAT_START = "Combat Start",
  ACTIVATED = "Activated",
  INFLICT_PHYS = "Inflict Phys Injury",
  INFLICT_MAG = "Inflict Mag Injury",
