  bonuses: Bonus[];
  tags: string[];
  desc_lore: string;
  desc_mech: string;
  cd: number;
  cd_unit: string;
  dur: number;
  dur_unit: string;
  limit?: number;
  limit_unit?: string;
  is_blocked?: boolean; // New field for locking abilities
}

export interface AbilityGroup {
  name: string;
  tags: string[];
  abilities: Ability[];
  is_hidden?: boolean;
}

export interface Passive {
  name: string;
  bonuses: Bonus[];
  trigger: string;
  tags: string[];
  desc_lore: string;
  desc_mech: string;
  is_flaw: boolean;
  cd: number;
