// [DIALECT] - This whole file is part of the dialect module
import React, { createContext, useContext, useState, useEffect } from 'react';
import { DIALECT_DICT } from './dictionary';
import { Faction } from '../types';

interface DialectContextType {
  isOldSlavonic: boolean;
  isDialectUnlocked: boolean;
  isBloodMode: boolean;
  isToggleVisible: boolean;
  toggleDialect: () => void;
  handleSlashClick: () => void;
  handleLetterClick: (char: string) => void;
  isInputMode: boolean;
  inputBuffer: string;
  t: (key: string, defaultText: string) => string;
  trackTabChange: (faction: Faction) => void;
}

const DialectContext = createContext<DialectContextType | undefined>(undefined);

export const DialectProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isOldSlavonic, setIsOldSlavonic] = useState(false);
  const [isDialectUnlocked, setIsDialectUnlocked] = useState(false);
  const [isBloodMode, setIsBloodMode] = useState(false);

  // New state: Is the scroll button visible?
  const [isToggleVisible, setIsToggleVisible] = useState(false);

  // Easter Egg State
  const [slashClickCount, setSlashClickCount] = useState(0);
  const [isInputMode, setIsInputMode] = useState(false);
  const [inputBuffer, setInputBuffer] = useState("");

  const SLAVONIC_CODE = "пишет//дед";
  const BLOOD_CODE = "тело//и//плоть";
  const TOGGLE_UNLOCK_CODE = "рак-кубов";
  const CLICKS_REQUIRED = 15;

  useEffect(() => {
    // Load persisted states
    const savedDialect = localStorage.getItem('isOldSlavonic') === 'true';
    const savedUnlock = localStorage.getItem('isDialectUnlocked') === 'true';
    const savedBlood = localStorage.getItem('isBloodMode') === 'true';
    const savedVisible = localStorage.getItem('isToggleVisible') === 'true';

    setIsOldSlavonic(savedDialect);
    setIsDialectUnlocked(savedUnlock);
    setIsBloodMode(savedBlood);
    setIsToggleVisible(savedVisible);
  }, []);

  // Global Key Listener for "rak-kubov" unlock
  // Improved robustness for special characters like hyphen
  useEffect(() => {
      let buffer = ""; 

      const handleGlobalKeyDown = (e: KeyboardEvent) => {
          // Allow toggling it back off/on if needed, so removed the isToggleVisible check return

          // Ignore modifier keys to prevent pollution
          if (e.key.length > 1 && e.key !== 'Minus' && e.key !== '-') return;

          const char = e.key.toLowerCase();

          // Append to local closure buffer
          buffer = (buffer + char).slice(-25); // Increased buffer size

          if (buffer.includes(TOGGLE_UNLOCK_CODE)) {
              // Toggle state instead of just enable
              setIsToggleVisible(prev => {
                  const newState = !prev;
                  localStorage.setItem('isToggleVisible', String(newState));
                  console.log(`Dialect Toggle Button ${newState ? 'Unlocked' : 'Hidden'}!`);
                  return newState;
              });
              buffer = ""; // Reset after success
          }
      };

      window.addEventListener('keydown', handleGlobalKeyDown);
      return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  const unlockDialect = () => {
    setIsDialectUnlocked(true);
    localStorage.setItem('isDialectUnlocked', 'true');
    setIsInputMode(false);
    setInputBuffer("");
    console.log("Dialect Unlocked!");
  };

  const activateBloodMode = () => {
      const newState = !isBloodMode;
      setIsBloodMode(newState);
      localStorage.setItem('isBloodMode', String(newState));
      setIsInputMode(false);
      setInputBuffer("");
  };

  const handleSlashClick = () => {
    // Allows entering codes even if unlocked (e.g. for blood mode)
    if (!isInputMode) {
      const newCount = slashClickCount + 1;
      setSlashClickCount(newCount);
      if (newCount >= CLICKS_REQUIRED) {
        setIsInputMode(true);
        setInputBuffer("");
      }
    } else {
      handleLetterClick("//");
    }
  };

  const handleLetterClick = (char: string) => {
    if (!isInputMode) return;

    setInputBuffer(prev => {
      const next = (prev + char.toLowerCase()).slice(-20);

      if (next.includes(SLAVONIC_CODE)) {
         unlockDialect();
      }
      if (next.includes(BLOOD_CODE)) {
         activateBloodMode();
      }
      return next;
    });
  };

  const toggleDialect = () => {
    setIsOldSlavonic(prev => {
      const next = !prev;
      localStorage.setItem('isOldSlavonic', String(next));
      return next;
    });
  };

  const t = (key: string, defaultText: string) => {
    if (!isOldSlavonic) return defaultText;
    return DIALECT_DICT[key] || defaultText;
  };

  const trackTabChange = (faction: Faction) => {
      // Deprecated functionality
  };

  return (
    <DialectContext.Provider value={{ 
      isOldSlavonic, 
      isDialectUnlocked, 
      isBloodMode,
      isToggleVisible,
      toggleDialect, 
      handleSlashClick, 
      handleLetterClick, 
      isInputMode,
      inputBuffer,
      t,
      trackTabChange
    }}>
      {children}
    </DialectContext.Provider>
  );
};

export const useDialect = () => {
  const context = useContext(DialectContext);
  if (!context) {
    return { 
      isOldSlavonic: false, 
      isDialectUnlocked: false, 
      isBloodMode: false,
      isToggleVisible: false,
      toggleDialect: () => {}, 
      handleSlashClick: () => {},
      handleLetterClick: () => {},
      isInputMode: false,
      inputBuffer: "",
      t: (_: string, d: string) => d,
      trackTabChange: () => {}
    };
  }
  return context;
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { User } from '../types';
import { supabase } from '../lib/supabase';
import bridge from '@vkontakte/vk-bridge';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  isAdmin: boolean;
  signIn: (email?: string, password?: string) => Promise<void>;
  signInWithProvider: (provider: 'google') => Promise<void>;
  signInWithVK: () => Promise<void>;
  signUp: (email: string, password: string) => Promise<void>; 
  signInAsGuest: () => Promise<void>;
  signOut: () => Promise<void>;
  logoutAdmin: () => void; 
  updatePassword: (newPassword: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children?: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null); 
  const [isAdmin, setIsAdmin] = useState(false);
  const [isLoading, setIsLoading] = useState(true); // Default to true to wait for session check

  // Check admin role from DB
  const checkProfileRole = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('role')
        .eq('id', userId)
        .single();

      if (error) {
        console.warn("[Auth] Failed to fetch profile role.", error.message);
        setIsAdmin(false);
        return;
      }

      if (data && data.role === 'admin') {
        setIsAdmin(true);
      } else {
        setIsAdmin(false);
      }
    } catch (e) {
      console.error("[Auth] Unexpected error checking profile role:", e);
      setIsAdmin(false);
    }
  };

  // --- Session Initialization Effect ---
  useEffect(() => {
    const initializeAuth = async () => {
        try {
            // 1. Check active Supabase session
            const { data: { session } } = await supabase.auth.getSession();

            if (session?.user) {
                const realUser: User = {
                    id: session.user.id,
                    email: session.user.email || '',
                    role: 'user'
                };
                setUser(realUser);
                checkProfileRole(session.user.id);
            } else {
                // 2. Check for persisted Guest session
                const isGuest = localStorage.getItem('juul_d_is_guest');
                if (isGuest === 'true') {
                    setUser({
                        id: 'guest',
                        email: 'guest@void.net',
                        role: 'guest'
                    });
                }
            }
        } catch (error) {
            console.error("Auth initialization error:", error);
        } finally {
            setIsLoading(false);
        }
    };

    initializeAuth();

    // 3. Subscribe to Auth Changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_OUT') {
            setUser(null);
            setIsAdmin(false);
            localStorage.removeItem('juul_d_is_guest');
        } else if (session?.user && (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED')) {
             const realUser: User = {
                id: session.user.id,
                email: session.user.email || '',
                role: 'user'
            };
            // Only update if different to prevent loops, though React handles this
            setUser(realUser);
            localStorage.removeItem('juul_d_is_guest');

            if (event === 'SIGNED_IN') {
                checkProfileRole(session.user.id);
            }
        }
    });

    return () => {
        subscription.unsubscribe();
    };
  }, []);

  const signIn = async (email?: string, password?: string) => {
    setIsLoading(true);
    try {
        if (email && password) {
            // Attempt real Supabase Auth
            const { data, error } = await supabase.auth.signInWithPassword({ email, password });

            if (error) {
                console.error("Supabase Auth Error:", error.message);
                throw error;
            }

            // Explicitly set user immediately to prevent race conditions with navigation
            if (data.session?.user) {
                const realUser: User = {
                    id: data.session.user.id,
                    email: data.session.user.email || '',
                    role: 'user'
                };
                setUser(realUser);
                await checkProfileRole(data.session.user.id);
            }
        } else {
            // Legacy / Default mock
            setUser({
                id: '12345',
                email: 'traveller@vk.com',
                role: 'user'
            });
        }
    } catch (e) {
        console.error("Sign-In Error:", e);
        throw e; // Rethrow so AuthPage can display error
    } finally {
        setIsLoading(false);
    }
  };

  const signInWithProvider = async (provider: 'google') => {
      setIsLoading(true);
      try {
          // Construct redirect URL to return to the app root (handling subpaths like /Juul-D/)
          let baseUrl = '/';
          try {
              // @ts-ignore
              if (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env.BASE_URL) {
                  // @ts-ignore
                  baseUrl = import.meta.env.BASE_URL;
              }
          } catch (e) {
              // Ignore env read errors in sandboxes
          }

          const redirectUrl = window.location.origin + baseUrl;

          const { data, error } = await supabase.auth.signInWithOAuth({
              provider: provider,
              options: {
                  redirectTo: redirectUrl
              }
          });
          if (error) throw error;
      } catch (e) {
          console.error(`OAuth ${provider} Error:`, e);
          throw e;
      } finally {
          // Note: setIsLoading(false) is not called here because OAuth redirects away.
          // It will reset when the page reloads on callback.
      }
  };

  // Custom VK Handler for Mini Apps
  const signInWithVK = async () => {
      setIsLoading(true);
      try {
          // 1. Get VK User Data
          const vkUser = await bridge.send('VKWebAppGetUserInfo');
          if (!vkUser || !vkUser.id) throw new Error("Не удалось получить данные ВК");

          // 2. Generate Synthetic Credentials
          // NOTE: This isn't production-secure for high-stakes apps, but standard for 
          // client-side hobby apps without a backend proxy.
          const fakeEmail = `id${vkUser.id}@vk.juul-d.local`;
          const fakePassword = `vk_secret_${vkUser.id}_secure_salt_v1`;

          // 3. Try to Sign In
          const { data: signInData, error: signInError } = await supabase.auth.signInWithPassword({
              email: fakeEmail,
              password: fakePassword
          });

          // 4. If Sign In fails (User doesn't exist), Sign Up
          if (signInError) {
              const { data: signUpData, error: signUpError } = await supabase.auth.signUp({
                  email: fakeEmail,
                  password: fakePassword,
              });

              if (signUpError) throw signUpError;

              // 5. Update Profile with VK Name/Avatar (Wait for session trigger or force update)
              if (signUpData.user) {
                  // Small delay to ensure triggers ran if any, then upsert
                  await new Promise(r => setTimeout(r, 500));
                  await supabase.from('profiles').upsert({
                      id: signUpData.user.id,
                      full_name: `${vkUser.first_name} ${vkUser.last_name}`,
                      avatar_url: vkUser.photo_200 || vkUser.photo_100,
                      updated_at: new Date()
                  });
              }
          }
      } catch (e: any) {
          console.error("VK Auth Error:", e);
          throw e;
      } finally {
          setIsLoading(false);
      }
  };

  const signUp = async (email: string, password: string) => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase.auth.signUp({
        email,
        password,
      });

      if (error) {
        console.error("Supabase Registration Error:", error.message);
        throw error;
      }

      if (!data.session && data.user) {
          console.log("Registration successful, verify email.");
      }
    } catch (e) {
      console.error("Registration Exception:", e);
      throw e;
    } finally {
      setIsLoading(false);
    }
  };

  const signInAsGuest = async () => {
      setIsLoading(true);
      await new Promise(resolve => setTimeout(resolve, 800)); // Fake loading

      localStorage.setItem('juul_d_is_guest', 'true');

      setUser({
          id: 'guest',
          email: 'guest@void.net',
          role: 'guest'
      });
      setIsAdmin(false); 
      setIsLoading(false);
  };

  const signOut = async () => {
    setIsLoading(true);
    setIsAdmin(false);
    localStorage.removeItem('juul_d_is_guest');

    await supabase.auth.signOut();
    setUser(null);
    setIsLoading(false);
  };

  const logoutAdmin = () => {
    setIsAdmin(false);
  };

  const updatePassword = async (newPassword: string) => {
      if (!user || user.id === 'guest') throw new Error("Гости не могут менять пароль");

      const { error } = await supabase.auth.updateUser({ password: newPassword });
      if (error) throw error;
  };

  return (
    <AuthContext.Provider value={{ 
      user, 
      isAuthenticated: !!user, 
      isLoading, 
      isAdmin, 
      signIn, 
      signInWithProvider,
      signInWithVK,
      signUp,
      signInAsGuest,
      signOut,
      logoutAdmin,
      updatePassword
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

