            disabled={isRefreshing || !!refreshError}
            className={`
                flex items-center gap-4 px-3 py-2 rounded-lg text-slate-400 border border-transparent transition-all w-full group relative overflow-hidden
                ${refreshError 
                    ? 'border-red-500/30 bg-red-900/10 text-red-400 cursor-not-allowed' 
                    : 'hover:text-emerald-300 hover:bg-emerald-900/10 hover:border-emerald-500/30'}
                ${isDesktopCollapsed ? 'justify-center' : ''}
            `}
            title="Обновить базы данных"
          >
             {refreshError ? <AlertCircle className="w-5 h-5 min-w-[20px] shrink-0" /> : <RefreshCw className={`w-5 h-5 min-w-[20px] shrink-0 ${isRefreshing ? 'animate-spin text-emerald-400' : ''}`} />}
             <span className={`font-fantasy tracking-wider text-xs whitespace-nowrap transition-all duration-300 uppercase ${isDesktopCollapsed ? 'hidden' : 'block'}`}>
                 {isRefreshing ? 'Синхронизация...' : (refreshError || 'Обновить Базы')}
             </span>
          </button>

          {/* Change Password Button */}
          {user && user.role !== 'guest' && (
              <div className="relative">
                  <button 
                    onClick={() => setShowPasswordInput(!showPasswordInput)}
                    className={`
                        flex items-center gap-4 px-3 py-2 rounded-lg text-slate-500 hover:text-amber-400 hover:bg-amber-900/10 border border-transparent hover:border-amber-500/30 transition-all w-full
                        ${isDesktopCollapsed ? 'justify-center' : ''}
                    `}
                    title="Сменить Пароль"
                  >
                    <KeyRound className="w-5 h-5 min-w-[20px] shrink-0" />
                    <span className={`font-fantasy tracking-wider text-sm whitespace-nowrap transition-all duration-300 uppercase ${isDesktopCollapsed ? 'hidden' : 'block'}`}>
                        Пароль
                    </span>
                  </button>

                  {/* Password Input Overlay */}
                  {showPasswordInput && !isDesktopCollapsed && (
                      <div className="absolute bottom-full mb-2 left-0 w-full bg-slate-900 border border-violet-500/30 p-2 rounded shadow-xl animate-fadeIn z-50">
                          {passMessage ? (
                              <div className={`text-xs text-center font-bold ${passMessage === 'Успешно!' ? 'text-emerald-400' : 'text-red-400'}`}>{passMessage}</div>
                          ) : (
                              <div className="flex gap-1">
                                  <input 
                                    type="password" 
                                    placeholder="Новый пароль" 
                                    className="w-full bg-black/50 border border-slate-700 rounded px-2 py-1 text-xs text-white focus:border-violet-500 outline-none"
                                    value={newPassword}
                                    onChange={(e) => setNewPassword(e.target.value)}
                                  />
                                  <button onClick={handleChangePassword} className="bg-violet-600 text-white p-1 rounded hover:bg-violet-500"><Check size={14} /></button>
                              </div>
                          )}
                      </div>
                  )}
              </div>
          )}

          {/* Logout */}
          <button 
            onClick={handleLogout}
            className={`
              flex items-center gap-4 px-3 py-2 rounded-lg text-slate-500 hover:text-red-400 hover:bg-red-900/10 border border-transparent hover:border-red-500/30 transition-all w-full
              ${isDesktopCollapsed ? 'justify-center' : ''}
            `}
            title="Выйти"
          >
            <LogOut className="w-5 h-5 min-w-[20px] shrink-0" />
            <span 
              className={`
                font-fantasy tracking-wider text-sm whitespace-nowrap transition-all duration-300 uppercase
                ${isDesktopCollapsed ? 'opacity-0 w-0 min-[1150px]:hidden' : 'opacity-100 w-auto'}
              `}
            >
              Выйти
            </span>
          </button>

          {/* Only show ID if Admin */}
          {user && isAdmin && !isDesktopCollapsed && (
            <div className="flex flex-col px-2 mt-1 animate-fadeIn opacity-50 hover:opacity-100 transition-opacity">
              <span className="text-[10px] truncate font-mono text-emerald-500">{user.email}</span>
            </div>
          )}
        </div>
      </div>
    </aside>
  );
};

import React, { useState, useMemo } from 'react';
import { CharacterData, TimeUnit, StatType, Bonus, Ability } from '../types';
import { Card, StyledInput, StyledTextarea, Button, BonusInput, TagInput, TimeInput, TabRadarCharts, CommonTagToggles } from './Shared';
import { Plus, Trash2, Clock, Hourglass, ChevronDown, ChevronRight, Eye, EyeOff, Hash, Check, X, Lock, Unlock } from 'lucide-react';
import { DisplayMode } from '../App';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  displayMode: DisplayMode;
  onChange: (groups: CharacterData['ability_groups']) => void;
  timeUnits: TimeUnit[];
}

const TabAbilities: React.FC<Props> = ({ character, isEditMode, displayMode, onChange, timeUnits }) => {
  const { ability_groups } = character;
  const [collapsedGroups, setCollapsedGroups] = useState<Record<number, boolean>>({});
  const [deleteConfirmGroupIdx, setDeleteConfirmGroupIdx] = useState<number | null>(null);
  /* [DIALECT] */ const { t } = useDialect();

  const toggleGroup = (idx: number) => {
    setCollapsedGroups(prev => ({ ...prev, [idx]: !prev[idx] }));
  };

  const updateGroup = (idx: number, field: string, val: any) => {
    const next = [...ability_groups];
    next[idx] = { ...next[idx], [field]: val };
    onChange(next);
  };

  const addGroup = () => onChange([...ability_groups, { name: "Новая Школа", tags: [], abilities: [], is_hidden: false }]);

  const removeGroup = (idx: number) => {
     const next = ability_groups.filter((_, i) => i !== idx);
     onChange(next);

     // Clean up collapsed state & delete state
     const newCollapsed = { ...collapsedGroups };
     delete newCollapsed[idx];
     setCollapsedGroups(newCollapsed);
     setDeleteConfirmGroupIdx(null);
  };

  const addAbility = (gIdx: number) => {
    const next = [...ability_groups];
    // Deep clone the group to avoid mutation
    const group = { ...next[gIdx] };
    group.abilities = [...(group.abilities || [])];

    group.abilities.push({ 
      name: "Новый Навык", bonuses: [], tags: [], desc_lore: "", desc_mech: "",
      cd: 0, cd_unit: "", dur: 0, dur_unit: "", limit: 0, limit_unit: "", is_blocked: false
    });

    next[gIdx] = group;
    onChange(next);
  };

  const updateAbility = (gIdx: number, aIdx: number, field: string, val: any) => {
    const next = [...ability_groups];
    // Deep clone logic
    const group = { ...next[gIdx] };
    // Clone abilities array
    group.abilities = [...group.abilities];

    // NOTE: sorting blocked items to the bottom happens during render, 
    // but here we must find the correct ability in the original array based on index
    // However, the indices passed here (aIdx) come from the RENDERED list (which might be sorted differently).
    // This is tricky. To solve this, we should rely on mapping. But since we don't have unique IDs for abilities guaranteed, 
    // we should trust the array order passed from the parent if we don't sort inside the state.
    // 
    // Wait, if we sort for display, we mess up the index mapping for updates. 
    // Strategy: We will sort for display, but attach the original index to the mapped item to pass back here.

    // Actually, simpler: Let's assume the state itself should be sorted? No, that causes jumping UI.
    // Let's rely on the fact that `map` provides the index. 

    // REFACTOR: We need to find the ability by reference or ID.
    // Since we don't have stable IDs in the type def yet (it's optional in some contexts), 
    // let's pass the ability object itself if possible, OR, handle sorting carefully.

    // For this implementation: We will sort the display list.
    // To update correctly, we need the index in the ORIGINAL 'group.abilities' array.

    group.abilities[aIdx] = { ...group.abilities[aIdx], [field]: val };
    next[gIdx] = group;
    onChange(next);
  };

  const removeAbility = (gIdx: number, aIdx: number) => {
    const next = [...ability_groups];
    const group = { ...next[gIdx] };
    group.abilities = [...group.abilities];
    group.abilities.splice(aIdx, 1);
    next[gIdx] = group;
    onChange(next);
  };

  const shouldShowLore = displayMode === 'lore';
  const shouldShowMech = displayMode === 'mech';

  // --- Derived Data for Charts (Memoized to prevent flickering during text edits) ---
  const structureData = useMemo(() => {
      // Optimization: Skip calculation in Edit Mode
      if (isEditMode) return [];

      const data = ability_groups.map((g, i) => {
        const name = g.name || "Unknown";
        let baseName = name.length > 10 ? name.substring(0, 8) + '..' : name;
        return {
          subject: baseName + '\u200B'.repeat(i), 
          value: g.abilities ? g.abilities.length : 0
        };
      });
      // Pad to at least 3 points for radar chart
      while (data.length < 3) {
          data.push({ 
              subject: '\u200B'.repeat(100 + data.length), 
              value: 0 
          });
      }
      return data;
  }, [ability_groups, isEditMode]);

  const bonusData = useMemo(() => {
      // Optimization: Skip calculation in Edit Mode
      if (isEditMode) return [];

      let phys = 0, magic = 0, unique = 0;
      ability_groups.forEach(g => {
        if (Array.isArray(g.abilities)) {
          g.abilities.forEach(item => {
            if (Array.isArray(item.bonuses)) {
              item.bonuses.forEach(b => {
                 const val = Number(b.val);
                 if (!Number.isNaN(val)) {
                    if (b.stat === StatType.PHYS) phys += val;
                    if (b.stat === StatType.MAGIC) magic += val;
                    if (b.stat === StatType.UNIQUE) unique += val;
                 }
              });
            }
          });
        }
      });

      const getValue = (v: number) => Math.max(0, v); // Only positive for abilities

      return [
        { subject: t('stat_phys_short', 'ФИЗ'), value: getValue(phys) },
        { subject: t('stat_mag_short', 'МАГ'), value: getValue(magic) },
        { subject: t('stat_uni_short', 'УНИК'), value: getValue(unique) },
      ];
  }, [ability_groups, t, isEditMode]);

  return (
    <div className="space-y-8 animate-fade-in">

      {!isEditMode && (
          <TabRadarCharts 
              structureData={structureData} 
              bonusData={bonusData} 
              color="#06b6d4" 
              t={t}
          />
      )}

      {ability_groups.map((group, gIdx) => {
        // Hide if not in edit mode AND either empty or explicitly hidden
        if (!isEditMode && (group.abilities.length === 0 || group.is_hidden)) return null;

        const isCollapsed = collapsedGroups[gIdx];
        const isHidden = group.is_hidden;

        // Prepare sorted list for display, but keep original index
        const abilitiesWithIndex = group.abilities.map((ab, i) => ({ ...ab, originalIndex: i }));

        // Sort: Unblocked first, Blocked last
        const sortedAbilities = abilitiesWithIndex.sort((a, b) => {
            if (a.is_blocked === b.is_blocked) return 0;
            return a.is_blocked ? 1 : -1;
        });

        return (
          // Use Index as key to prevent re-mounting on name change
          <div key={gIdx} className={`space-y-4 transition-all ${isHidden && isEditMode ? 'opacity-70 border-2 border-dashed border-gray-800 p-4 rounded-xl bg-gray-900/20' : ''}`}>
             {/* Header */}
             <div className="flex items-center gap-4 border-b border-gray-800 pb-2 bg-slate-900/90 p-3 rounded-t-lg backdrop-blur-sm shadow-md">
               <button onClick={() => toggleGroup(gIdx)} className="text-gray-500 hover:text-cyan-400 transition-colors p-1">
                  {isCollapsed ? <ChevronRight size={24}/> : <ChevronDown size={24} />}
               </button>
               <div className="flex-1">
                 <StyledInput 
                   isEditMode={isEditMode} 
                   value={group.name} 
                   onChange={e => updateGroup(gIdx, 'name', e.target.value)} 
                   className="text-xl font-bold text-cyan-500 uppercase tracking-widest bg-transparent border-none p-0" 
                 />
                 {/* [DIALECT] */}
                 {isHidden && isEditMode && <span className="text-[10px] uppercase font-bold text-gray-500 block -mt-1">{t('lbl_hidden_group', "Скрытая группа")}</span>}
               </div>

               {!isCollapsed && <TagInput isEditMode={isEditMode} tags={group.tags || []} onChange={t => updateGroup(gIdx, 'tags', t)} />}

               {isEditMode && (
                 <>
                   <button 
                     onClick={() => updateGroup(gIdx, 'is_hidden', !isHidden)} 
                     className={`p-1.5 rounded transition-colors ${isHidden ? 'bg-gray-800 text-gray-400 hover:text-white' : 'text-cyan-600 hover:text-cyan-400'}`}
                     title={isHidden ? "Показать в листе" : "Скрыть из листа"}
                   >
                     {isHidden ? <EyeOff size={16}/> : <Eye size={16}/>}
                   </button>

                   {/* Delete Confirm Logic */}
                   {deleteConfirmGroupIdx === gIdx ? (
                     <div className="flex items-center gap-1">
                        <Button size="sm" variant="danger" onClick={() => removeGroup(gIdx)}><Check size={14} /></Button>
                        <Button size="sm" variant="secondary" onClick={() => setDeleteConfirmGroupIdx(null)}><X size={14} /></Button>
                     </div>
                   ) : (
                     <Button size="sm" variant="danger" onClick={() => setDeleteConfirmGroupIdx(gIdx)}><Trash2 size={14} /></Button>
                   )}
                 </>
               )}
             </div>

             {/* Content */}
             {!isCollapsed && (
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-in">
                 {sortedAbilities.map((abilityWrapper) => {
                   const { originalIndex, ...ability } = abilityWrapper;
                   const isBlocked = ability.is_blocked;

                   return (
                   <Card key={originalIndex} className={`hover:border-gray-700 transition-colors bg-[#0b0d10] border-gray-800 ${isBlocked ? 'opacity-60 grayscale-[0.8] hover:opacity-100 hover:grayscale-0' : ''}`}>
                      <div className="flex justify-between items-start mb-2 overflow-hidden">
                         <div className="flex-1 min-w-0 mr-2" title={ability.name}>
                           <StyledInput 
                              isEditMode={isEditMode && !isBlocked} 
                              disabled={isBlocked}
                              value={ability.name} 
                              onChange={e => updateAbility(gIdx, originalIndex, 'name', e.target.value)} 
                              className={`font-bold text-lg truncate block w-full ${isBlocked ? 'text-slate-500' : ''}`} 
                              // [DIALECT]
                              placeholder={t('ph_ability_name', "Название навыка")}
                           />
                         </div>
                         {isEditMode && (
                             <div className="flex items-center gap-1 flex-shrink-0">
                                <button 
                                    onClick={() => updateAbility(gIdx, originalIndex, 'is_blocked', !isBlocked)}
                                    className={`p-1 rounded transition-colors ${isBlocked ? 'text-amber-500 bg-amber-900/20' : 'text-slate-600 hover:text-amber-400'}`}
                                    title={isBlocked ? "Разблокировать" : "Заблокировать (Архивировать)"}
                                >
                                    {isBlocked ? <Lock size={14} /> : <Unlock size={14} />}
                                </button>
                                {!isBlocked && (
                                    <button onClick={() => removeAbility(gIdx, originalIndex)} className="text-red-900 hover:text-red-500 transition-colors">
                                        <Trash2 size={14}/>
                                    </button>
                                )}
                             </div>
                         )}
                      </div>

                      {/* Mech Details (Hidden in Lore Mode unless Editing) */}
                      {(shouldShowMech || isEditMode) && (
                        <div className={`flex flex-wrap gap-2 mb-2 ${isBlocked ? 'pointer-events-none' : ''}`}>
                          <BonusInput isEditMode={isEditMode && !isBlocked} bonuses={ability.bonuses} onChange={b => updateAbility(gIdx, originalIndex, 'bonuses', b)} />
                          <TimeInput 
                            icon={Clock} label="КД" isEditMode={isEditMode && !isBlocked} 
                            val={ability.cd} unit={ability.cd_unit} 
                            onChangeVal={v => updateAbility(gIdx, originalIndex, 'cd', v)} 
                            onChangeUnit={u => updateAbility(gIdx, originalIndex, 'cd_unit', u)} 
                            options={timeUnits}
                          />
                          <TimeInput 
                            icon={Hourglass} label="Длит." isEditMode={isEditMode && !isBlocked} 
                            val={ability.dur} unit={ability.dur_unit} 
                            onChangeVal={v => updateAbility(gIdx, originalIndex, 'dur', v)} 
                            onChangeUnit={u => updateAbility(gIdx, originalIndex, 'dur_unit', u)} 
                            options={timeUnits}
                          />
                          {/* Limit input */}
                          <TimeInput 
                            icon={Hash} label="Лимит" isEditMode={isEditMode && !isBlocked} 
                            val={ability.limit || 0} unit={ability.limit_unit || ""} 
                            onChangeVal={v => updateAbility(gIdx, originalIndex, 'limit', v)} 
                            onChangeUnit={u => updateAbility(gIdx, originalIndex, 'limit_unit', u)} 
                            options={timeUnits}
                          />
                        </div>
                      )}

                      <div className={`mb-3 ${isBlocked ? 'pointer-events-none' : ''}`}>
                         <TagInput isEditMode={isEditMode && !isBlocked} tags={ability.tags || []} onChange={t => updateAbility(gIdx, originalIndex, 'tags', t)} />
                         {isEditMode && !isBlocked && <CommonTagToggles tags={ability.tags || []} onChange={t => updateAbility(gIdx, originalIndex, 'tags', t)} />}
                      </div>

                      {/* Lore Text */}
                      {(shouldShowLore || isEditMode) && (
                        <StyledTextarea 
                          isEditMode={isEditMode && !isBlocked} 
                          disabled={isBlocked}
                          value={ability.desc_lore} 
                          onChange={e => updateAbility(gIdx, originalIndex, 'desc_lore', e.target.value)} 
                          className="text-sm text-gray-400 italic mb-2" 
                          // [DIALECT]
                          placeholder={t('ph_ability_lore', "Худ. описание")}
                        />
                      )}

                      {/* Mech Text - Green Highlight */}
                      {(shouldShowMech || isEditMode) && (isEditMode || ability.desc_mech) && (
                        <div className={`pt-2 ${!isEditMode && shouldShowLore ? 'border-t border-gray-800' : ''}`}>
                          <StyledTextarea 
                            isEditMode={isEditMode && !isBlocked} 
                            disabled={isBlocked}
                            value={ability.desc_mech} 
                            onChange={e => updateAbility(gIdx, originalIndex, 'desc_mech', e.target.value)} 
                            className={`text-xs font-mono leading-relaxed ${isEditMode ? 'text-green-400' : 'text-green-500/80'} ${isBlocked ? 'text-slate-500' : ''}`} 
                            // [DIALECT]
                            placeholder={t('ph_ability_mech', "Механика")} 
                          />
                        </div>
                      )}
                   </Card>
                 )})}

                 {isEditMode && (
                   <button onClick={() => addAbility(gIdx)} className="border-2 border-dashed border-gray-800 rounded-lg flex items-center justify-center text-gray-700 hover:text-cyan-500 hover:border-cyan-900 transition-all min-h-[150px] bg-slate-900/50 backdrop-blur-sm">
                     <Plus size={24} />
                   </button>
                 )}
               </div>
             )}
          </div>
        );
      })}

      {/* [DIALECT] */}
      {isEditMode && <Button onClick={addGroup} className="w-full py-4 border-dashed border-2 bg-slate-900/50 backdrop-blur-sm border-gray-800 text-gray-600 hover:text-white hover:border-gray-600">
         {t('btn_add_school', "Создать новую школу")}
      </Button>}
    </div>
  );
};

export default TabAbilities;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { INITIAL_CHARACTER, DEFAULT_INJURIES, DEFAULT_TIME_UNITS } from './constants';
import { CharacterData, InjuryDefinition, TimeUnit, Faction } from './types';
import * as SupabaseService from './utils/supabaseService';
import Roster from './components/Roster';
import SheetHeader from './components/SheetHeader';
import TabEquipment from './components/TabEquipment';
import TabAbilities from './components/TabAbilities';
import TabPassives from './components/TabPassives';
import TabDebuffs from './components/TabDebuffs';
import TabUnits from './components/TabUnits';
import TabMedCard from './components/TabMedCard';
import GlobalSettingsModal from './components/GlobalSettingsModal';
import { TagHintsModal } from './components/TagHintsModal';
import { Button } from './components/Shared';
import { Save, ChevronLeft, ChevronRight, Edit3, Trash2, RotateCcw, Settings, BookOpen, Calculator, ScrollText, Loader2, Tag } from 'lucide-react';
import { DialectProvider, useDialect } from './dialect_module/DialectContext';
import { UIProvider, useUI } from './context/UIContext';
import { TrainingPage } from './pages/TrainingPage';

export type DisplayMode = 'lore' | 'mech';

interface RosterModuleProps {
  isAdmin?: boolean;
}

const RosterContent: React.FC<RosterModuleProps> = ({ isAdmin = false }) => {
  const { toggleDialect, isOldSlavonic, isDialectUnlocked, t } = useDialect();
  const { showAlert, showConfirm } = useUI();

  // App State
  // View can now be 'training' as well
  const [view, setView] = useState<'roster' | 'sheet' | 'training'>('roster');

  // --- SPLIT STATE FOR PERFORMANCE ---
  // `characters` holds the master state, updated on every keystroke in Sheet.
  // `rosterList` holds the snapshot for the sidebar list, updated only on Save/Init/Create/Delete.
  const [characters, setCharacters] = useState<CharacterData[]>([]);
  const [rosterList, setRosterList] = useState<CharacterData[]>([]);

  const [isLoadingData, setIsLoadingData] = useState(true);

  const [activeCharId, setActiveCharId] = useState<string | null>(null);
  const [charStack, setCharStack] = useState<string[]>([]);

  // Sheet State
  const [displayMode, setDisplayMode] = useState<DisplayMode>('lore');
  const [isEditMode, setIsEditMode] = useState(false);
  const [activeTab, setActiveTab] = useState<'equipment' | 'abilities' | 'passives' | 'debuffs' | 'units' | 'medcard'>('equipment');

  // Global Configs
  const [triggersMap, setTriggersMap] = useState<Record<string, string>>({});
  const [injuryDefinitions, setInjuryDefinitions] = useState<InjuryDefinition[]>(DEFAULT_INJURIES);
  const [timeUnits, setTimeUnits] = useState<TimeUnit[]>(DEFAULT_TIME_UNITS);

  // Admin UI State
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isTagHintsOpen, setIsTagHintsOpen] = useState(false);

  const SHEET_TABS = useMemo(() => [
    { id: 'equipment', label: t('tab_eq', 'Снаряжение') },
    { id: 'abilities', label: t('tab_ab', 'Способности') },
    { id: 'passives', label: t('tab_ps', 'Пассивки') },
    { id: 'debuffs', label: t('tab_db', 'Дебаффы') },
    { id: 'units', label: t('tab_un', 'Юниты') },
    { id: 'medcard', label: t('tab_mc', 'Мед.Карта') },
  ], [t]);

  const initRef = useRef(false);

  // Fetch Data
  useEffect(() => {
    if (initRef.current) return;
    initRef.current = true;

    const init = async () => {
      setIsLoadingData(true);
      try {
        const [chars, trigs, inj, units] = await Promise.all([
          SupabaseService.getAllCharacters(),
          SupabaseService.getGlobalTriggers(),
          SupabaseService.getInjuries(),
          SupabaseService.getTimeUnits()
        ]);
        setCharacters(chars);
        setRosterList(chars); // Init roster list
        setTriggersMap(trigs);
        setInjuryDefinitions(inj);
        setTimeUnits(units);
      } catch (e) {
        console.error("Failed to init app", e);
      } finally {
        setIsLoadingData(false);
      }
    };
    init();
  }, []);

  const handleCreate = async () => {
    const newChar: CharacterData = JSON.parse(JSON.stringify(INITIAL_CHARACTER));
    newChar.id = crypto.randomUUID();
    newChar.profile.name = "Новая Душа";

    // Optimistic UI
    const updated = [...characters, newChar];
    setCharacters(updated);
    setRosterList(updated); // Update list immediately on creation

    try {
      await SupabaseService.saveCharacter(newChar);
      setActiveCharId(newChar.id);
      setCharStack([newChar.id]);
      setView('sheet');
      setIsEditMode(true);
    } catch (e) {
      showAlert("Ошибка создания: " + e, "Сбой базы данных");
      const reverted = characters.filter(c => c.id !== newChar.id);
      setCharacters(reverted);
      setRosterList(reverted);
    }
  };

  const handleSelect = (id: string) => {
    // When selecting a new char, we ensure we have the latest data from our master list
    setActiveCharId(id);
    setCharStack([id]);
    setView('sheet');
    setIsEditMode(false);
    window.scrollTo(0,0);
  };

  const handleNavigateToUnit = (unitId: string) => {
    setCharStack(prev => [...prev, unitId]);
    setActiveCharId(unitId);
    window.scrollTo(0,0);
  };

  const handleBack = () => {
    if (charStack.length > 1) {
      const newStack = [...charStack];
      newStack.pop();
      setCharStack(newStack);
      setActiveCharId(newStack[newStack.length - 1]);
    } else {
      setView('roster');
      setActiveCharId(null);
      setCharStack([]);
      // On return to roster, sync list to ensure any saved changes are reflected
      // But actually, we only update rosterList on Save, so it should be fine.
      // If user cancels edits, characters state might need revert? 
      // For now, we assume simple state model: edits are kept in memory until discarded or saved.
    }
  };

  const handleNextTab = () => {
      const idx = SHEET_TABS.findIndex(t => t.id === activeTab);
      const nextId = SHEET_TABS[(idx + 1) % SHEET_TABS.length].id;
      setActiveTab(nextId as any);
  };

  const handlePrevTab = () => {
      const idx = SHEET_TABS.findIndex(t => t.id === activeTab);
      const prevId = SHEET_TABS[(idx - 1 + SHEET_TABS.length) % SHEET_TABS.length].id;
      setActiveTab(prevId as any);
  };

  const activeChar = characters.find(c => c.id === activeCharId);

  const updateActiveChar = (updates: Partial<CharacterData>) => {
    if (!activeChar) return;
    const updated = { ...activeChar, ...updates };
    setCharacters(prev => prev.map(c => c.id === activeChar.id ? updated : c));
    // NOTE: We do NOT update `rosterList` here to avoid sidebar re-renders/jitters
  };

  const handleSave = async () => {
    if (!activeChar) return;
    try {
      await SupabaseService.saveCharacter(activeChar);
      setIsEditMode(false);
      // Sync Roster List on Save
      setRosterList(characters);
    } catch (e) {
      showAlert("Ошибка сохранения: " + e, "Ошибка");
    }
  };

  const handleInstantUpdate = async (eq: CharacterData['equipment']) => {
      if (!activeChar) return;
      const updated = { ...activeChar, equipment: eq };
      const newChars = characters.map(c => c.id === activeChar.id ? updated : c);
      setCharacters(newChars);
      await SupabaseService.saveCharacter(updated);
      setRosterList(newChars); // Update roster immediately for instant actions
  };

  const handleDelete = async (idToDelete?: string) => {
    const targetId = idToDelete || activeChar?.id;
    if (!targetId) return;

    showConfirm("Вы уверены? Это действие необратимо уничтожит сущность.", async () => {
        try {
          await SupabaseService.deleteCharacter(targetId);
          const updated = characters.filter(c => c.id !== targetId);
          setCharacters(updated);
          setRosterList(updated); // Sync list
          if (targetId === activeCharId) {
             handleBack();
          }
        } catch (e) {
          showAlert("Ошибка удаления: " + e, "Ошибка");
        }
    }, "Уничтожение");
  };

  const createUnit = async () => {
      if (!activeChar) return;
      const unit: CharacterData = JSON.parse(JSON.stringify(INITIAL_CHARACTER));
      unit.id = crypto.randomUUID();
      unit.profile.name = "Новый Юнит";
      unit.meta.master_id = activeChar.id;

      try {
        await SupabaseService.saveCharacter(unit);
        const updated = [...characters, unit];
        setCharacters(updated);
        setRosterList(updated); // Sync
        handleNavigateToUnit(unit.id);
        setIsEditMode(true);
      } catch (e) {
         showAlert("Cannot create unit: " + e, "Ошибка");
      }
  };

  // Helper for background image in Sheet View
  const getSheetBackground = (faction: Faction) => {
      if (faction === Faction.LIGHT) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Light_bg.jpg';
      if (faction === Faction.DARK) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Dark_bg.jpg';
      if (faction === Faction.NPC) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Bestiary_bg.jpg';
      if (faction === Faction.GRAVEYARD) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/graveyard_bg.jpg';
      return null;
  };

  if (isLoadingData) {
    return (
      <div className="min-h-full flex items-center justify-center text-violet-500">
        <Loader2 size={48} className="animate-spin" />
      </div>
    );
  }

  if (view === 'training') {
      return <TrainingPage characters={characters} onBack={() => setView('roster')} />;
  }

  return (
    // Removed min-h-screen and pb-20 to allow Roster component to control exact viewport height
    <div className="font-sans text-slate-300 selection:bg-violet-900/40 selection:text-white h-full relative">

      {/* Dynamic Background for Sheet View */}
      {view === 'sheet' && activeChar && (
          <>
            {getSheetBackground(activeChar.profile.faction) ? (
                <div className="fixed inset-0 z-0 overflow-hidden">
                    <div 
                        // здесь задний фон
                        className="absolute inset-0 bg-cover bg-center bg-no-repeat bg-fixed blur-[5px] scale-105"
                        style={{ backgroundImage: `url(${getSheetBackground(activeChar.profile.faction)})` }}
                    ></div>
                    {/* Darken by 50% */}
                    <div className="absolute inset-0 bg-black/50"></div>
                </div>
            ) : (
                // Default dark gradient if no specific faction bg
               <div className="fixed inset-0 bg-gradient-to-b from-slate-900 to-black z-0 pointer-events-none"></div>
            )}
          </>
      )}

      {view === 'roster' && (
        <>
          <Roster 
            characters={rosterList} // Use the buffered list for performance
            onSelect={handleSelect} 
            onCreate={handleCreate} 
            onOpenSettings={() => setIsSettingsOpen(true)}
            onOpenTraining={() => setView('training')}
          />
          {isSettingsOpen && isAdmin && (
             <GlobalSettingsModal 
                onClose={() => setIsSettingsOpen(false)}
                triggersMap={triggersMap}
                onSaveTriggers={async (t) => { await SupabaseService.saveGlobalTriggers(t); setTriggersMap(t); }}
                injuryDefinitions={injuryDefinitions}
                onSaveInjuries={async (inj) => { await SupabaseService.saveInjuries(inj); setInjuryDefinitions(inj); }}
                timeUnits={timeUnits}
                onSaveTimeUnits={async (units) => { await SupabaseService.saveTimeUnits(units); setTimeUnits(units); }}
             />
          )}
        </>
      )}

      {view === 'sheet' && activeChar && (
        <div className="relative z-10 max-w-5xl mx-auto p-4 md:p-6 animate-fade-in pb-32">

          {/* Top Navigation Bar */}
          <div className="flex items-center justify-between mb-6 bg-[#020617]/80 backdrop-blur-md p-3 border-b border-violet-900/30 sticky top-12 min-[1150px]:top-0 z-50 shadow-lg rune-clip-r">
            <div className="flex items-center gap-2">
               <Button 
                  variant="secondary" 
                  size="sm" 
                  onClick={handleBack} 
                  className="bg-[#0f172a] border-slate-700 hover:bg-slate-800 text-slate-200 hover:text-white shadow-md z-10 font-serif tracking-wide"
               >
                 <ChevronLeft size={18} /> 
                 {t('act_back', "Назад")}
               </Button>
               {charStack.length > 1 && (
                 <span className="text-xs text-slate-500 font-serif uppercase tracking-wider hidden md:inline ml-2 border-l border-slate-700 pl-3">
                   {t('lbl_depth', 'Глубина')}: {charStack.length}
                 </span>
               )}
            </div>

            <div className="flex items-center gap-2">
               {isDialectUnlocked && (
                  <button 
                    onClick={toggleDialect} 
                    className={`p-2 rounded border transition-all ${isOldSlavonic ? 'bg-amber-900/20 text-amber-500 border-amber-800' : 'bg-slate-800 text-slate-500 border-slate-700'}`}
                    title="Old Slavonic Dialect"
                  >
                     <ScrollText size={18} />
                  </button>
               )}

               <div className="h-6 w-px bg-slate-800 mx-1"></div>

               <div className="flex bg-[#0f172a] p-1 rounded-sm border border-slate-800">
                  <button 
                    onClick={() => setDisplayMode('lore')}
                    className={`p-1.5 rounded-sm transition-all ${displayMode === 'lore' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                    title="Lore Mode"
                  >
                    <BookOpen size={16} />
                  </button>
                  <button 
                    onClick={() => setDisplayMode('mech')}
                    className={`p-1.5 rounded-sm transition-all ${displayMode === 'mech' ? 'bg-violet-900/50 text-violet-300 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                    title="Mechanic Mode"
                  >
                    <Calculator size={16} />
                  </button>
               </div>

               {isAdmin && (
                 <>
                   <div className="h-6 w-px bg-slate-800 mx-1"></div>

                   {/* Tag Hints Toggle - Only visible in Edit Mode or if Admin wants to check */}
                   {isEditMode && (
                        <button 
                            onClick={() => setIsTagHintsOpen(true)}
                            className="p-2 bg-violet-900/20 hover:bg-violet-900/40 text-violet-300 border border-violet-500/30 rounded transition-colors"
                            title="Справочник Тегов"
                        >
                            <Tag size={16} />
                        </button>
                   )}

                   {isEditMode ? (
                     <>
                        <Button variant="danger" size="sm" onClick={() => handleDelete(activeChar.id)} title="Delete">
                          <Trash2 size={16} />
                        </Button>
                        <Button variant="secondary" size="sm" onClick={() => {
                           showConfirm("Отменить несохраненные изменения?", () => {
                               // Revert to roster list version if needed, or just exit edit
                               const original = rosterList.find(c => c.id === activeChar.id);
                               if (original) updateActiveChar(original); // Simple revert
                               setIsEditMode(false);
                           });
                        }}>
                           <RotateCcw size={16} />
                        </Button>
                        <Button className="bg-emerald-900/80 hover:bg-emerald-800 border-emerald-500/50" size="sm" onClick={handleSave}>
                          <Save size={16} /> {t('act_save', "Сохранить")}
                        </Button>
                     </>
                   ) : (
                     <Button variant="secondary" size="sm" onClick={() => setIsEditMode(true)}>
                       <Edit3 size={16} /> {t('act_edit', "Ред.")}
                     </Button>
                   )}
                 </>
               )}
            </div>
          </div>

          <SheetHeader 
            character={activeChar} 
            isEditMode={isEditMode} 
            onChange={updateActiveChar} 
            displayMode={displayMode}
            setDisplayMode={setDisplayMode}
            characters={characters}
            onNavigate={handleNavigateToUnit}
            onDelete={handleDelete}
            injuryDefinitions={injuryDefinitions}
          />

          {/* Navigation Tabs - Desktop - UPDATED BG */}
          <div className="hidden md:flex sticky top-28 min-[1150px]:top-14 z-40 bg-[#020617]/95 backdrop-blur-md border-b border-violet-900/30 mb-6 px-0 md:px-0">
             <div className="flex overflow-x-auto no-scrollbar gap-1 pb-1">
                {SHEET_TABS.map(tab => (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id as any)}
                    className={`px-6 py-3 text-sm font-serif font-bold uppercase tracking-widest transition-all whitespace-nowrap relative group flex-shrink-0 ${
                        activeTab === tab.id 
                        ? 'text-violet-300' 
                        : 'text-slate-600 hover:text-slate-300'
                    }`}
                  >
                    {tab.label}
                    {activeTab === tab.id && (
                        <div className="absolute bottom-0 left-0 w-full h-0.5 bg-violet-500 shadow-[0_0_10px_#8b5cf6]"></div>
                    )}
                  </button>
                ))}
             </div>
          </div>

          {/* Navigation Tabs - Mobile (Arrow Swapper) */}
          <div className="md:hidden sticky top-28 min-[1150px]:top-14 z-40 bg-[#020617]/95 backdrop-blur-md border-b border-violet-900/30 mb-6 -mx-4 px-4 py-2 flex items-center justify-between">
              <button onClick={handlePrevTab} className="p-2 text-slate-500 hover:text-white transition-colors">
                  <ChevronLeft size={24} />
              </button>
              <div className="font-serif font-bold uppercase tracking-widest text-violet-300 text-sm">
                  {SHEET_TABS.find(t => t.id === activeTab)?.label}
              </div>
              <button onClick={handleNextTab} className="p-2 text-slate-500 hover:text-white transition-colors">
                  <ChevronRight size={24} />
              </button>
          </div>

          {/* Full Width Content Area */}
          <div>
            {activeTab === 'equipment' && (
              <TabEquipment 
                character={activeChar} 
                isEditMode={isEditMode} 
                onChange={(eq) => updateActiveChar({ equipment: eq })} 
                displayMode={displayMode}
                onInstantUpdate={(eq) => handleInstantUpdate(eq)}
              />
            )}
            {activeTab === 'abilities' && (
              <TabAbilities 
                character={activeChar} 
                isEditMode={isEditMode} 
                onChange={(groups) => updateActiveChar({ ability_groups: groups })}
                displayMode={displayMode}
                timeUnits={timeUnits}
              />
            )}
            {activeTab === 'passives' && (
              <TabPassives 
                character={activeChar} 
                isEditMode={isEditMode} 
                onChange={(p) => updateActiveChar({ passives: p })}
                displayMode={displayMode}
                triggersMap={triggersMap}
                timeUnits={timeUnits}
              />
            )}
            {activeTab === 'debuffs' && (
              <TabDebuffs 
                character={activeChar} 
                isEditMode={isEditMode} 
                onChange={(p) => updateActiveChar({ passives: p })}
                displayMode={displayMode}
                triggersMap={triggersMap}
                timeUnits={timeUnits}
              />
            )}
            {activeTab === 'units' && (
              <TabUnits 
                master={activeChar} 
                units={characters} 
                onCreateUnit={createUnit}
                onNavigateToUnit={handleNavigateToUnit}
                isEditMode={isEditMode}
              />
            )}
            {activeTab === 'medcard' && (
              <TabMedCard 
                character={activeChar} 
                isEditMode={isEditMode} 
                onChange={(mc) => updateActiveChar({ medcard: mc })}
                injuryDefinitions={injuryDefinitions}
              />
            )}
          </div>

        </div>
      )}

      {/* Tag Hints Modal */}
      {isTagHintsOpen && (
          <TagHintsModal 
              isOpen={isTagHintsOpen}
              onClose={() => setIsTagHintsOpen(false)}
              isAdmin={isAdmin}
          />
      )}
    </div>
  );
};

export const RosterAdminContainer: React.FC = () => {
  return null; 
};

const RosterModule: React.FC<RosterModuleProps> = (props) => (
  <DialectProvider>
    <UIProvider>
      <RosterContent {...props} />
    </UIProvider>
  </DialectProvider>
);

export default RosterModule;

export enum Faction {
  LIGHT = "Свет",
  DARK = "Тьма",
  NPC = "Бестиарий",
  GRAVEYARD = "Могильник"
}

export enum StatType {
  PHYS = "phys",
  MAGIC = "magic",
  UNIQUE = "unique"
}

export enum PassiveTrigger {
  ALWAYS = "Always",
  ON_HIT = "On Hit",
  ON_KILL = "On Kill",
  LOW_HP = "Low HP",
  COMBAT_START = "Combat Start",
  ACTIVATED = "Activated",
  INFLICT_PHYS = "Inflict Phys Injury",
  INFLICT_MAG = "Inflict Mag Injury",
  TAKE_PHYS = "Take Phys Injury",
  TAKE_MAG = "Take Mag Injury"
}

export interface Bonus {
  stat: StatType;
  val: number;
}

export interface Resource {
  label: string;
  current: number;
  max: number;
}

export interface Wearable {
  name: string;
  bonuses: Bonus[];
  tags: string[];
  is_equipped: boolean;
  desc_lore: string;
  desc_mech: string;
}

export interface Usable {
  name: string;
  bonuses: Bonus[];
  tags: string[];
  desc_lore: string;
  desc_mech: string;
}

export interface InventoryItem {
  name: string;
  desc_lore: string;
  desc_mech: string;
  qty: number;
}

export interface Ability {
  name: string;
  bonuses: Bonus[];
  tags: string[];
  desc_lore: string;
  desc_mech: string;
  cd: number;
  cd_unit: string;
  dur: number;
  dur_unit: string;
  limit?: number;
  limit_unit?: string;
  is_blocked?: boolean; // New field for locking abilities
}

export interface AbilityGroup {
  name: string;
  tags: string[];
  abilities: Ability[];
  is_hidden?: boolean;
}

export interface Passive {
  name: string;
  bonuses: Bonus[];
  trigger: string;
  tags: string[];
  desc_lore: string;
  desc_mech: string;
  is_flaw: boolean;
  cd: number;
  cd_unit: string;
  dur: number;
  dur_unit: string;
  is_blocked?: boolean; // New field for locking passives
}

export interface PassiveGroup {
  group_name: string;
  tags: string[];
  items: Passive[];
  is_flaw_group?: boolean;
}

export interface InjuryDefinition {
  tag: string;
  label: string;
  value: number;
  type: 1 | 2 | 3;
  desc?: string;
  stack?: number;
}

export interface Injury {
  template_id: string;
  custom_name: string;
  count: number;
}

export interface Condition {
  name: string;
  desc: string;
  turns: number;
}

export interface TimeUnit {
  tag: string;
  label: string;
  battle: boolean;
}

export interface BattleTag {
  tag: string;
  description: string;
}

export interface TrainingRecord {
  char_id: string;
  limits: string; // Format "3/4/2/2/2"
  current: Record<string, number[]>; // Key is day "1", "2". Value is array [0,0,0,0,0]
}

export interface CharacterData {
  id: string;
  meta: {
    uid: string;
    master_id?: string;
    owner_link: string;
    avatar_url: string;
    save_status: boolean;
    save_status_reason?: string;
  };
  profile: {
    name: string;
    faction: Faction;
    npc_volume: string;
    level: number;
    bio: string;
    currencies: {
      juhe: number;
      jumi: number;
    };
  };
  stats: {
    phys: number;
    magic: number;
    unique: number;
  };
  resources: Resource[];
  equipment: {
    wearable: Wearable[];
    usable: Usable[];
    inventory: InventoryItem[];
  };
  ability_groups: AbilityGroup[];
  passives: PassiveGroup[];
  medcard: {
    injuries: Injury[];
    conditions: Condition[];
  };
}

import React, { useState, useMemo } from 'react';
import { CharacterData, TimeUnit, StatType, Bonus } from '../types';
import { Card, StyledInput, StyledTextarea, Button, BonusInput, TagInput, TimeInput, TabRadarCharts, CommonTagToggles } from './Shared';
import { Plus, Trash2, Clock, Hourglass, Check, X, ChevronRight, ChevronDown, Eye, EyeOff, Lock, Unlock } from 'lucide-react';
import { DisplayMode } from '../App';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  displayMode: DisplayMode;
  onChange: (p: CharacterData['passives']) => void;
  triggersMap: Record<string, string>;
  timeUnits: TimeUnit[];
}

const TabPassives: React.FC<Props> = ({ character, isEditMode, displayMode, onChange, triggersMap, timeUnits }) => {
  const { passives } = character;
  const [collapsedGroups, setCollapsedGroups] = useState<Record<number, boolean>>({});
  const [deleteConfirmGroupIdx, setDeleteConfirmGroupIdx] = useState<number | null>(null);
  /* [DIALECT] */ const { t } = useDialect();

  const toggleGroup = (idx: number) => {
    setCollapsedGroups(prev => ({ ...prev, [idx]: !prev[idx] }));
  };

  const updateGroup = (gIdx: number, field: string, val: any) => {
    const next = [...passives];
    next[gIdx] = { ...next[gIdx], [field]: val };
    onChange(next);
  };

  const addGroup = () => onChange([...passives, { group_name: "Классовые", tags: [], items: [], is_flaw_group: false }]);

  const removeGroup = (idx: number) => { 
     const next = passives.filter((_, i) => i !== idx);
     onChange(next);
     setDeleteConfirmGroupIdx(null);
     // Clean up collapsed state
     const newCollapsed = { ...collapsedGroups };
     delete newCollapsed[idx];
     setCollapsedGroups(newCollapsed);
  };

  const addItem = (gIdx: number) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...(group.items || [])];
    group.items.push({ 
      name: "Новая черта", 
      bonuses: [], 
      trigger: Object.keys(triggersMap)[0] || "Always", 
      tags: [], 
      desc_lore: "", 
      desc_mech: "", 
      is_flaw: false,
      cd: 0, cd_unit: "", dur: 0, dur_unit: "", is_blocked: false
    });
    next[gIdx] = group;
    onChange(next);
  };

  const updateItem = (gIdx: number, iIdx: number, field: string, val: any) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...group.items];
    group.items[iIdx] = { ...group.items[iIdx], [field]: val };
    next[gIdx] = group;
    onChange(next);
  };

  const removeItem = (gIdx: number, iIdx: number) => {
    const next = [...passives];
    const group = { ...next[gIdx] };
    group.items = [...group.items];
    group.items.splice(iIdx, 1);
    next[gIdx] = group;
    onChange(next);
  };

  const shouldShowLore = displayMode === 'lore';
  const shouldShowMech = displayMode === 'mech';

  // --- Derived Data for Charts (Memoized) ---
  const structureData = useMemo(() => {
      // Optimization: Skip calculation in Edit Mode
      if (isEditMode) return [];

      const positiveGroups = passives.filter(g => !g.is_flaw_group);

      const data = positiveGroups.map((g, i) => {
        const name = g.group_name || "Unknown";
        let baseName = name.length > 10 ? name.substring(0, 8) + '..' : name;
        return {
          subject: baseName + '\u200B'.repeat(i), 
          value: g.items ? g.items.length : 0
        };
      });
      while (data.length < 3) {
          data.push({ subject: '\u200B'.repeat(100 + data.length), value: 0 });
      }
      return data;
  }, [passives, isEditMode]);

  const bonusData = useMemo(() => {
      // Optimization: Skip calculation in Edit Mode
      if (isEditMode) return [];

      let phys = 0, magic = 0, unique = 0;
      // Iterate only positive groups
      passives.filter(g => !g.is_flaw_group).forEach(g => {
        if (Array.isArray(g.items)) {
          g.items.forEach(item => {
            if (Array.isArray(item.bonuses)) {
              item.bonuses.forEach(b => {
                 const val = Number(b.val);
                 if (!Number.isNaN(val)) {
                    if (b.stat === StatType.PHYS) phys += val;
                    if (b.stat === StatType.MAGIC) magic += val;
                    if (b.stat === StatType.UNIQUE) unique += val;
                 }
              });
            }
          });
        }
      });

      const getValue = (v: number) => Math.max(0, v); 

      return [
        { subject: t('stat_phys_short', 'ФИЗ'), value: getValue(phys) },
        { subject: t('stat_mag_short', 'МАГ'), value: getValue(magic) },
        { subject: t('stat_uni_short', 'УНИК'), value: getValue(unique) },
      ];
  }, [passives, t, isEditMode]);

  return (
    <div className="space-y-8 animate-fade-in relative">

      {/* Charts Visualization - Explicit Emerald Color */}
      {/* PERFORMANCE FIX: Only render charts in View Mode */}
      {!isEditMode && (
          <TabRadarCharts 
              structureData={structureData} 
