      </Modal>
    </div>
  );
};

export enum Faction {
  LIGHT = "Свет",
  DARK = "Тьма",
  NPC = "Бестиарий",
  GRAVEYARD = "Могильник"
}

export enum StatType {
  PHYS = "phys",
  MAGIC = "magic",
  UNIQUE = "unique"
}

export enum PassiveTrigger {
  ALWAYS = "Always",
  ON_HIT = "on_hit",
  ON_DEFENSE = "on_defense",
  ABILITY = "ability",
  LOW_HP = "Low HP",
  COMBAT_START = "Combat Start",
  ACTIVATED = "Activated"
}

export interface Bonus {
  stat: StatType;
  val: number;
}

export interface Resource {
  label: string;
  current: number;
  max: number;
}

export interface Wearable {
  name: string;
  bonuses: Bonus[];
  tags: string[];
  is_equipped: boolean;
  desc_lore: string;
  desc_mech: string;
}

export interface Usable {
