import { BattleParticipant, SequenceNode, JsonAbility, JsonItem, JsonBonus, InjuryRule } from '../types';
import { TRAUMA_DEFINITIONS } from '../constants';

interface CalculationResult {
  formattedString: string;
}

// --- CONFIGURATION ---

const DEFAULT_INJURY_RULES: InjuryRule[] = Object.entries(TRAUMA_DEFINITIONS).map(([tag, def]) => ({
    tag,
    label: def.label,
    value: def.value,
    stack: def.stack
}));

const normalizeTags = (tags: string[] = []) => tags.map(t => t.toLowerCase().trim());

const hasTagOverlap = (sourceTags: string[], targetTags: string[]): boolean => {
    if (!sourceTags || sourceTags.length === 0) return true; 
    return sourceTags.some(t => targetTags.includes(t));
};

const sumBonuses = (bonuses: JsonBonus[] = []): number => {
    return bonuses.reduce((acc, b) => acc + (Number(b.val) || 0), 0);
};

const calculateLiveStatPenalty = (
    participant: BattleParticipant, 
    statType: 'phys' | 'magic' | 'unique',
    rules: InjuryRule[]
): number => {
    if (!participant.medcard || !participant.medcard.injuries) return 0;

    let totalPenalty = 0;
    const suffix = `_${statType === 'unique' ? 'uniq' : statType}`; 

    const injuryCounts: Record<string, number> = {};
    participant.medcard.injuries.forEach(inj => {
        const tag = inj.template_id;
        if (tag.endsWith(suffix)) {
            injuryCounts[tag] = (injuryCounts[tag] || 0) + (inj.count || 1);
        }
    });

    Object.entries(injuryCounts).forEach(([tag, count]) => {
        const rule = rules.find(r => r.tag === tag);
        if (rule) {
            const penaltyValue = Number(rule.value);
            const stackSize = Number(rule.stack);

            if (stackSize > 0) {
                const stacksApplied = Math.floor(count / stackSize);
                totalPenalty += (stacksApplied * penaltyValue);
            } else {
                totalPenalty += (count * penaltyValue);
            }
        }
    });

    return totalPenalty;
};

export const getMatchingFactors = (
    participant: BattleParticipant,
    ability: JsonAbility
) => {
    const factors: { name: string, bonus: number, type: 'passive' | 'effect' | 'item', tags?: string[], desc?: string, mech?: string }[] = [];
    const abilityTags = normalizeTags(ability.tags);
    const abilityName = ability.name;

    // 1. Passives
    if (participant.flat_passives) {
        participant.flat_passives.forEach(pas => {
            const trigger = (pas.trigger || '').toLowerCase().trim();
            const pasTags = normalizeTags(pas.tags);

            let shouldTrigger = false;

            // Trigger logic
            if (trigger === 'always' || trigger === 'пассивно / всегда' || !trigger) {
                shouldTrigger = hasTagOverlap(pasTags, abilityTags);
            } else if (trigger === 'ability') {
                // Trigger specifically if current ability matches linked ability name
                shouldTrigger = pas.trigger_ability_id === abilityName;
            } else if (trigger === 'on_hit') {
                // Trigger if it's an attack/action AND tags overlap
                shouldTrigger = hasTagOverlap(pasTags, abilityTags);
            } else if (trigger === 'on_defense') {
                // Trigger if it's a defense/reaction action AND tags overlap
                // Logic assumes "defense" or "block" tags exist in abilityTags
                const isDefense = abilityTags.some(t => ['defense', 'block', 'dodge', 'защита', 'блок', 'уворот'].includes(t));
                shouldTrigger = isDefense && hasTagOverlap(pasTags, abilityTags);
            }

            if (shouldTrigger) {
                factors.push({ 
                    name: pas.name, 
                    bonus: sumBonuses(pas.bonuses), 
                    type: 'passive', 
                    tags: pas.tags,
                    mech: pas.desc_mech 
                });
            }
        });
    }

    // 2. Active Effects (Existing logic)
    if (participant.active_effects) {
        participant.active_effects.forEach(eff => {
            if (hasTagOverlap(normalizeTags(eff.tags), abilityTags)) {
                let mechanics = '';
                if (eff.original_ability_id) {
                    const source = participant.flat_abilities.find(a => a._id === eff.original_ability_id);
                    if (source) mechanics = source.desc_mech || '';
                }

                factors.push({ 
                    name: eff.name, 
                    bonus: sumBonuses(eff.bonuses), 
                    type: 'effect', 
                    tags: eff.tags,
                    desc: `Active effect. Duration: ${eff.duration_left} ${eff.unit}`,
                    mech: mechanics
                });
            }
        });
    }

    // 3. Wearables (Existing logic)
    if (participant.equipment && participant.equipment.wearable) {
        participant.equipment.wearable.forEach(item => {
            if (item.is_equipped && hasTagOverlap(normalizeTags(item.tags), abilityTags)) {
                factors.push({ 
                    name: item.name, 
                    bonus: sumBonuses(item.bonuses), 
                    type: 'item', 
                    tags: item.tags,
                    mech: item.desc_mech,
                    desc: item.desc_lore
                });
            }
        });
    }

    return factors;
};

const calculateTotalBonus = (
    participant: BattleParticipant, 
    ability: JsonAbility, 
    weapon: JsonItem | undefined,
    injuryRules: InjuryRule[],
    excludedModifiers: string[] = []
): number => {
    let total = 0;

    const usedStats = new Set<string>();
    if (ability.bonuses) {
        ability.bonuses.forEach(b => {
            const bonusVal = Number(b.val) || 0;
            if (b.stat) {
                const statKey = b.stat.toLowerCase();
                if (statKey.includes('phys') || statKey.includes('физ')) {
                    if (!usedStats.has('phys')) {
                        const base = Number(participant.stats.phys) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'phys', injuryRules));
                        usedStats.add('phys');
                    }
                } 
                if (statKey.includes('mag') || statKey.includes('маг')) {
                    if (!usedStats.has('magic')) {
                        const base = Number(participant.stats.magic) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'magic', injuryRules));
                        usedStats.add('magic');
                    }
                } 
                if (statKey.includes('uniq') || statKey.includes('уник')) {
                    if (!usedStats.has('unique')) {
                        const base = Number(participant.stats.unique) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'unique', injuryRules));
                        usedStats.add('unique');
                    }
                }
            }
            total += bonusVal;
        });
    }

    if (weapon) total += sumBonuses(weapon.bonuses);

    const externalFactors = getMatchingFactors(participant, ability);
    externalFactors.forEach(f => {
        if (!excludedModifiers.includes(f.name)) {
            total += f.bonus;
        }
    });

    return total;
};


// --- TREE WALKER ---

const getDiceString = (level: number = 1): string => {
    if (level >= 5) return '3d100';
    if (level >= 3) return '2d100';
    return '1d100';
};

export const calculateSequenceTree = (
  nodes: SequenceNode[],
  participants: BattleParticipant[],
  injuryRules: InjuryRule[] = DEFAULT_INJURY_RULES 
): CalculationResult => {

  const getActionData = (charId: string, abilityId: string, weaponId?: string, excludedModifiers: string[] = []) => {
        const actor = participants.find(p => p.instance_id === charId || p.id === charId);
        if (!actor) return null;

        let ability = actor.flat_abilities?.find(a => a._id === abilityId);

        if (!ability && actor.ability_groups) {
            for (const group of actor.ability_groups) {
                const found = group.abilities.find(a => a._id === abilityId || (a.id && a.id === abilityId) || a.name === abilityId);
                if (found) { ability = found; break; }
            }
        }

        if (!ability) return null;

        const weapon = actor.equipment.usable.find(w => w._id === weaponId || (w.id && w.id === weaponId) || w.name === weaponId);

        const bonusVal = calculateTotalBonus(actor, ability, weapon, injuryRules, excludedModifiers);
        const sign = bonusVal >= 0 ? '+' : '';
        const weaponStr = weapon && weapon.name ? ` [${weapon.name}]` : ''; 
        const nameStr = `${ability.name}${weaponStr}`;
        const diceStr = getDiceString(actor.profile.level);

        const isForm = ability.tags.some(t => ['form', 'форма'].includes(t.toLowerCase()));
        const isBuff = ability.tags.some(t => ['buff', 'бафф'].includes(t.toLowerCase()));

        return { 
            name: nameStr, 
            actorName: actor.profile.name,
            bonus: `${sign}${bonusVal}`, 
            dice: diceStr, 
            isForm,
            isBuff,
            mechanics: ability.desc_mech
        };
  };

  const processNode = (node: SequenceNode): string => {
    if (node.type === 'divider') return '__DIVIDER__';

    if (node.type === 'logic_chain') {
        const childrenStr = node.children.map(c => processNode(c)).join(' | ');
        return `\n{ ${childrenStr} }`;
    }

    if (node.type === 'condition') {
      const conditionText = node.data?.conditionText || '...';
      const childStrings = node.children.map(c => processNode(c)).filter(s => s && s.trim() !== '');
      let innerContent = childStrings.join(' - ');
      return `${conditionText}: ${innerContent}`;
    }

    if (node.type === 'combo') {
      const validChildren = node.children.filter(c => c.type === 'action');
      if (validChildren.length === 0) return '';

      const dataList = validChildren.map(c => 
          getActionData(c.data?.charId || '', c.data?.abilityId || '', c.data?.weaponId, c.data?.excludedModifiers)
      ).filter(Boolean) as any[];

      if (dataList.length === 0) return '';

      const namesPart = dataList.map(d => `${d.actorName}: ${d.name}`).join(' + ');
      const bonusesPart = dataList.map(d => (d.isForm || d.isBuff) ? '-' : `${d.dice}${d.bonus}`).join('/');

      return `[${namesPart}(${bonusesPart})]`;
    }

    if (node.type === 'action') {
        const data = getActionData(node.data?.charId || '', node.data?.abilityId || '', node.data?.weaponId, node.data?.excludedModifiers);
        if (!data) return '[Unknown Action]';

        if (data.isForm) {
            return `<${data.actorName}: ${data.name} (${data.mechanics || ''})>`;
        }

        if (data.isBuff) {
            return `(${data.actorName}: ${data.name} (${data.mechanics || ''}))`;
        }

        return `${data.actorName}: ${data.name}(${data.dice}${data.bonus})`;
    }

    return '';
  };

  const parts = nodes.map(n => processNode(n)).filter(Boolean);

  let finalString = '';
  let isStartOfLine = true; 

  parts.forEach((part, index) => {
      if (part === '__DIVIDER__') {
          finalString += '\n\n'; 
          isStartOfLine = true;
      } else {
          const cleanPart = part.trim();
          if (cleanPart) {
              if (isStartOfLine) {
                  finalString += '> ' + cleanPart;
                  isStartOfLine = false;
              } else {
                  finalString += ' - ' + cleanPart;
              }
          }
      }
  });

  return { formattedString: finalString.trim() };
};

import { CharacterTemplate, JsonAbility, JsonItem, JsonPassiveItem, JsonInjury } from '../types';
import { TRAUMA_DEFINITIONS } from '../constants';
import { supabase } from '../../../lib/supabase';

export { supabase };

// Helper to generate IDs for items inside JSON that might lack them
const generateId = () => Math.random().toString(36).substr(2, 9);

// Helper: robustly extract tags from an object whether it uses 'tags' (array) or 'tag' (string)
const getTags = (obj: any): string[] => {
    if (!obj) return [];
    let collected: string[] = [];

    if (Array.isArray(obj.tags)) {
        collected = [...obj.tags];
    } else if (typeof obj.tags === 'string') {
        collected.push(obj.tags);
    }

    if (typeof obj.tag === 'string') {
        collected.push(obj.tag);
    }

    // Clean and lowercase
    return collected.map(t => t.toLowerCase().trim()).filter(Boolean);
};

// Helper: Calculate total trauma penalty based on definitions
export const calculateTraumaPenalty = (injuries: JsonInjury[] = []) => {
  let totals = {
      phys: 0,
      mag: 0,
      uniq: 0,
      total: 0
  };

  const injuryCounts: Record<string, number> = {};

  injuries.forEach(injury => {
      const current = injuryCounts[injury.template_id] || 0;
      injuryCounts[injury.template_id] = current + (injury.count || 1);
  });

  for (const [templateId, count] of Object.entries(injuryCounts)) {
      const def = TRAUMA_DEFINITIONS[templateId];
      if (!def) continue;

      let penalty = 0;
      if (def.stack && def.stack > 0) {
          const stacks = Math.floor(count / def.stack);
          penalty = stacks * def.value;
      } else {
          penalty = count * def.value;
      }

      totals.total += penalty;
      if (templateId.includes('phys')) totals.phys += penalty;
      else if (templateId.includes('mag')) totals.mag += penalty;
      else if (templateId.includes('uniq')) totals.uniq += penalty;
  }

  return totals;
};

// Normalization Helpers
const normalizeBonuses = (items: any[]) => {
  if (!Array.isArray(items)) return [];
  return items.map(item => ({
    ...item,
    bonuses: (item.bonuses || []).map((b: any) => ({
      stat: (b.stat || 'phys').toLowerCase().trim(),
      val: b.val !== undefined ? b.val : (b.value !== undefined ? b.value : 0)
    }))
  }));
};

const normalizeItems = (items: any[]) => {
    if (!Array.isArray(items)) return [];
    const normalized = normalizeBonuses(items);
    return normalized.map((item: any) => ({
        ...item,
        desc_lore: item.desc_lore !== undefined ? item.desc_lore : (item.desc?.lore || ''),
        desc_mech: item.desc_mech !== undefined ? item.desc_mech : (item.desc?.mech || '')
    }));
};

const normalizeAbilities = (abilities: any[]) => {
  if (!Array.isArray(abilities)) return [];
  const normalizedItems = normalizeItems(abilities);
  return normalizedItems.map((ab: any) => ({
    ...ab,
    limit: ab.limit !== undefined ? ab.limit : (ab.limits?.value || 0),
    limit_unit: ab.limit_unit !== undefined ? ab.limit_unit : (ab.limits?.unit || ''),
    cd: ab.cd !== undefined ? ab.cd : (ab.cooldown?.value || 0),
    cd_unit: ab.cd_unit !== undefined ? ab.cd_unit : (ab.cooldown?.unit || ''),
    dur: ab.dur !== undefined ? ab.dur : (ab.duration?.value || 0),
    dur_unit: ab.dur_unit !== undefined ? ab.dur_unit : (ab.duration?.unit || '')
  }));
};

const normalizeTrigger = (trigger: string): string => {
    if (!trigger) return 'ALWAYS';
    const t = trigger.toLowerCase().trim();
    if (t.includes('start') || t.includes('начало')) return 'COMBAT_START';
    if (t.includes('hit') || t.includes('попадан') || t.includes('удар')) return 'on_hit';
    if (t.includes('defense') || t.includes('защит')) return 'on_defense';
    if (t.includes('ability') || t.includes('способнос')) return 'ability';
    if (t.includes('always') || t.includes('всегда') || t.includes('пассив')) return 'ALWAYS';
    return t; 
}

export async function getCharacters() {
  console.log('Fetching characters...');
  const { data, error } = await supabase.from('characters').select('*');

  if (error) {
    console.error('Supabase: Error fetching characters:', error);
    return { data: [], error };
  }

  if (!data) return { data: [], error: null };

  const formattedData = data.map((row: any) => {
    let charData = row.data || row;
    if (row.data && typeof row.data === 'object') {
       charData = { ...row.data, id: row.id };
    }

    const result: any = {
        id: charData.id || generateId(),
        meta: charData.meta || { uid: 'system', avatar_url: '' },
        profile: charData.profile || charData.identity || { name: 'Unknown', level: 1, faction: 'None', npc_volume: '' },
        stats: charData.stats || { phys: 0, magic: 0, unique: 0 },
        resources: charData.resources || [],
        equipment: { usable: [], wearable: [], inventory: [] },
        ability_groups: [],
        passives: [], 
        medcard: charData.medcard || charData.med_card || { injuries: [], conditions: [] },
        flat_abilities: [],
        flat_passives: []
    };

    const tabs = charData.tabs || {};

    let rawWearable = tabs.equipment?.wearable || charData.equipment?.wearable;
    result.equipment.wearable = normalizeItems(rawWearable).map((i: any) => ({...i, _id: generateId(), tags: getTags(i)}));

    let rawUsable = tabs.equipment?.weapons || tabs.equipment?.usable || charData.equipment?.weapons || charData.equipment?.usable;
    result.equipment.usable = normalizeItems(rawUsable).map((i: any) => ({...i, _id: generateId(), tags: getTags(i)}));

    let rawInventory = tabs.equipment?.backpack || tabs.equipment?.inventory || charData.equipment?.backpack || charData.equipment?.inventory;
    result.equipment.inventory = normalizeItems(rawInventory).map((i: any) => ({...i, _id: generateId(), tags: getTags(i)}));

    let rawAbilityGroups = [];
    if (tabs.abilities && Array.isArray(tabs.abilities.schools)) {
        rawAbilityGroups = tabs.abilities.schools;
    } else if (Array.isArray(charData.ability_groups)) {
        rawAbilityGroups = charData.ability_groups;
    }

    if (rawAbilityGroups.length > 0) {
        result.ability_groups = rawAbilityGroups.map((group: any) => {
            const groupTags = getTags(group);
            const abilities = normalizeAbilities(group.abilities).map((ab: any) => {
                const abTags = [...new Set([...groupTags, ...getTags(ab)])];
                const hydrated = { ...ab, _id: generateId(), tags: abTags };
                if (!abTags.includes('no_war')) {
                    result.flat_abilities.push(hydrated);
                }
                return hydrated;
            });
            return { ...group, abilities };
        });
    }

    let rawPassiveGroups = [];
    if (tabs.passives && Array.isArray(tabs.passives.groups)) {
        rawPassiveGroups = tabs.passives.groups;
    } else if (Array.isArray(charData.passives)) {
        rawPassiveGroups = charData.passives;
    }

    if (rawPassiveGroups.length > 0) {
        rawPassiveGroups.forEach((group: any) => {
            const groupTags = getTags(group);
            const rawItems = group.items || group.abilities || [];

            const items = normalizeItems(rawItems).map((p: any) => {
                const pTags = [...new Set([...groupTags, ...getTags(p)])];
                const hydrated = {
                    ...p,
                    _id: generateId(),
                    tags: pTags,
                    trigger: normalizeTrigger(p.trigger),
                    trigger_ability_id: p.trigger_ability_id,
                    is_flaw: false,
                    dur: p.dur || 0,
                    dur_unit: p.dur_unit || 'turn'
                };
                result.flat_passives.push(hydrated);
                return hydrated;
            });

            result.passives.push({
                group_name: group.group_name || group.name || "Passives",
                is_flaw_group: false,
                items
            });
        });
    }

    let rawDebuffGroups = [];
    if (tabs.debuffs && Array.isArray(tabs.debuffs.groups)) {
        rawDebuffGroups = tabs.debuffs.groups;
    } else if (Array.isArray(charData.debuffs)) {
        rawDebuffGroups = charData.debuffs;
    }

    if (rawDebuffGroups.length > 0) {
        rawDebuffGroups.forEach((group: any) => {
            const groupTags = getTags(group);
            const rawItems = group.items || group.abilities || [];

            const items = normalizeItems(rawItems).map((p: any) => {
                const pTags = [...new Set([...groupTags, ...getTags(p)])];
                const hydrated = {
                    ...p,
                    _id: generateId(),
                    tags: pTags,
                    trigger: normalizeTrigger(p.trigger),
                    trigger_ability_id: p.trigger_ability_id,
                    is_flaw: true,
                    dur: p.dur || 0,
                    dur_unit: p.dur_unit || 'turn'
                };
                result.flat_passives.push(hydrated);
                return hydrated;
            });

            result.passives.push({
                group_name: group.group_name || group.name || "Debuffs",
                is_flaw_group: true,
                items
            });
        });
    }

    const trauma = calculateTraumaPenalty(result.medcard.injuries);
    result.battle_stats = {
        hp_penalty_current: trauma.total,
        trauma_phys: trauma.phys,
        trauma_mag: trauma.mag,
        trauma_uniq: trauma.uniq,
        actions_max: 4, 
        actions_left: 4
    };

    return result;
  });

  return { data: formattedData as CharacterTemplate[], error: null };
}

