                                                            <option key={a.name} value={a.name}>{a.name}</option>
                                                        ))}
                                                    </optgroup>
                                                ))}
                                            </select>
                                        ) : (
                                            <div className="flex items-center gap-2 text-amber-500 text-[10px] italic">
                                                <AlertCircle size={10} /> У персонажа нет способностей для привязки.
                                            </div>
