import { BattleParticipant, SequenceNode, JsonAbility, JsonItem, JsonBonus, InjuryRule } from '../types';
import { TRAUMA_DEFINITIONS } from '../constants';

interface CalculationResult {
  formattedString: string;
}

// --- CONFIGURATION ---

const DEFAULT_INJURY_RULES: InjuryRule[] = Object.entries(TRAUMA_DEFINITIONS).map(([tag, def]) => ({
    tag,
    label: def.label,
    value: def.value,
    stack: def.stack
}));

const normalizeTags = (tags: string[] = []) => tags.map(t => t.toLowerCase().trim());

const hasTagOverlap = (sourceTags: string[], targetTags: string[]): boolean => {
    if (!sourceTags || sourceTags.length === 0) return true; 
    return sourceTags.some(t => targetTags.includes(t));
};

const sumBonuses = (bonuses: JsonBonus[] = []): number => {
    return bonuses.reduce((acc, b) => acc + (Number(b.val) || 0), 0);
};

const calculateLiveStatPenalty = (
    participant: BattleParticipant, 
    statType: 'phys' | 'magic' | 'unique',
    rules: InjuryRule[]
): number => {
    if (!participant.medcard || !participant.medcard.injuries) return 0;

    let totalPenalty = 0;
    const suffix = `_${statType === 'unique' ? 'uniq' : statType}`; 

    const injuryCounts: Record<string, number> = {};
    participant.medcard.injuries.forEach(inj => {
        const tag = inj.template_id;
        if (tag.endsWith(suffix)) {
            injuryCounts[tag] = (injuryCounts[tag] || 0) + (inj.count || 1);
        }
    });

    Object.entries(injuryCounts).forEach(([tag, count]) => {
        const rule = rules.find(r => r.tag === tag);
        if (rule) {
            const penaltyValue = Number(rule.value);
            const stackSize = Number(rule.stack);

            if (stackSize > 0) {
                const stacksApplied = Math.floor(count / stackSize);
                totalPenalty += (stacksApplied * penaltyValue);
            } else {
                totalPenalty += (count * penaltyValue);
            }
        }
    });

    return totalPenalty;
};

export const getMatchingFactors = (
    participant: BattleParticipant,
    ability: JsonAbility
) => {
    const factors: { name: string, bonus: number, type: 'passive' | 'effect' | 'item', tags?: string[], desc?: string, mech?: string }[] = [];
    const abilityTags = normalizeTags(ability.tags);
    const abilityName = ability.name;

    // 1. Passives
    if (participant.flat_passives) {
        participant.flat_passives.forEach(pas => {
            const trigger = (pas.trigger || '').toLowerCase().trim();
            const pasTags = normalizeTags(pas.tags);

            let shouldTrigger = false;

            // Trigger logic
            if (trigger === 'always' || trigger === 'пассивно / всегда' || !trigger) {
                shouldTrigger = hasTagOverlap(pasTags, abilityTags);
            } else if (trigger === 'ability') {
                // Trigger specifically if current ability matches linked ability name
                shouldTrigger = pas.trigger_ability_id === abilityName;
            } else if (trigger === 'on_hit') {
                // Trigger if it's an attack/action AND tags overlap
                const isAttack = abilityTags.some(t => ['attack', 'hit', 'удар', 'атака', 'melee', 'ranged'].includes(t));
                shouldTrigger = isAttack && hasTagOverlap(pasTags, abilityTags);
            } else if (trigger === 'on_defense') {
                // Trigger if it's a defense/reaction action AND tags overlap
                const isDefense = abilityTags.some(t => ['defense', 'block', 'dodge', 'защита', 'блок', 'уворот'].includes(t));
                shouldTrigger = isDefense && hasTagOverlap(pasTags, abilityTags);
            }

            if (shouldTrigger) {
                factors.push({ 
                    name: pas.name, 
                    bonus: sumBonuses(pas.bonuses), 
                    type: 'passive', 
                    tags: pas.tags,
                    mech: pas.desc_mech 
                });
            }
        });
    }

    // 2. Active Effects
    if (participant.active_effects) {
        participant.active_effects.forEach(eff => {
            if (hasTagOverlap(normalizeTags(eff.tags), abilityTags)) {
                let mechanics = '';
                if (eff.original_ability_id) {
                    const source = participant.flat_abilities.find(a => a._id === eff.original_ability_id);
                    if (source) mechanics = source.desc_mech || '';
                }

                factors.push({ 
                    name: eff.name, 
                    bonus: sumBonuses(eff.bonuses), 
                    type: 'effect', 
                    tags: eff.tags,
                    desc: `Active effect. Duration: ${eff.duration_left} ${eff.unit}`,
                    mech: mechanics
                });
            }
        });
    }

    // 3. Wearables
    if (participant.equipment && participant.equipment.wearable) {
        participant.equipment.wearable.forEach(item => {
            if (item.is_equipped && hasTagOverlap(normalizeTags(item.tags), abilityTags)) {
                factors.push({ 
                    name: item.name, 
                    bonus: sumBonuses(item.bonuses), 
                    type: 'item', 
                    tags: item.tags,
                    mech: item.desc_mech,
                    desc: item.desc_lore
                });
            }
        });
    }

    return factors;
};

const calculateTotalBonus = (
    participant: BattleParticipant, 
    ability: JsonAbility, 
    weapon: JsonItem | undefined,
    injuryRules: InjuryRule[],
    excludedModifiers: string[] = []
): number => {
    let total = 0;

    const usedStats = new Set<string>();
    if (ability.bonuses) {
        ability.bonuses.forEach(b => {
            const bonusVal = Number(b.val) || 0;
            if (b.stat) {
                const statKey = b.stat.toLowerCase();
                if (statKey.includes('phys') || statKey.includes('физ')) {
                    if (!usedStats.has('phys')) {
                        const base = Number(participant.stats.phys) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'phys', injuryRules));
                        usedStats.add('phys');
                    }
                } 
                if (statKey.includes('mag') || statKey.includes('маг')) {
                    if (!usedStats.has('magic')) {
                        const base = Number(participant.stats.magic) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'magic', injuryRules));
                        usedStats.add('magic');
                    }
                } 
                if (statKey.includes('uniq') || statKey.includes('уник')) {
                    if (!usedStats.has('unique')) {
                        const base = Number(participant.stats.unique) || 0;
                        total += (base + calculateLiveStatPenalty(participant, 'unique', injuryRules));
                        usedStats.add('unique');
                    }
                }
            }
            total += bonusVal;
        });
    }

    if (weapon) total += sumBonuses(weapon.bonuses);

    const externalFactors = getMatchingFactors(participant, ability);
    externalFactors.forEach(f => {
        if (!excludedModifiers.includes(f.name)) {
            total += f.bonus;
        }
    });

    return total;
};


// --- TREE WALKER ---

const getDiceString = (level: number = 1): string => {
    if (level >= 5) return '3d100';
    if (level >= 3) return '2d100';
    return '1d100';
};

export const calculateSequenceTree = (
  nodes: SequenceNode[],
  participants: BattleParticipant[],
  injuryRules: InjuryRule[] = DEFAULT_INJURY_RULES 
): CalculationResult => {

  const getActionData = (charId: string, abilityId: string, weaponId?: string, excludedModifiers: string[] = []) => {
        const actor = participants.find(p => p.instance_id === charId || p.id === charId);
        if (!actor) return null;

        let ability = actor.flat_abilities?.find(a => a._id === abilityId);

        if (!ability && actor.ability_groups) {
            for (const group of actor.ability_groups) {
                const found = group.abilities.find(a => a._id === abilityId || (a.id && a.id === abilityId) || a.name === abilityId);
                if (found) { ability = found; break; }
            }
        }

        if (!ability) return null;

        const weapon = actor.equipment.usable.find(w => w._id === weaponId || (w.id && w.id === weaponId) || w.name === weaponId);

        const bonusVal = calculateTotalBonus(actor, ability, weapon, injuryRules, excludedModifiers);
        const sign = bonusVal >= 0 ? '+' : '';
        const weaponStr = weapon && weapon.name ? ` [${weapon.name}]` : ''; 
        const nameStr = `${ability.name}${weaponStr}`;
        const diceStr = getDiceString(actor.profile.level);

        const isForm = ability.tags.some(t => ['form', 'форма'].includes(t.toLowerCase()));
        const isBuff = ability.tags.some(t => ['buff', 'бафф'].includes(t.toLowerCase()));

        return { 
            name: nameStr, 
            actorName: actor.profile.name,
            bonus: `${sign}${bonusVal}`, 
            dice: diceStr, 
            isForm,
            isBuff,
            mechanics: ability.desc_mech
        };
  };

  const processNode = (node: SequenceNode): string => {
    if (node.type === 'divider') return '__DIVIDER__';

    if (node.type === 'logic_chain') {
        const childrenStr = node.children.map(c => processNode(c)).join(' | ');
        return `\n{ ${childrenStr} }`;
    }

    if (node.type === 'condition') {
      const conditionText = node.data?.conditionText || '...';
      const childStrings = node.children.map(c => processNode(c)).filter(s => s && s.trim() !== '');
      let innerContent = childStrings.join(' - ');
      return `${conditionText}: ${innerContent}`;
    }

    if (node.type === 'combo') {
      const validChildren = node.children.filter(c => c.type === 'action');
      if (validChildren.length === 0) return '';

      const dataList = validChildren.map(c => 
          getActionData(c.data?.charId || '', c.data?.abilityId || '', c.data?.weaponId, c.data?.excludedModifiers)
      ).filter(Boolean) as any[];

      if (dataList.length === 0) return '';

      const namesPart = dataList.map(d => `${d.actorName}: ${d.name}`).join(' + ');
      const bonusesPart = dataList.map(d => (d.isForm || d.isBuff) ? '-' : `${d.dice}${d.bonus}`).join('/');

      return `[${namesPart}(${bonusesPart})]`;
    }

    if (node.type === 'action') {
        const data = getActionData(node.data?.charId || '', node.data?.abilityId || '', node.data?.weaponId, node.data?.excludedModifiers);
        if (!data) return '[Unknown Action]';

        if (data.isForm) {
            return `<${data.actorName}: ${data.name} (${data.mechanics || ''})>`;
        }

        if (data.isBuff) {
            return `(${data.actorName}: ${data.name} (${data.mechanics || ''}))`;
        }

        return `${data.actorName}: ${data.name}(${data.dice}${data.bonus})`;
    }

    return '';
  };

  const parts = nodes.map(n => processNode(n)).filter(Boolean);

  let finalString = '';
  let isStartOfLine = true; 

  parts.forEach((part, index) => {
      if (part === '__DIVIDER__') {
          finalString += '\n\n'; 
          isStartOfLine = true;
      } else {
          const cleanPart = part.trim();
          if (cleanPart) {
              if (isStartOfLine) {
                  finalString += '> ' + cleanPart;
                  isStartOfLine = false;
              } else {
                  finalString += ' - ' + cleanPart;
              }
          }
      }
  });

  return { formattedString: finalString.trim() };
};

// [DIALECT] - This whole file is part of the dialect module
import React, { createContext, useContext, useState, useEffect } from 'react';
import { DIALECT_DICT } from './dictionary';
import { Faction } from '../types';

interface DialectContextType {
  isOldSlavonic: boolean;
  isDialectUnlocked: boolean;
  isBloodMode: boolean;
  isToggleVisible: boolean;
  toggleDialect: () => void;
  toggleDialectButtonVisibility: () => void; // New direct toggle
  handleSlashClick: () => void;
  handleLetterClick: (char: string) => void;
  isInputMode: boolean;
  inputBuffer: string;
  t: (key: string, defaultText: string) => string;
  trackTabChange: (faction: Faction) => void;
}

const DialectContext = createContext<DialectContextType | undefined>(undefined);

export const DialectProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isOldSlavonic, setIsOldSlavonic] = useState(false);
  const [isDialectUnlocked, setIsDialectUnlocked] = useState(false);
  const [isBloodMode, setIsBloodMode] = useState(false);

  // Is the scroll button visible in the sheet header?
  const [isToggleVisible, setIsToggleVisible] = useState(false);

  // Easter Egg State
  const [slashClickCount, setSlashClickCount] = useState(0);
  const [isInputMode, setIsInputMode] = useState(false);
  const [inputBuffer, setInputBuffer] = useState("");

  const SLAVONIC_CODE = "пишет//дед";
  const BLOOD_CODE = "тело//и//плоть";
  const CLICKS_REQUIRED = 15;

  useEffect(() => {
    // Load persisted states
    const savedDialect = localStorage.getItem('isOldSlavonic') === 'true';
    const savedUnlock = localStorage.getItem('isDialectUnlocked') === 'true';
    const savedBlood = localStorage.getItem('isBloodMode') === 'true';
    const savedVisible = localStorage.getItem('isToggleVisible') === 'true';

    setIsOldSlavonic(savedDialect);
    setIsDialectUnlocked(savedUnlock);
    setIsBloodMode(savedBlood);
    setIsToggleVisible(savedVisible);
  }, []);

  const toggleDialectButtonVisibility = () => {
      setIsToggleVisible(prev => {
          const next = !prev;
          localStorage.setItem('isToggleVisible', String(next));
          return next;
      });
  };

  const unlockDialect = () => {
    setIsDialectUnlocked(true);
    localStorage.setItem('isDialectUnlocked', 'true');
    setIsInputMode(false);
    setInputBuffer("");
    console.log("Dialect Unlocked!");
  };

  const activateBloodMode = () => {
      const newState = !isBloodMode;
      setIsBloodMode(newState);
      localStorage.setItem('isBloodMode', String(newState));
      setIsInputMode(false);
      setInputBuffer("");
  };

  const handleSlashClick = () => {
    if (!isInputMode) {
      const newCount = slashClickCount + 1;
      setSlashClickCount(newCount);
      if (newCount >= CLICKS_REQUIRED) {
        setIsInputMode(true);
        setInputBuffer("");
      }
    } else {
      handleLetterClick("//");
    }
  };

  const handleLetterClick = (char: string) => {
    if (!isInputMode) return;

    setInputBuffer(prev => {
      const next = (prev + char.toLowerCase()).slice(-20);

      if (next.includes(SLAVONIC_CODE)) {
         unlockDialect();
      }
      if (next.includes(BLOOD_CODE)) {
         activateBloodMode();
      }
      return next;
    });
  };

  const toggleDialect = () => {
    setIsOldSlavonic(prev => {
      const next = !prev;
      localStorage.setItem('isOldSlavonic', String(next));
      return next;
    });
  };

  const t = (key: string, defaultText: string) => {
    if (!isOldSlavonic) return defaultText;
    return DIALECT_DICT[key] || defaultText;
  };

  const trackTabChange = (faction: Faction) => {
      // Deprecated
  };

  return (
    <DialectContext.Provider value={{ 
      isOldSlavonic, 
      isDialectUnlocked, 
      isBloodMode,
      isToggleVisible,
      toggleDialect, 
      toggleDialectButtonVisibility,
      handleSlashClick, 
      handleLetterClick, 
      isInputMode,
      inputBuffer,
      t,
      trackTabChange
    }}>
      {children}
    </DialectContext.Provider>
  );
};

export const useDialect = () => {
  const context = useContext(DialectContext);
  if (!context) {
    return { 
      isOldSlavonic: false, 
      isDialectUnlocked: false, 
      isBloodMode: false,
      isToggleVisible: false,
      toggleDialect: () => {}, 
      toggleDialectButtonVisibility: () => {},
      handleSlashClick: () => {},
      handleLetterClick: () => {},
      isInputMode: false,
      inputBuffer: "",
      t: (_: string, d: string) => d,
      trackTabChange: () => {}
    };
  }
  return context;
};

