                     </Card>
                   )})}
                   {isEditMode && <Button onClick={() => addItem(gIdx)} variant="secondary" className="border-dashed"><Plus size={14} /> {t('mech_debuffs', "Добавить Дебафф")}</Button>}
                 </div>
             )}
           </div>
         );
      })}
       {isEditMode && <Button onClick={addGroup} className="w-full py-4 border-dashed border-2 bg-slate-900/50 backdrop-blur-sm border-gray-800 text-gray-500 hover:text-white hover:border-gray-600">{t('mech_debuffs', "Создать группу дебаффов")}</Button>}
    </div>
  );
};

