// [DIALECT] - This whole file is part of the dialect module
import React, { createContext, useContext, useState, useEffect } from 'react';
import { DIALECT_DICT } from './dictionary';
import { Faction } from '../types';

interface DialectContextType {
  isOldSlavonic: boolean;
  isDialectUnlocked: boolean;
  isBloodMode: boolean;
  isToggleVisible: boolean;
  toggleDialect: () => void;
  toggleDialectButtonVisibility: () => void;
  handleSlashClick: () => void;
  handleLetterClick: (char: string) => void;
  isInputMode: boolean;
  inputBuffer: string;
  t: (key: string, defaultText: string) => string;
  trackTabChange: (faction: Faction) => void;
}

const DialectContext = createContext<DialectContextType | undefined>(undefined);

export const DialectProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isOldSlavonic, setIsOldSlavonic] = useState(false);
  const [isDialectUnlocked, setIsDialectUnlocked] = useState(false);
  const [isBloodMode, setIsBloodMode] = useState(false);
  const [isToggleVisible, setIsToggleVisible] = useState(false);

  const [slashClickCount, setSlashClickCount] = useState(0);
  const [isInputMode, setIsInputMode] = useState(false);
  const [inputBuffer, setInputBuffer] = useState("");

  const SLAVONIC_CODE = "пишет//дед";

  // Blood mode logic codes
  const BLOOD_ON = "телоиплоть";
  const BLOOD_ON_ALT = "ntkjbgkjnm"; // English layout

  const BLOOD_OFF = "раккубов";
  const BLOOD_OFF_ALT = "hfrre,,jd"; // English layout

  const CLICKS_REQUIRED = 15;

  useEffect(() => {
    const savedDialect = localStorage.getItem('isOldSlavonic') === 'true';
    const savedUnlock = localStorage.getItem('isDialectUnlocked') === 'true';
    const savedBlood = localStorage.getItem('isBloodMode') === 'true';
    const savedVisible = localStorage.getItem('isToggleVisible') === 'true';

    setIsOldSlavonic(savedDialect);
    setIsDialectUnlocked(savedUnlock);
    setIsBloodMode(savedBlood);
    setIsToggleVisible(savedVisible);

    // Global Key Listener for secret codes
    let keyBuffer = "";
    const handleGlobalKey = (e: KeyboardEvent) => {
        // Build buffer ignoring spaces for "тело и плоть"
        if (e.key === " ") return; 

        keyBuffer = (keyBuffer + e.key.toLowerCase()).slice(-20);

        // CHECK ON
        if (keyBuffer.includes(BLOOD_ON) || keyBuffer.includes(BLOOD_ON_ALT)) {
            setIsBloodMode(true);
            localStorage.setItem('isBloodMode', 'true');
            keyBuffer = "";
            console.log("Blood Mode: ACTIVATED");
        }

        // CHECK OFF
        if (keyBuffer.includes(BLOOD_OFF) || keyBuffer.includes(BLOOD_OFF_ALT)) {
            setIsBloodMode(false);
            localStorage.setItem('isBloodMode', 'false');
            keyBuffer = "";
            console.log("Blood Mode: DEACTIVATED");
        }
    };

    window.addEventListener('keydown', handleGlobalKey);
    return () => window.removeEventListener('keydown', handleGlobalKey);
  }, []);

  const toggleDialectButtonVisibility = () => {
      setIsToggleVisible(prev => {
          const next = !prev;
          localStorage.setItem('isToggleVisible', String(next));
          return next;
      });
  };

  const unlockDialect = () => {
    setIsDialectUnlocked(true);
    localStorage.setItem('isDialectUnlocked', 'true');
    setIsInputMode(false);
    setInputBuffer("");
  };

  const handleSlashClick = () => {
    if (!isInputMode) {
      const newCount = slashClickCount + 1;
      setSlashClickCount(newCount);
      if (newCount >= CLICKS_REQUIRED) {
        setIsInputMode(true);
        setInputBuffer("");
      }
    } else {
      handleLetterClick("//");
    }
  };

  const handleLetterClick = (char: string) => {
    if (!isInputMode) return;
    setInputBuffer(prev => {
      const next = (prev + char.toLowerCase()).slice(-20);
      if (next.includes(SLAVONIC_CODE)) unlockDialect();

      // Manual click checks for Blood Mode
      if (next.includes(BLOOD_ON)) {
          setIsBloodMode(true);
          localStorage.setItem('isBloodMode', 'true');
      }
      if (next.includes(BLOOD_OFF)) {
          setIsBloodMode(false);
          localStorage.setItem('isBloodMode', 'false');
      }
      return next;
    });
  };

  const toggleDialect = () => {
    setIsOldSlavonic(prev => {
      const next = !prev;
      localStorage.setItem('isOldSlavonic', String(next));
      return next;
    });
  };

  const t = (key: string, defaultText: string) => {
    if (!isOldSlavonic) return defaultText;
    return DIALECT_DICT[key] || defaultText;
  };

  const trackTabChange = (faction: Faction) => {};

  return (
    <DialectContext.Provider value={{ 
      isOldSlavonic, isDialectUnlocked, isBloodMode, isToggleVisible,
      toggleDialect, toggleDialectButtonVisibility,
      handleSlashClick, handleLetterClick, isInputMode, inputBuffer, t, trackTabChange
    }}>
      {children}
    </DialectContext.Provider>
  );
};

export const useDialect = () => {
  const context = useContext(DialectContext);
  if (!context) {
    return { 
      isOldSlavonic: false, isDialectUnlocked: false, isBloodMode: false, isToggleVisible: false,
      toggleDialect: () => {}, toggleDialectButtonVisibility: () => {},
      handleSlashClick: () => {}, handleLetterClick: () => {},
      isInputMode: false, inputBuffer: "", t: (_: string, d: string) => d, trackTabChange: () => {}
    };
  }
  return context;
};

