        // --- NEW: EXTRACT PASSIVE NAMES FOR LOGGING ---
        const externalFactors = getMatchingFactors(actor, ability.tags);
        const activeModifiers = externalFactors
            .filter(f => !excludedModifiers.includes(f.name))
            .filter(f => {
