                ...p,
                _id: generateId(),
                tags: pTags,
                trigger: normalizeTrigger(p.trigger),
                is_flaw: !!group.is_flaw_group,
                dur: p.dur || 0,
                dur_unit: p.dur_unit || 'turn'
            };
            result.flat_passives.push(hydrated);
            return hydrated;
        });
        result.passives.push({
            group_name: group.group_name || group.name || (group.is_flaw_group ? "Debuffs" : "Passives"),
            is_flaw_group: !!group.is_flaw_group,
            items
        });
    });

    let rawDebuffGroups = (tabs.debuffs && Array.isArray(tabs.debuffs.groups)) ? tabs.debuffs.groups : (charData.debuffs || []);
    rawDebuffGroups.forEach((group: any) => {
        const groupTags = getTags(group);
        const rawItems = group.items || group.abilities || [];
