            };
            result.flat_passives.push(hydrated);
            return hydrated;
        });
        result.passives.push({ group_name: group.group_name || group.name || "Debuffs", is_flaw_group: true, items });
    });

    const trauma = calculateTraumaPenalty(result.medcard.injuries);
    result.battle_stats = {
