export async function createBattle(name: string) {
  const { data, error } = await supabase.from('battles').insert([{ name, participants_snapshot: [], sequence_log: [], casualties: [], round: 1, status: 'startup' }]).select().single();
  return { data, error };
}

export async function updateBattle(battleId: string, updates: any) {
  const { data, error } = await supabase.from('battles').update(updates).eq('id', battleId);
  return { data, error };
}

export async function deleteBattle(battleId: string) {
    const { error } = await supabase.from('battles').delete().eq('id', battleId);
    return { error };
}

export async function updateCharacter(charId: string, updates: any) {
    const { data: currentRows, error: fetchError } = await supabase.from('characters').select('data').eq('id', charId).single();
    if (fetchError || !currentRows) return { error: fetchError };
    const mergedData = { ...(currentRows.data || {}), ...updates };
    const { error } = await supabase.from('characters').update({ data: mergedData }).eq('id', charId);
    return { error };
}

