/**
 * Fetches all tables and triggers a JSON file download in the browser.
 */
export const exportFullBackup = async () => {
    try {
        const [chars, trigs, injuries, timeUnits, actions, tags, training] = await Promise.all([
            supabase.from('characters').select('*'),
            supabase.from('triggers').select('*'),
            supabase.from('injuries').select('*'),
            supabase.from('time_units').select('*'),
            supabase.from('basic_actions').select('*'),
            supabase.from('battle_tags').select('*'),
            supabase.from('training').select('*')
        ]);

        const backupData = {
            characters: chars.data || [],
            triggers: trigs.data || [],
            injuries: injuries.data || [],
            time_units: timeUnits.data || [],
            basic_actions: actions.data || [],
            battle_tags: tags.data || [],
            training: training.data || [],
            exported_at: new Date().toISOString()
        };

        const blob = new Blob([JSON.stringify(backupData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `juul_d_backup_${new Date().toISOString().split('T')[0]}.json`;
        a.click();
        URL.revokeObjectURL(url);
    } catch (e: any) {
        throw new Error("Failed to export: " + e.message);
    }
};

/**
 * Parses a JSON backup file and upserts the data into respective tables.
 */
export const importFullBackup = async (file: File): Promise<{ success: boolean; message: string }> => {
    try {
        const text = await file.text();
        const data = JSON.parse(text);

        if (data.characters && data.characters.length > 0) await supabase.from('characters').upsert(data.characters);
        if (data.triggers && data.triggers.length > 0) await supabase.from('triggers').upsert(data.triggers);
        if (data.injuries && data.injuries.length > 0) await supabase.from('injuries').upsert(data.injuries);
        if (data.time_units && data.time_units.length > 0) await supabase.from('time_units').upsert(data.time_units);
        if (data.basic_actions && data.basic_actions.length > 0) await supabase.from('basic_actions').upsert(data.basic_actions);
        if (data.battle_tags && data.battle_tags.length > 0) await supabase.from('battle_tags').upsert(data.battle_tags);
        if (data.training && data.training.length > 0) await supabase.from('training').upsert(data.training);

        // Clear local cache to ensure fresh data
        CacheService.clearAll();

        return { success: true, message: "Импорт завершен успешно. Кеш очищен." };
    } catch (e: any) {
        return { success: false, message: e.message };
    }
};

/**
 * Scans storage bucket and removes files not referenced in any database table.
 */
export const cleanUnusedStorage = async (): Promise<number> => {
    try {
        // 1. Get all file names in bucket
        const { data: files, error: listError } = await supabase.storage.from('Juul-D-Tracker').list();
        if (listError) throw listError;
        if (!files || files.length === 0) return 0;

        // 2. Get all referenced URLs from DB
        const [{ data: chars }, { data: maps }, { data: locs }] = await Promise.all([
            supabase.from('characters').select('data'),
            supabase.from('maps').select('image_url'),
            supabase.from('locations').select('img')
        ]);

        const usedUrls = new Set<string>();
        chars?.forEach((c: any) => {
            if (c.data?.meta?.avatar_url) usedUrls.add(c.data.meta.avatar_url);
        });
        maps?.forEach((m: any) => usedUrls.add(m.image_url));
        locs?.forEach((l: any) => usedUrls.add(l.img));

        // 3. Find files not in referenced URLs set
        const filesToDelete: string[] = [];
        files.forEach(file => {
            const publicUrl = supabase.storage.from('Juul-D-Tracker').getPublicUrl(file.name).data.publicUrl;
            if (!usedUrls.has(publicUrl)) {
                filesToDelete.push(file.name);
            }
        });

        // 4. Perform deletion
        if (filesToDelete.length > 0) {
            const { error: delError } = await supabase.storage.from('Juul-D-Tracker').remove(filesToDelete);
            if (delError) throw delError;
        }

        return filesToDelete.length;
    } catch (e: any) {
        throw new Error("Cleanup failed: " + e.message);
    }
};

import { CharacterTemplate, JsonAbility, JsonItem, JsonPassiveItem, JsonInjury } from '../types';
import { TRAUMA_DEFINITIONS } from '../constants';
import { supabase } from '../../../lib/supabase';

export { supabase };

// Helper to generate IDs for items inside JSON that might lack them
const generateId = () => Math.random().toString(36).substr(2, 9);

// Helper: robustly extract tags from an object whether it uses 'tags' (array) or 'tag' (string)
const getTags = (obj: any): string[] => {
    if (!obj) return [];
    let collected: string[] = [];

    if (Array.isArray(obj.tags)) {
        collected = [...obj.tags];
    } else if (typeof obj.tags === 'string') {
        collected.push(obj.tags);
    }

    if (typeof obj.tag === 'string') {
        collected.push(obj.tag);
    }

    // Clean and lowercase
    return collected.map(t => t.toLowerCase().trim()).filter(Boolean);
};

// Helper: Calculate total trauma penalty based on definitions
export const calculateTraumaPenalty = (injuries: JsonInjury[] = []) => {
  let totals = { phys: 0, mag: 0, uniq: 0, total: 0 };
  const injuryCounts: Record<string, number> = {};

  injuries.forEach(injury => {
      const current = injuryCounts[injury.template_id] || 0;
      injuryCounts[injury.template_id] = current + (injury.count || 1);
  });

  for (const [templateId, count] of Object.entries(injuryCounts)) {
      const def = TRAUMA_DEFINITIONS[templateId];
      if (!def) continue;

      let penalty = 0;
      if (def.stack && def.stack > 0) {
          const stacks = Math.floor(count / def.stack);
          penalty = stacks * def.value;
      } else {
          penalty = count * def.value;
      }

      totals.total += penalty;
      if (templateId.includes('phys')) totals.phys += penalty;
      else if (templateId.includes('mag')) totals.mag += penalty;
      else if (templateId.includes('uniq')) totals.uniq += penalty;
  }
  return totals;
};

// Normalization Helpers
const normalizeBonuses = (items: any[]) => {
  if (!Array.isArray(items)) return [];
  return items.map(item => ({
    ...item,
    bonuses: (item.bonuses || []).map((b: any) => ({
      stat: (b.stat || 'phys').toLowerCase().trim(),
      val: b.val !== undefined ? b.val : (b.value !== undefined ? b.value : 0)
    }))
  }));
};

const normalizeItems = (items: any[]) => {
    if (!Array.isArray(items)) return [];
    const normalized = normalizeBonuses(items);
    return normalized.map((item: any) => ({
        ...item,
        desc_lore: item.desc_lore !== undefined ? item.desc_lore : (item.desc?.lore || ''),
        desc_mech: item.desc_mech !== undefined ? item.desc_mech : (item.desc?.mech || '')
    }));
};

const normalizeAbilities = (abilities: any[]) => {
  if (!Array.isArray(abilities)) return [];
  const normalizedItems = normalizeItems(abilities);
  return normalizedItems.map((ab: any) => ({
    ...ab,
    limit: ab.limit !== undefined ? ab.limit : (ab.limits?.value || 0),
    limit_unit: ab.limit_unit !== undefined ? ab.limit_unit : (ab.limits?.unit || ''),
    cd: ab.cd !== undefined ? ab.cd : (ab.cooldown?.value || 0),
    cd_unit: ab.cd_unit !== undefined ? ab.cd_unit : (ab.cooldown?.unit || ''),
    dur: ab.dur !== undefined ? ab.dur : (ab.duration?.value || 0),
    dur_unit: ab.dur_unit !== undefined ? ab.dur_unit : (ab.duration?.unit || '')
  }));
};

const normalizeTrigger = (trigger: string): string => {
    if (!trigger) return 'ALWAYS';
    const t = trigger.toUpperCase().trim();
    if (t.includes('START') || t.includes('НАЧАЛО')) return 'COMBAT_START';
    if (t.includes('HIT') || t.includes('ПОПАДАН') || t.includes('УДАР')) return 'ON_HIT';
    if (t.includes('KILL') || t.includes('УБИЙСТВ')) return 'ON_KILL';
    if (t.includes('DEFENSE') || t.includes('ЗАЩИТ')) return 'ON_DEFENSE';
    if (t.includes('ABILITY') || t.includes('СПОСОБН')) return 'ABILITY';
    if (t.includes('ALWAYS') || t.includes('ВСЕГДА') || t.includes('ПАССИВ')) return 'ALWAYS';
    return t;
}

export async function getCharacters() {
  console.log('Fetching characters and basic actions...');

  const [charRes, basicRes] = await Promise.all([
      supabase.from('characters').select('*'),
      supabase.from('basic_actions').select('*')
  ]);

  if (charRes.error) {
    console.error('Supabase: Error fetching characters:', charRes.error);
    return { data: [], error: charRes.error };
  }

  const globalBasicActions: JsonAbility[] = (basicRes.data || []).map(a => ({
      ...a,
      _id: `global_${a.id || generateId()}`,
      tags: getTags(a)
  }));

  const formattedData = charRes.data.map((row: any) => {
    let charData = row.data || row;
    if (row.data && typeof row.data === 'object') {
       charData = { ...row.data, id: row.id };
    }

    const result: any = {
        id: charData.id || generateId(),
        meta: charData.meta || { uid: 'system', avatar_url: '' },
        profile: charData.profile || charData.identity || { name: 'Unknown', level: 1, faction: 'None', npc_volume: '' },
        stats: charData.stats || { phys: 0, magic: 0, unique: 0 },
        resources: charData.resources || [],
        equipment: { usable: [], wearable: [], inventory: [] },
        ability_groups: [],
        passives: [],
        medcard: charData.medcard || charData.med_card || { injuries: [], conditions: [] },
        flat_abilities: [],
        flat_passives: []
    };

    const tabs = charData.tabs || {};
    let rawWearable = tabs.equipment?.wearable || charData.equipment?.wearable;
    result.equipment.wearable = normalizeItems(rawWearable).map((i: any) => ({...i, _id: generateId(), tags: getTags(i)}));
    let rawUsable = tabs.equipment?.weapons || tabs.equipment?.usable || charData.equipment?.weapons || charData.equipment?.usable;
    result.equipment.usable = normalizeItems(rawUsable).map((i: any) => ({...i, _id: generateId(), tags: getTags(i)}));
    let rawInventory = tabs.equipment?.backpack || tabs.equipment?.inventory || charData.equipment?.backpack || charData.equipment?.inventory;
    result.equipment.inventory = normalizeItems(rawInventory).map((i: any) => ({...i, _id: generateId(), tags: getTags(i)}));

    // Inject Global Basic Actions
    if (globalBasicActions.length > 0) {
        const basicGroup = {
            name: "Базовые Действия",
            tags: [],
            abilities: globalBasicActions,
            is_hidden: false // Visible by default
        };
        result.ability_groups.push(basicGroup);
        globalBasicActions.forEach(a => result.flat_abilities.push(a));
    }

    let rawAbilityGroups = [];
    if (tabs.abilities && Array.isArray(tabs.abilities.schools)) {
        rawAbilityGroups = tabs.abilities.schools;
    } else if (Array.isArray(charData.ability_groups)) {
        rawAbilityGroups = charData.ability_groups;
    }

    if (rawAbilityGroups.length > 0) {
        rawAbilityGroups.forEach((group: any) => {
            if (group.name === "Базовые Действия") return; // Skip if already manually there to avoid duplicates
            const groupTags = getTags(group);
            const abilities = normalizeAbilities(group.abilities).map((ab: any) => {
                const abTags = [...new Set([...groupTags, ...getTags(ab)])];
                const hydrated = { ...ab, _id: generateId(), tags: abTags };
                if (!abTags.includes('no_war')) {
                    result.flat_abilities.push(hydrated);
                }
                return hydrated;
            });
            result.ability_groups.push({ ...group, abilities });
        });
    }

    // Passives Logic
    let rawPassiveGroups = (tabs.passives && Array.isArray(tabs.passives.groups)) ? tabs.passives.groups : (charData.passives || []);
    rawPassiveGroups.forEach((group: any) => {
        const groupTags = getTags(group);
        const rawItems = group.items || group.abilities || [];
        const items = normalizeItems(rawItems).map((p: any) => {
            const pTags = [...new Set([...groupTags, ...getTags(p)])];
            const hydrated = {
                ...p,
                _id: generateId(),
                tags: pTags,
                trigger: normalizeTrigger(p.trigger),
                is_flaw: !!group.is_flaw_group,
                dur: p.dur || 0,
                dur_unit: p.dur_unit || 'turn'
            };
            result.flat_passives.push(hydrated);
            return hydrated;
        });
        result.passives.push({
            group_name: group.group_name || group.name || (group.is_flaw_group ? "Debuffs" : "Passives"),
            is_flaw_group: !!group.is_flaw_group,
            items
        });
    });

    let rawDebuffGroups = (tabs.debuffs && Array.isArray(tabs.debuffs.groups)) ? tabs.debuffs.groups : (charData.debuffs || []);
    rawDebuffGroups.forEach((group: any) => {
        const groupTags = getTags(group);
        const rawItems = group.items || group.abilities || [];
        const items = normalizeItems(rawItems).map((p: any) => {
            const pTags = [...new Set([...groupTags, ...getTags(p)])];
            const hydrated = {
                ...p,
                _id: generateId(),
                tags: pTags,
                trigger: normalizeTrigger(p.trigger),
                is_flaw: true,
                dur: p.dur || 0,
                dur_unit: p.dur_unit || 'turn'
            };
            result.flat_passives.push(hydrated);
            return hydrated;
        });
        result.passives.push({ group_name: group.group_name || group.name || "Debuffs", is_flaw_group: true, items });
    });

    const trauma = calculateTraumaPenalty(result.medcard.injuries);
    result.battle_stats = {
        hp_penalty_current: trauma.total,
        trauma_phys: trauma.phys, trauma_mag: trauma.mag, trauma_uniq: trauma.uniq,
        actions_max: 4, actions_left: 4
    };
    return result;
  });

  return { data: formattedData as CharacterTemplate[], error: null };
}

export async function getBattles() {
  const { data, error } = await supabase.from('battles').select('*');
  return { data, error };
}

export async function createBattle(name: string) {
  const { data, error } = await supabase.from('battles').insert([{ name, participants_snapshot: [], sequence_log: [], casualties: [], round: 1, status: 'startup' }]).select().single();
  return { data, error };
}

export async function updateBattle(battleId: string, updates: any) {
  const { data, error } = await supabase.from('battles').update(updates).eq('id', battleId);
  return { data, error };
}

export async function deleteBattle(battleId: string) {
    const { error } = await supabase.from('battles').delete().eq('id', battleId);
    return { error };
}

export async function updateCharacter(charId: string, updates: any) {
    const { data: currentRows, error: fetchError } = await supabase.from('characters').select('data').eq('id', charId).single();
    if (fetchError || !currentRows) return { error: fetchError };
    const mergedData = { ...(currentRows.data || {}), ...updates };
    const { error } = await supabase.from('characters').update({ data: mergedData }).eq('id', charId);
    return { error };
}

import React, { useState, useMemo } from 'react';
import { CharacterData, TimeUnit, StatType, Bonus, Ability } from '../types';
import { Card, StyledInput, StyledTextarea, Button, BonusInput, TagInput, TimeInput, TabRadarCharts, CommonTagToggles } from './Shared';
import { Plus, Trash2, Clock, Hourglass, ChevronDown, ChevronRight, Eye, EyeOff, Hash, Check, X, Lock, Unlock, Sparkles } from 'lucide-react';
import { DisplayMode } from '../App';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  character: CharacterData;
  isEditMode: boolean;
  displayMode: DisplayMode;
  onChange: (groups: CharacterData['ability_groups']) => void;
  timeUnits: TimeUnit[];
}

const TabAbilities: React.FC<Props> = ({ character, isEditMode, displayMode, onChange, timeUnits }) => {
  const { ability_groups } = character;
  const [collapsedGroups, setCollapsedGroups] = useState<Record<number, boolean>>({});
  const [deleteConfirmGroupIdx, setDeleteConfirmGroupIdx] = useState<number | null>(null);
  /* [DIALECT] */ const { t } = useDialect();

  const toggleGroup = (idx: number) => {
    setCollapsedGroups(prev => ({ ...prev, [idx]: !prev[idx] }));
  };

  const updateGroup = (idx: number, field: string, val: any) => {
    const next = [...ability_groups];
    next[idx] = { ...next[idx], [field]: val };
    onChange(next);
  };

  const addGroup = () => onChange([...ability_groups, { name: "Новая Школа", tags: [], abilities: [], is_hidden: false }]);

  const removeGroup = (idx: number) => {
     const next = ability_groups.filter((_, i) => i !== idx);
     onChange(next);

     const newCollapsed = { ...collapsedGroups };
     delete newCollapsed[idx];
     setCollapsedGroups(newCollapsed);
     setDeleteConfirmGroupIdx(null);
  };

  const addAbility = (gIdx: number) => {
    const next = [...ability_groups];
    const group = { ...next[gIdx] };
    group.abilities = [...(group.abilities || [])];

    group.abilities.push({ 
      name: "Новый Навык", bonuses: [], tags: [], desc_lore: "", desc_mech: "",
      cd: 0, cd_unit: "", dur: 0, dur_unit: "", limit: 0, limit_unit: "", is_blocked: false
    });

    next[gIdx] = group;
    onChange(next);
  };

  const updateAbility = (gIdx: number, aIdx: number, field: string, val: any) => {
    const next = [...ability_groups];
    const group = { ...next[gIdx] };
    group.abilities = [...group.abilities];
    group.abilities[aIdx] = { ...group.abilities[aIdx], [field]: val };
    next[gIdx] = group;
    onChange(next);
  };

  const removeAbility = (gIdx: number, aIdx: number) => {
    const next = [...ability_groups];
    const group = { ...next[gIdx] };
    group.abilities = [...group.abilities];
    group.abilities.splice(aIdx, 1);
    next[gIdx] = group;
    onChange(next);
  };

  const shouldShowLore = displayMode === 'lore';
  const shouldShowMech = displayMode === 'mech';

  const structureData = useMemo(() => {
      if (isEditMode) return [];
      const data = ability_groups.map((g, i) => {
        const name = g.name || "Unknown";
        let baseName = name.length > 10 ? name.substring(0, 8) + '..' : name;
        return { subject: baseName + '\u200B'.repeat(i), value: g.abilities ? g.abilities.length : 0 };
      });
      while (data.length < 3) data.push({ subject: '\u200B'.repeat(100 + data.length), value: 0 });
      return data;
  }, [ability_groups, isEditMode]);

  const bonusData = useMemo(() => {
      if (isEditMode) return [];
      let phys = 0, magic = 0, unique = 0;
      ability_groups.forEach(g => {
        if (Array.isArray(g.abilities)) {
          g.abilities.forEach(item => {
            if (Array.isArray(item.bonuses)) {
              item.bonuses.forEach(b => {
                 const val = Number(b.val);
                 if (!Number.isNaN(val)) {
                    if (b.stat === StatType.PHYS) phys += val;
                    if (b.stat === StatType.MAGIC) magic += val;
                    if (b.stat === StatType.UNIQUE) unique += val;
                 }
              });
            }
          });
        }
      });
      const getValue = (v: number) => Math.max(0, v); 
      return [
        { subject: t('stat_phys_short', 'ФИЗ'), value: getValue(phys) },
        { subject: t('stat_mag_short', 'МАГ'), value: getValue(magic) },
        { subject: t('stat_uni_short', 'УНИК'), value: getValue(unique) },
      ];
  }, [ability_groups, t, isEditMode]);

  return (
    <div className="space-y-8 animate-fade-in">
      {!isEditMode && <TabRadarCharts structureData={structureData} bonusData={bonusData} color="#06b6d4" t={t} />}

      {ability_groups.map((group, gIdx) => {
        const isBasic = group.name === "Базовые Действия";
        if (!isEditMode && (group.abilities.length === 0 || group.is_hidden)) return null;

        const isCollapsed = collapsedGroups[gIdx];
        const isHidden = group.is_hidden;
        const abilitiesWithIndex = group.abilities.map((ab, i) => ({ ...ab, originalIndex: i }));
        const sortedAbilities = abilitiesWithIndex.sort((a, b) => {
            if (a.is_blocked === b.is_blocked) return 0;
            return a.is_blocked ? 1 : -1;
        });

        return (
          <div key={gIdx} className={`space-y-4 transition-all ${isBasic ? 'border-l-4 border-emerald-500' : ''} ${isHidden && isEditMode ? 'opacity-70 border-2 border-dashed border-gray-800 p-4 rounded-xl bg-gray-900/20' : ''}`}>
             <div className={`flex items-center gap-4 border-b border-gray-800 pb-2 ${isBasic ? 'bg-emerald-950/20' : 'bg-slate-900/90'} p-3 rounded-t-lg backdrop-blur-sm shadow-md`}>
               <button onClick={() => toggleGroup(gIdx)} className={`p-1 transition-colors ${isBasic ? 'text-emerald-400 hover:text-emerald-300' : 'text-gray-500 hover:text-cyan-400'}`}>
                  {isCollapsed ? <ChevronRight size={24}/> : <ChevronDown size={24} />}
               </button>
               <div className="flex-1 flex items-center gap-2">
                 {isBasic && <Sparkles size={18} className="text-emerald-500 shrink-0" />}
                 <StyledInput 
                   isEditMode={isEditMode && !isBasic} 
                   value={group.name} 
                   onChange={e => updateGroup(gIdx, 'name', e.target.value)} 
                   className={`text-xl font-bold uppercase tracking-widest bg-transparent border-none p-0 ${isBasic ? 'text-emerald-500' : 'text-cyan-500'}`} 
                 />
                 {isBasic && isEditMode && <span className="text-[9px] uppercase font-bold text-emerald-900 bg-emerald-500/20 px-2 py-0.5 rounded">Система</span>}
                 {isHidden && isEditMode && <span className="text-[10px] uppercase font-bold text-gray-500 block -mt-1">{t('lbl_hidden_group', "Скрытая группа")}</span>}
               </div>

               {!isCollapsed && <TagInput isEditMode={isEditMode && !isBasic} tags={group.tags || []} onChange={t => updateGroup(gIdx, 'tags', t)} />}

               {isEditMode && !isBasic && (
                 <>
                   <button 
                     onClick={() => updateGroup(gIdx, 'is_hidden', !isHidden)} 
                     className={`p-1.5 rounded transition-colors ${isHidden ? 'bg-gray-800 text-gray-400 hover:text-white' : 'text-cyan-600 hover:text-cyan-400'}`}
                     title={isHidden ? "Показать в листе" : "Скрыть из листа"}
                   >
                     {isHidden ? <EyeOff size={16}/> : <Eye size={16}/>}
                   </button>

                   {deleteConfirmGroupIdx === gIdx ? (
                     <div className="flex items-center gap-1">
                        <Button size="sm" variant="danger" onClick={() => removeGroup(gIdx)}><Check size={14} /></Button>
                        <Button size="sm" variant="secondary" onClick={() => setDeleteConfirmGroupIdx(null)}><X size={14} /></Button>
                     </div>
                   ) : (
                     <Button size="sm" variant="danger" onClick={() => setDeleteConfirmGroupIdx(gIdx)}><Trash2 size={14}/></Button>
                   )}
                 </>
               )}
             </div>

             {!isCollapsed && (
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-in">
                 {sortedAbilities.map((abilityWrapper) => {
                   const { originalIndex, ...ability } = abilityWrapper;
                   const isBlocked = ability.is_blocked;

                   return (
                   <Card key={originalIndex} className={`hover:border-gray-700 transition-colors bg-[#0b0d10] border-gray-800 ${isBlocked ? 'opacity-60 grayscale-[0.8] hover:opacity-100 hover:grayscale-0' : ''} ${isBasic ? 'border-l-2 border-emerald-900/50' : ''}`}>
                      <div className="flex justify-between items-start mb-2 overflow-hidden">
                         <div className="flex-1 min-w-0 mr-2" title={ability.name}>
                           <StyledInput 
                              isEditMode={isEditMode && !isBlocked && !isBasic} 
                              disabled={isBlocked || isBasic}
                              value={ability.name} 
                              onChange={e => updateAbility(gIdx, originalIndex, 'name', e.target.value)} 
                              className={`font-bold text-lg truncate block w-full ${isBlocked ? 'text-slate-500' : (isBasic ? 'text-emerald-300' : '')}`} 
                              placeholder={t('ph_ability_name', "Название навыка")}
                           />
                         </div>
                         {isEditMode && !isBasic && (
                             <div className="flex items-center gap-1 flex-shrink-0">
                                <button 
                                    onClick={() => updateAbility(gIdx, originalIndex, 'is_blocked', !isBlocked)}
                                    className={`p-1 rounded transition-colors ${isBlocked ? 'text-amber-500 bg-amber-900/20' : 'text-slate-600 hover:text-amber-400'}`}
                                    title={isBlocked ? "Разблокировать" : "Заблокировать (Архивировать)"}
                                >
                                    {isBlocked ? <Lock size={14} /> : <Unlock size={14} />}
                                </button>
                                {!isBlocked && (
                                    <button onClick={() => removeAbility(gIdx, originalIndex)} className="text-red-900 hover:text-red-500 transition-colors">
                                        <Trash2 size={14}/>
                                    </button>
                                )}
                             </div>
                         )}
                      </div>

                      {(shouldShowMech || isEditMode) && (
                        <div className={`flex flex-wrap gap-2 mb-2 ${isBlocked ? 'pointer-events-none' : ''}`}>
                          <BonusInput isEditMode={isEditMode && !isBlocked && !isBasic} bonuses={ability.bonuses} onChange={b => updateAbility(gIdx, originalIndex, 'bonuses', b)} />
                          <TimeInput 
                            icon={Clock} label="КД" isEditMode={isEditMode && !isBlocked && !isBasic} 
                            val={ability.cd} unit={ability.cd_unit} 
                            onChangeVal={v => updateAbility(gIdx, originalIndex, 'cd', v)} 
                            onChangeUnit={u => updateAbility(gIdx, originalIndex, 'cd_unit', u)} 
                            options={timeUnits}
                          />
                          <TimeInput 
                            icon={Hourglass} label="Длит." isEditMode={isEditMode && !isBlocked && !isBasic} 
                            val={ability.dur} unit={ability.dur_unit} 
                            onChangeVal={v => updateAbility(gIdx, originalIndex, 'dur', v)} 
                            onChangeUnit={u => updateAbility(gIdx, originalIndex, 'dur_unit', u)} 
                            options={timeUnits}
                          />
                          <TimeInput 
                            icon={Hash} label="Лимит" isEditMode={isEditMode && !isBlocked && !isBasic} 
                            val={ability.limit || 0} unit={ability.limit_unit || ""} 
                            onChangeVal={v => updateAbility(gIdx, originalIndex, 'limit', v)} 
                            onChangeUnit={u => updateAbility(gIdx, originalIndex, 'limit_unit', u)} 
                            options={timeUnits}
                          />
                        </div>
                      )}

                      <div className={`mb-3 ${isBlocked ? 'pointer-events-none' : ''}`}>
                         <TagInput isEditMode={isEditMode && !isBlocked && !isBasic} tags={ability.tags || []} onChange={t => updateAbility(gIdx, originalIndex, 'tags', t)} />
                         {isEditMode && !isBlocked && !isBasic && <CommonTagToggles tags={ability.tags || []} onChange={t => updateAbility(gIdx, originalIndex, 'tags', t)} />}
                      </div>

                      {(shouldShowLore || isEditMode) && (
                        <StyledTextarea 
                          isEditMode={isEditMode && !isBlocked && !isBasic} 
                          disabled={isBlocked || isBasic}
                          value={ability.desc_lore} 
                          onChange={e => updateAbility(gIdx, originalIndex, 'desc_lore', e.target.value)} 
                          className="text-sm text-gray-400 italic mb-2" 
                          placeholder={t('ph_ability_lore', "Худ. описание")}
                        />
                      )}

                      {(shouldShowMech || isEditMode) && (isEditMode || ability.desc_mech) && (
                        <div className={`pt-2 ${!isEditMode && shouldShowLore ? 'border-t border-gray-800' : ''}`}>
                          <StyledTextarea 
                            isEditMode={isEditMode && !isBlocked && !isBasic} 
                            disabled={isBlocked || isBasic}
                            value={ability.desc_mech} 
                            onChange={e => updateAbility(gIdx, originalIndex, 'desc_mech', e.target.value)} 
                            className={`text-xs font-mono leading-relaxed ${isEditMode ? 'text-green-400' : (isBasic ? 'text-emerald-500/70' : 'text-green-500/80')} ${isBlocked ? 'text-slate-500' : ''}`} 
                            placeholder={t('ph_ability_mech', "Механика")} 
                          />
                        </div>
                      )}
                   </Card>
                 )})}

                 {isEditMode && !isBasic && (
                   <button onClick={() => addAbility(gIdx)} className="border-2 border-dashed border-gray-800 rounded-lg flex items-center justify-center text-gray-700 hover:text-cyan-500 hover:border-cyan-900 transition-all min-h-[150px] bg-slate-900/50 backdrop-blur-sm">
                     <Plus size={24} />
                   </button>
                 )}
               </div>
             )}
          </div>
        );
      })}

      {isEditMode && <Button onClick={addGroup} className="w-full py-4 border-dashed border-2 bg-slate-900/50 backdrop-blur-sm border-gray-800 text-gray-600 hover:text-white hover:border-gray-600">
         {t('btn_add_school', "Создать новую школу")}
      </Button>}
