                  if (childExists) return { ...node, children: [...node.children, newSibling] };
              }
              if (node.children.length > 0) return { ...node, children: recursiveAdd(node.children) };
              return node;
          });
      };
      setTree(prev => recursiveAdd(prev));
  };

  const updateLog = (newLogs: LogEntry[]) => {
      setLogs(newLogs);
  };

