  }

  /* Performance: GPU Acceleration & Paint Containment */
  .gpu-accelerated {
    transform: translateZ(0);
    backface-visibility: hidden;
    perspective: 1000px;
  }

  /* Browser-native list virtualization */
  .content-visibility-auto {
    content-visibility: auto;
    contain-intrinsic-size: 1px 500px; /* Est. card height */
