                                    <h3 className={`font-fantasy font-bold text-lg leading-tight truncate ${theme.text} group-hover:text-white transition-colors`}>
                                        {char.profile.name}
                                    </h3>

                                    {/* Subtext: Save Status */}
                                    <div className="flex items-center gap-2 mt-1">
                                        {char.profile.faction === Faction.GRAVEYARD ? (
                                            <span className="text-[10px] text-slate-500 uppercase tracking-wide flex items-center gap-1">
                                                <Skull size={10} /> {char.meta.save_status_reason || t('meta_death_unknown', "Почил")}
                                            </span>
                                        ) : char.meta.save_status ? (
                                            <span className={`text-[10px] uppercase tracking-wide flex items-center gap-1 ${isBloodMode ? 'text-red-400' : 'text-emerald-500/80'}`}>
                                                <ShieldCheck size={10} /> {t('meta_save_ok', 'Сейв есть')}
                                            </span>
                                        ) : (
                                            <span className="text-[10px] text-red-500/80 uppercase tracking-wide flex items-center gap-1">
                                                <Skull size={10} /> {t('meta_save_lost', 'Без сейва')}
                                            </span>
                                        )}
                                    </div>
                                </div>
                            </div>

                            {/* Master Link */}
                            {char.meta.master_id && char.profile.faction === Faction.NPC && (
                                <div className="text-[10px] bg-white/5 rounded px-2 py-1 text-violet-300 border border-violet-500/20 flex items-center gap-2">
                                    <LinkIcon size={10} /> 
                                    <span>{t('lbl_linked', 'Связан узами')}</span>
                                </div>
                            )}

                            {/* Stats Grid - Minimalist */}
                            <div className="grid grid-cols-3 gap-1 mt-auto pt-2 border-t border-white/5">
                                <div className="flex flex-col items-center p-1 bg-black/20 rounded">
                                    <Sword size={10} className="text-red-400 mb-0.5" />
                                    <span className="text-xs font-mono font-bold text-slate-300">{char.stats.phys}</span>
                                </div>
                                <div className="flex flex-col items-center p-1 bg-black/20 rounded">
                                    <Wand2 size={10} className="text-blue-400 mb-0.5" />
                                    <span className="text-xs font-mono font-bold text-slate-300">{char.stats.magic}</span>
                                </div>
                                <div className="flex flex-col items-center p-1 bg-black/20 rounded">
                                    <Crown size={10} className="text-purple-400 mb-0.5" />
                                    <span className="text-xs font-mono font-bold text-slate-300">{char.stats.unique}</span>
                                </div>
                            </div>

                            {/* Equipment Line */}
                            <div className="text-[9px] text-slate-500 truncate h-4">
                                {char.equipment.wearable.filter(w => w.is_equipped).map(w => w.name).join(", ") || ""}
                            </div>
                        </div>
                    </div>
                ))}

                {filtered.length === 0 && (
                    <div className="col-span-full flex flex-col items-center justify-center py-20 text-slate-600 border-2 border-dashed border-slate-800 rounded-xl bg-slate-900/20">
                        <Ghost size={48} className="mb-4 opacity-20"/>
                        <span className="text-sm font-bold uppercase tracking-widest font-serif">{t('msg_empty', 'Лишь ветер гуляет')}</span>
                    </div>
                )}
                </div>
            </div>
      </div>

      {/* [DIALECT] Easter Egg Input Window */}
      {isInputMode && (
          <div className="fixed inset-0 md:absolute md:inset-auto md:bottom-4 md:left-1/2 md:-translate-x-1/2 md:bottom-8 z-[100] animate-fadeIn flex items-center justify-center pointer-events-none p-4">
              <div className="bg-black/95 border border-violet-900 rounded-lg p-4 shadow-[0_0_40px_rgba(139,92,246,0.4)] backdrop-blur-md pointer-events-auto w-full max-w-sm relative">
                <div className="flex items-center gap-2 mb-2 justify-between">
                  <div className="flex items-center gap-2">
                      <Terminal size={14} className="text-violet-500 animate-pulse"/>
                      <span className="text-[10px] font-mono text-violet-300 uppercase tracking-widest">Input Sequence</span>
                  </div>
                </div>
                <div className="bg-slate-950 border border-slate-800 rounded p-3 min-h-[3rem] flex items-center justify-center overflow-hidden">
                    <span className="font-serif text-sm md:text-base text-violet-400 tracking-[0.1em] md:tracking-[0.2em] uppercase drop-shadow-[0_0_5px_rgba(167,139,250,0.8)] break-all text-center">
                      {inputBuffer || <span className="opacity-20">_ _ _ _ _ _</span>}
                    </span>
                </div>
                <div className="text-center mt-2">
                    <span className="text-[9px] text-slate-600 uppercase font-bold tracking-widest">Tap title letters & slashes</span>
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Roster;

import { BattleParticipant } from '../types';
import { formatCooldown, formatDuration, STATUS_PHRASES, PERMANENT_EFFECT_PHRASES } from '../constants';

// Helper to reliably pick a phrase based on inputs
const getStatusPhrase = (phrases: string[], seed: number) => {
    if (!phrases || phrases.length === 0) return "Неизвестно";
    return phrases[seed % phrases.length];
};

// Sort helper: Group by Template ID, then by Name
const sortParticipants = (participants: BattleParticipant[]) => {
    return [...participants].sort((a, b) => {
        // Primary Sort: Group by ID (Template)
        if (a.id !== b.id) {
            return a.id.localeCompare(b.id);
        }
        // Secondary Sort: Name (Natural Order: Rat #1, Rat #2, etc.)
        return a.profile.name.localeCompare(b.profile.name, undefined, { numeric: true, sensitivity: 'base' });
    });
};

// Helper to check if something is non-combat
const isNonCombat = (tags: string[] = []) => {
    const t = tags.map(tag => tag.toLowerCase().trim());
    return t.includes('no_war') || t.includes('небоевое');
};

export const generateSummary = (participants: BattleParticipant[], round: number): string => {
    let text = "";

    // Sort for grouping
    const sortedParticipants = sortParticipants(participants);

    // 1. Status Section
    sortedParticipants.forEach(p => {
        const { trauma_phys = 0, trauma_mag = 0, trauma_uniq = 0 } = p.battle_stats;
        let phrase = "";

        const charSeed = p.instance_id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
        const seed = Math.abs(charSeed + trauma_phys + round);

        if (trauma_phys === 0) {
            phrase = getStatusPhrase(STATUS_PHRASES.level_0, seed);
        } else {
            const positiveTrauma = Math.abs(trauma_phys);
            const level = Math.ceil(positiveTrauma / 5) * 5;
            const lookupKey = level > 60 ? 'level_60' : `level_${level}`;
            const phraseSet = STATUS_PHRASES[lookupKey] || STATUS_PHRASES.level_60;
            phrase = getStatusPhrase(phraseSet, seed);
        }

        const parts: string[] = [];
        if (trauma_phys !== 0) parts.push(`Физ: ${trauma_phys}`);
        if (trauma_mag !== 0) parts.push(`Маг: ${trauma_mag}`);
        if (trauma_uniq !== 0) parts.push(`Уник: ${trauma_uniq}`);

        const injuriesText = parts.length > 0 ? `(${parts.join(', ')})` : "";
        text += `${p.profile.name} — ${phrase} ${injuriesText}\n\n`;
    });

    // 2. Split Effects
    const forms: string[] = [];
    const buffs: string[] = [];
    const debuffs: string[] = [];

    sortedParticipants.forEach(p => {
        p.active_effects.forEach(eff => {
             // Filter out non-combat effects
             if (isNonCombat(eff.tags)) return;

             const isForm = (eff.tags || []).some(t => t.toLowerCase().includes('form') || t.toLowerCase().includes('форма'));
             const isNegative = eff.bonuses.some(b => b.val < 0);

             // Logic for permanent/long durations
             let durationStr = formatDuration(eff.duration_left, eff.unit);
             const u = eff.unit?.toLowerCase() || '';

             // If duration is extremely high (> 50 rounds) OR unit is explicitly 'battle' or 'day'
             if (eff.duration_left > 50 || ['battle', 'бой', 'day', 'сутки'].includes(u)) {
                 const effectSeed = eff.id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0) + round;
                 durationStr = getStatusPhrase(PERMANENT_EFFECT_PHRASES, effectSeed);
             }

             const line = `${eff.name} (${p.profile.name}) — ${durationStr}`;

             if (isForm) forms.push(line);
             else if (isNegative) debuffs.push(line);
             else buffs.push(line);
        });
    });

    if (forms.length > 0) {
        text += "Активные Формы:\n" + forms.join('\n') + "\n\n";
    }

    if (buffs.length > 0) {
        text += "Активные Баффы:\n" + buffs.join('\n') + "\n\n";
    }

    if (debuffs.length > 0) {
        text += "Активные Ослабления:\n" + debuffs.join('\n') + "\n\n";
    }

    if (forms.length === 0 && buffs.length === 0 && debuffs.length === 0) {
        text += "(Нет активных боевых эффектов)\n\n";
    }

    text += "Перезарядка:\n";
    const battleCDs: string[] = [];
    sortedParticipants.forEach(p => {
        p.cooldowns.forEach(cd => {
             battleCDs.push(`${cd.name} (${p.profile.name}): ${formatCooldown(cd.name, cd.val, cd.unit)}`);
        });
    });

    if (battleCDs.length > 0) text += battleCDs.join('\n') + '\n';
    return text;
};

export const generateStatsText = (participants: BattleParticipant[]) => {
    // Sort for grouping
    const sortedParticipants = sortParticipants(participants);

    return sortedParticipants.map(p => {
        const lines = [];
        // Header: "Name (X ур.)"
        lines.push(`${p.profile.name} (${p.profile.level} ур.)`);

        // Stats - Hide (0) if 0
        const pT = p.battle_stats.trauma_phys;
        const mT = p.battle_stats.trauma_mag;
        const uT = p.battle_stats.trauma_uniq;

        lines.push(`Физическая характеристика: ${p.stats.phys}${pT !== 0 ? ` (${pT})` : ''}`);
        lines.push(`Магическая характеристика: ${p.stats.magic}${mT !== 0 ? ` (${mT})` : ''}`);
        lines.push(`Уникальная характеристика: ${p.stats.unique}${uT !== 0 ? ` (${uT})` : ''}`);

        // Passives - Filter strictly for 'Always'/'Passive' types AND combat-relevant
        const permanentPassives = p.flat_passives.filter(pas => {
            const t = (pas.trigger || '').toLowerCase().trim();
            const isPassiveType = !t || t === 'always' || t === 'passive' || t === 'пассивно' || t === 'всегда' || t === 'пассивно / всегда';
            return isPassiveType && !isNonCombat(pas.tags);
        });

        if (permanentPassives.length > 0) {
            lines.push(`> Пассивные эффекты:`);
            permanentPassives.forEach(pas => {
                lines.push(`* ${pas.name} (${pas.desc_mech || 'нет описания'})`);
            });
        }

        // Active Effects Logic
        const forms = [];
        const buffs = [];
        const debuffs = [];

        p.active_effects.forEach(e => {
            // Filter out non-combat effects
            if (isNonCombat(e.tags)) return;

            const isForm = (e.tags || []).some(t => t.toLowerCase().includes('form') || t.toLowerCase().includes('форма'));

            // Check for negative bonus to classify as debuff
            const isNegative = e.bonuses.some(b => b.val < 0);

            const line = `* ${e.name} (ост. ${formatDuration(e.duration_left, e.unit)})`;

            if (isForm) forms.push(line);
            else if (isNegative) debuffs.push(line);
            else buffs.push(line);
        });

        if (forms.length > 0) {
            lines.push(`> Формы:`);
            forms.forEach(l => lines.push(l));
        }

        if (buffs.length > 0) {
            lines.push(`> Баффы:`);
            buffs.forEach(l => lines.push(l));
        }

        if (debuffs.length > 0) {
            lines.push(`> Ослабления:`);
            debuffs.forEach(l => lines.push(l));
        }

        return lines.join('\n');
    }).join('\n\n\n');
};
